from __future__ import annotations

"""
Reusable Group 4 structural extractor.

This module consolidates the validated historical Group 4 CSV/PDF
discovery, audit, review-resolution, and structural extraction logic
into a report-level API.

Source policy:
    CSV exists -> CSV only
    otherwise PDF

No CSV/PDF field-level mixing is performed.
No semantic normalization or unit conversion is performed.
"""

import csv
import json
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

GROUP_NAME = "group4"
RULE_VERSION = "2.1"


@dataclass
class Group4ExtractionResult:
    source_format: str
    source_path: str
    series: list[dict] = field(default_factory=list)
    signals: list[dict] = field(default_factory=list)
    samples: list[dict] = field(default_factory=list)
    values: list[dict] = field(default_factory=list)
    companion_metadata: list[dict] = field(default_factory=list)
    graphical_review: list[dict] = field(default_factory=list)
    excluded: list[dict] = field(default_factory=list)
    unresolved: list[dict] = field(default_factory=list)
    issues: list[str] = field(default_factory=list)


def _load_csv_rows(path: Path):
    """
    Minimal replacement for the historical collection loader's row output.
    Returns the same first item consumed by Group 4 discovery plus placeholders.
    """
    with path.open("r", encoding="utf-8-sig", errors="replace", newline="") as f:
        rows = [list(row) for row in csv.reader(f)]
    return rows, None, None, None, None, []


def _strip_cli(source: str) -> str:
    return source


def _make_ns(name: str, source: str, extra: dict | None = None):
    ns = {"__name__": f"_embedded_{name}"}
    if extra:
        ns.update(extra)
    exec(compile(source, f"<embedded:{name}>", "exec"), ns)
    return ns

_CSV_DISCOVERY_SOURCE = '"""\nGroup 4 CSV discovery: Time-series measurements.\n\nPurpose\n-------\nDiscover all time-series-like structures directly from the original\nCISS/CDR CSV exports.\n\nThis is a discovery pass only.\n\nIt does NOT:\n- normalize signal semantics,\n- convert units,\n- infer missing time values,\n- merge different table families,\n- assign crash-event identities,\n- use PDF content,\n- replace source labels,\n- or build the final Group 4 dataset.\n\nThe objective is to identify all repeated/ordered measurement tables\npresent in CSV reports so that Group 4 extraction can later be built\nfrom the original CSV sources.\n\nOutputs\n-------\ntimeseries_candidate_sections.csv\ntimeseries_candidate_rows.csv\ntimeseries_family_summary.csv\nreport_coverage.csv\nreview_sections.csv\nerrors.csv\nmetadata.json\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport hashlib\nimport json\nimport re\n\nfrom collections import Counter, defaultdict\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\n\n\ncsv.field_size_limit(10_000_000)\n\n\nBASE = [\n    "report_id",\n    "case_id",\n    "vehicle_number",\n    "export_basename",\n]\n\n\n# ============================================================\n# I/O\n# ============================================================\n\ndef read_csv(path: Path):\n    with path.open(\n        encoding="utf-8-sig",\n        newline="",\n    ) as f:\n        return list(csv.DictReader(f))\n\n\ndef write_csv(\n    path: Path,\n    rows: list[dict],\n    columns: list[str],\n):\n    tmp = path.with_suffix(\n        path.suffix + ".part"\n    )\n\n    with tmp.open(\n        "w",\n        encoding="utf-8-sig",\n        newline="",\n    ) as f:\n        writer = csv.DictWriter(\n            f,\n            fieldnames=columns,\n        )\n        writer.writeheader()\n        writer.writerows(rows)\n\n    tmp.replace(path)\n\n\n# ============================================================\n# General helpers\n# ============================================================\n\ndef norm(value):\n    return re.sub(\n        r"\\s+",\n        " ",\n        str(value or "").strip(),\n    )\n\n\ndef norm_key(value):\n    value = norm(value).casefold()\n\n    return norm(\n        re.sub(\n            r"[^a-z0-9]+",\n            " ",\n            value,\n        )\n    )\n\n\ndef identifier(*parts):\n    text = "|".join(\n        str(part)\n        for part in parts\n    )\n\n    return hashlib.sha256(\n        text.encode()\n    ).hexdigest()[:24]\n\n\ndef resolve_path(\n    value,\n    source_root: Path,\n):\n    raw = norm(value)\n\n    if not raw:\n        return None\n\n    path = Path(raw)\n\n    if path.exists():\n        return path\n\n    candidate = (\n        source_root\n        / path\n    )\n\n    if candidate.exists():\n        return candidate\n\n    return None\n\n\ndef is_number(value):\n    text = norm(value)\n\n    if not text:\n        return False\n\n    return bool(\n        re.fullmatch(\n            r"[-+]?"\n            r"(?:\\d+(?:\\.\\d*)?|\\.\\d+)"\n            r"(?:[eE][-+]?\\d+)?",\n            text,\n        )\n    )\n\n\ndef is_na(value):\n    return (\n        norm(value).casefold()\n        in {\n            "n/a",\n            "na",\n            "not available",\n            "not applicable",\n            "sna",\n        }\n    )\n\n\ndef populated_cells(row):\n    return [\n        norm(cell)\n        for cell in row\n        if norm(cell)\n    ]\n\n\n# ============================================================\n# Section heading detection\n# ============================================================\n\nNON_SECTION_TEXT = {\n    "DATA LIMITATIONS",\n    "DISCLAIMER",\n    "COMMENTS",\n    "NOTES",\n}\n\n\ndef looks_like_heading(row):\n    """\n    Detect likely CSV section headings.\n\n    CDR exports commonly use rows containing one populated\n    all-uppercase cell as section boundaries.\n    """\n\n    filled = populated_cells(row)\n\n    if len(filled) != 1:\n        return False\n\n    text = filled[0]\n\n    if not text:\n        return False\n\n    if text.upper() in NON_SECTION_TEXT:\n        return True\n\n    if len(text) < 4:\n        return False\n\n    # Strong uppercase section pattern.\n    letters = [\n        char\n        for char in text\n        if char.isalpha()\n    ]\n\n    if letters and all(\n        char.isupper()\n        for char in letters\n    ):\n        return True\n\n    # Known structural section wording can sometimes\n    # contain mixed case.\n    if re.search(\n        r"\\b(?:"\n        r"pre[- ]?crash|"\n        r"crash pulse|"\n        r"event data|"\n        r"system status|"\n        r"pcm|"\n        r"rollover|"\n        r"deployment|"\n        r"longitudinal|"\n        r"lateral|"\n        r"acceleration|"\n        r"velocity change"\n        r")\\b",\n        text,\n        re.I,\n    ):\n        return True\n\n    return False\n\n\ndef segment_sections(rows):\n    """\n    Return:\n        [\n            {\n                heading,\n                start,\n                end,\n                rows\n            }\n        ]\n\n    start/end are zero-based source-row indexes.\n    """\n\n    headings = []\n\n    for index, row in enumerate(rows):\n\n        if looks_like_heading(row):\n            headings.append(\n                (\n                    index,\n                    populated_cells(row)[0],\n                )\n            )\n\n    sections = []\n\n    for pos, (\n        start,\n        heading,\n    ) in enumerate(headings):\n\n        end = (\n            headings[pos + 1][0]\n            if pos + 1 < len(headings)\n            else len(rows)\n        )\n\n        content = rows[\n            start + 1:end\n        ]\n\n        sections.append({\n            "heading":\n                heading,\n\n            "start":\n                start,\n\n            "end":\n                end,\n\n            "rows":\n                content,\n        })\n\n    return sections\n\n\n# ============================================================\n# Time-series evidence\n# ============================================================\n\nTIME_AXIS_PATTERNS = [\n    r"\\bseconds?\\s+before\\b",\n    r"\\bseconds?\\s+after\\b",\n    r"\\btime\\b",\n    r"\\brelative\\s+time\\b",\n    r"\\btime\\s*\\(s\\)",\n    r"\\btime\\s*\\(ms\\)",\n    r"\\bbuffer\\s+address\\b",\n    r"\\bsample\\s+number\\b",\n    r"\\bsample\\s+index\\b",\n]\n\n\nSIGNAL_PATTERNS = [\n    r"\\bvehicle\\s+speed\\b",\n    r"\\bengine\\s+speed\\b",\n    r"\\brpm\\b",\n    r"\\bthrottle\\b",\n    r"\\baccelerator\\b",\n    r"\\bbrake\\b",\n    r"\\bacceleration\\b",\n    r"\\bdelta[- ]?v\\b",\n    r"\\bvelocity\\s+change\\b",\n    r"\\blongitudinal\\b",\n    r"\\blateral\\b",\n    r"\\broll(?:over)?\\b",\n    r"\\byaw\\b",\n    r"\\bangular\\b",\n    r"\\bcrash\\s+pulse\\b",\n]\n\n\nHEADING_FAMILY_PATTERNS = [\n    (\n        "pcm_edr",\n        r"\\bPCM\\s+EDR\\s+DATA\\b",\n    ),\n\n    (\n        "pre_crash",\n        r"\\bPRE[- ]?CRASH\\b",\n    ),\n\n    (\n        "crash_pulse",\n        r"\\bCRASH\\s+PULSE\\b",\n    ),\n\n    (\n        "longitudinal",\n        r"\\bLONGITUDINAL\\b",\n    ),\n\n    (\n        "lateral",\n        r"\\bLATERAL\\b",\n    ),\n\n    (\n        "rollover",\n        r"\\bROLLOVER\\b",\n    ),\n\n    (\n        "velocity_change",\n        r"\\b(?:DELTA[- ]?V|VELOCITY\\s+CHANGE)\\b",\n    ),\n\n    (\n        "deployment_temporal",\n        r"\\bDEPLOYMENT\\b",\n    ),\n]\n\n\ndef detect_heading_family(heading):\n    for family, pattern in HEADING_FAMILY_PATTERNS:\n\n        if re.search(\n            pattern,\n            heading,\n            re.I,\n        ):\n            return family\n\n    return "generic_timeseries"\n\n\ndef row_text(row):\n    return norm(\n        " ".join(\n            norm(cell)\n            for cell in row\n            if norm(cell)\n        )\n    )\n\n\ndef header_time_axis_score(rows):\n    """\n    Search the first few meaningful rows for time/index\n    header evidence.\n    """\n\n    useful = [\n        row\n        for row in rows\n        if populated_cells(row)\n    ]\n\n    header_rows = useful[:6]\n\n    combined = " ".join(\n        row_text(row)\n        for row in header_rows\n    )\n\n    matches = [\n        pattern\n        for pattern\n        in TIME_AXIS_PATTERNS\n        if re.search(\n            pattern,\n            combined,\n            re.I,\n        )\n    ]\n\n    return (\n        len(matches),\n        matches,\n        combined,\n    )\n\n\ndef signal_header_score(rows):\n    useful = [\n        row\n        for row in rows\n        if populated_cells(row)\n    ]\n\n    combined = " ".join(\n        row_text(row)\n        for row in useful[:6]\n    )\n\n    matches = [\n        pattern\n        for pattern\n        in SIGNAL_PATTERNS\n        if re.search(\n            pattern,\n            combined,\n            re.I,\n        )\n    ]\n\n    return (\n        len(matches),\n        matches,\n    )\n\n\ndef numeric_leading_rows(rows):\n    """\n    Count rows where the first populated cell is numeric/N/A\n    and there is at least one additional populated cell.\n    """\n\n    result = []\n\n    for index, row in enumerate(rows):\n\n        filled = populated_cells(row)\n\n        if len(filled) < 2:\n            continue\n\n        if (\n            is_number(\n                filled[0]\n            )\n            or is_na(\n                filled[0]\n            )\n        ):\n            result.append(index)\n\n    return result\n\n\ndef repeated_width_evidence(rows):\n    """\n    Return evidence that multiple data rows share a repeated\n    populated-column count.\n    """\n\n    widths = []\n\n    for row in rows:\n        count = len(\n            populated_cells(row)\n        )\n\n        if count >= 2:\n            widths.append(count)\n\n    if not widths:\n        return (\n            0,\n            0,\n        )\n\n    counts = Counter(widths)\n\n    width, count = counts.most_common(1)[0]\n\n    return (\n        width,\n        count,\n    )\n\n\ndef detect_explicit_relative_time(rows):\n    """\n    Look for a likely relative-time column with actual numeric\n    values.\n\n    This is discovery only and does not identify final column\n    position.\n    """\n\n    useful = [\n        row\n        for row in rows\n        if populated_cells(row)\n    ]\n\n    for header_index, row in enumerate(\n        useful[:6]\n    ):\n\n        for cell_index, cell in enumerate(row):\n\n            text = norm(cell)\n\n            if not re.search(\n                r"\\b(?:relative\\s+time|seconds?\\s+(?:before|after)|time)\\b",\n                text,\n                re.I,\n            ):\n                continue\n\n            numeric_count = 0\n\n            for candidate in useful[\n                header_index + 1:\n                header_index + 12\n            ]:\n\n                if cell_index >= len(candidate):\n                    continue\n\n                value = norm(\n                    candidate[\n                        cell_index\n                    ]\n                )\n\n                if is_number(value):\n                    numeric_count += 1\n\n            if numeric_count >= 2:\n                return True\n\n    return False\n\n\ndef detect_buffer_axis(rows):\n\n    combined = " ".join(\n        row_text(row)\n        for row in rows[:6]\n    )\n\n    return bool(\n        re.search(\n            r"\\bbuffer\\s+address\\b",\n            combined,\n            re.I,\n        )\n    )\n\n\n# ============================================================\n# Candidate scoring\n# ============================================================\n\ndef analyze_section(\n    heading,\n    rows,\n):\n    """\n    Conservative candidate scoring.\n\n    A section is considered a time-series candidate when\n    multiple independent pieces of evidence support repeated\n    ordered measurements.\n    """\n\n    time_score, time_patterns, header_text = (\n        header_time_axis_score(\n            rows\n        )\n    )\n\n    signal_score, signal_patterns = (\n        signal_header_score(\n            rows\n        )\n    )\n\n    numeric_rows = numeric_leading_rows(\n        rows\n    )\n\n    modal_width, modal_width_count = (\n        repeated_width_evidence(\n            rows\n        )\n    )\n\n    explicit_time = (\n        detect_explicit_relative_time(\n            rows\n        )\n    )\n\n    buffer_axis = (\n        detect_buffer_axis(\n            rows\n        )\n    )\n\n    family = detect_heading_family(\n        heading\n    )\n\n    heading_temporal = (\n        family\n        != "generic_timeseries"\n    )\n\n    score = 0\n    reasons = []\n\n    if time_score:\n        score += 3\n        reasons.append(\n            "time_or_index_header"\n        )\n\n    if explicit_time:\n        score += 3\n        reasons.append(\n            "numeric_time_axis"\n        )\n\n    if buffer_axis:\n        score += 3\n        reasons.append(\n            "buffer_axis"\n        )\n\n    if len(numeric_rows) >= 2:\n        score += 2\n        reasons.append(\n            "repeated_numeric_leading_rows"\n        )\n\n    if modal_width_count >= 3:\n        score += 1\n        reasons.append(\n            "repeated_row_width"\n        )\n\n    if signal_score:\n        score += 1\n        reasons.append(\n            "measurement_signal_headers"\n        )\n\n    if heading_temporal:\n        score += 2\n        reasons.append(\n            "temporal_section_heading"\n        )\n\n    # Strong structural candidate.\n    candidate = (\n        score >= 5\n        and (\n            len(numeric_rows) >= 2\n            or buffer_axis\n        )\n    )\n\n    # Very strong explicit time axis should qualify even if\n    # numeric-leading rows are not in the first column.\n    if (\n        explicit_time\n        and modal_width_count >= 2\n    ):\n        candidate = True\n\n    # PCM buffer tables qualify structurally.\n    if (\n        family == "pcm_edr"\n        and buffer_axis\n    ):\n        candidate = True\n\n    # Sections close to threshold are retained for review.\n    review = (\n        not candidate\n        and score >= 3\n    )\n\n    if explicit_time:\n        time_axis_type = (\n            "relative_or_explicit_time"\n        )\n\n    elif buffer_axis:\n        time_axis_type = (\n            "buffer_order_or_relative_time"\n        )\n\n    elif len(numeric_rows) >= 2:\n        time_axis_type = (\n            "ordered_numeric_axis_candidate"\n        )\n\n    else:\n        time_axis_type = (\n            "unknown"\n        )\n\n    return {\n        "candidate":\n            candidate,\n\n        "review":\n            review,\n\n        "score":\n            score,\n\n        "family":\n            family,\n\n        "time_axis_type":\n            time_axis_type,\n\n        "explicit_time":\n            explicit_time,\n\n        "buffer_axis":\n            buffer_axis,\n\n        "time_header_match_count":\n            time_score,\n\n        "signal_header_match_count":\n            signal_score,\n\n        "numeric_leading_row_count":\n            len(\n                numeric_rows\n            ),\n\n        "numeric_leading_indexes":\n            numeric_rows,\n\n        "modal_populated_width":\n            modal_width,\n\n        "modal_width_row_count":\n            modal_width_count,\n\n        "reasons":\n            reasons,\n\n        "header_text":\n            header_text,\n    }\n\n\n# ============================================================\n# Main\n# ============================================================\n\ndef main():\n\n    parser = argparse.ArgumentParser(\n        description=__doc__\n    )\n\n    parser.add_argument(\n        "--index",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group1_v4/"\n            "report_index.csv"\n        ),\n    )\n\n    parser.add_argument(\n        "--source-root",\n        type=Path,\n        default=Path(\n            "data/temp"\n        ),\n    )\n\n    parser.add_argument(\n        "--output-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group4_csv_discovery_v1"\n        ),\n    )\n\n    parser.add_argument(\n        "--limit",\n        type=int,\n    )\n\n    args = parser.parse_args()\n\n    if (\n        args.limit is not None\n        and args.limit < 1\n    ):\n        parser.error(\n            "--limit must be positive"\n        )\n\n    index = read_csv(\n        args.index\n    )\n\n    selected = (\n        index[\n            :args.limit\n        ]\n        if args.limit\n        else index\n    )\n\n    # ========================================================\n    # Outputs\n    # ========================================================\n\n    candidate_sections = []\n    candidate_rows = []\n    review_sections = []\n    coverage = []\n    errors = []\n\n    # ========================================================\n    # Scan reports\n    # ========================================================\n\n    for number, report in enumerate(\n        selected,\n        1,\n    ):\n\n        base = {\n            key:\n                report.get(\n                    key,\n                    ""\n                )\n            for key in BASE\n        }\n\n        csv_path = resolve_path(\n            report.get(\n                "csv_path",\n                ""\n            ),\n            args.source_root,\n        )\n\n        if csv_path is None:\n\n            coverage.append({\n                **base,\n\n                "csv_available":\n                    False,\n\n                "csv_processed":\n                    False,\n\n                "section_count":\n                    0,\n\n                "timeseries_candidate_count":\n                    0,\n\n                "review_section_count":\n                    0,\n\n                "status":\n                    "no_csv_available",\n\n                "issue":\n                    "",\n            })\n\n            continue\n\n        try:\n            (\n                rows,\n                _,\n                _,\n                _,\n                _,\n                warnings,\n            ) = load_rows(\n                csv_path\n            )\n\n        except Exception as exc:\n\n            errors.append({\n                **base,\n\n                "source_path":\n                    str(\n                        csv_path\n                    ),\n\n                "error":\n                    (\n                        f"{type(exc).__name__}: "\n                        f"{exc}"\n                    ),\n            })\n\n            coverage.append({\n                **base,\n\n                "csv_available":\n                    True,\n\n                "csv_processed":\n                    False,\n\n                "section_count":\n                    0,\n\n                "timeseries_candidate_count":\n                    0,\n\n                "review_section_count":\n                    0,\n\n                "status":\n                    "csv_read_failed",\n\n                "issue":\n                    (\n                        f"{type(exc).__name__}: "\n                        f"{exc}"\n                    ),\n            })\n\n            continue\n\n        sections = segment_sections(\n            rows\n        )\n\n        report_candidate_count = 0\n        report_review_count = 0\n\n        for section_index, section in enumerate(\n            sections\n        ):\n\n            heading = section[\n                "heading"\n            ]\n\n            content = section[\n                "rows"\n            ]\n\n            analysis = analyze_section(\n                heading,\n                content,\n            )\n\n            if not (\n                analysis[\n                    "candidate"\n                ]\n                or analysis[\n                    "review"\n                ]\n            ):\n                continue\n\n            section_id = (\n                "g4csv_"\n                + identifier(\n                    base[\n                        "report_id"\n                    ],\n                    section[\n                        "start"\n                    ],\n                    heading,\n                )\n            )\n\n            common = {\n                **base,\n\n                "timeseries_candidate_id":\n                    section_id,\n\n                "source_path":\n                    str(\n                        csv_path\n                    ),\n\n                "source_heading":\n                    heading,\n\n                "source_record_start":\n                    section[\n                        "start"\n                    ]\n                    + 1,\n\n                "source_record_end":\n                    section[\n                        "end"\n                    ],\n\n                "candidate_family":\n                    analysis[\n                        "family"\n                    ],\n\n                "time_axis_type_candidate":\n                    analysis[\n                        "time_axis_type"\n                    ],\n\n                "discovery_score":\n                    analysis[\n                        "score"\n                    ],\n\n                "explicit_time_axis":\n                    analysis[\n                        "explicit_time"\n                    ],\n\n                "buffer_axis":\n                    analysis[\n                        "buffer_axis"\n                    ],\n\n                "time_header_match_count":\n                    analysis[\n                        "time_header_match_count"\n                    ],\n\n                "signal_header_match_count":\n                    analysis[\n                        "signal_header_match_count"\n                    ],\n\n                "numeric_leading_row_count":\n                    analysis[\n                        "numeric_leading_row_count"\n                    ],\n\n                "modal_populated_width":\n                    analysis[\n                        "modal_populated_width"\n                    ],\n\n                "modal_width_row_count":\n                    analysis[\n                        "modal_width_row_count"\n                    ],\n\n                "discovery_reasons":\n                    "|".join(\n                        analysis[\n                            "reasons"\n                        ]\n                    ),\n\n                "csv_warning_count":\n                    len(\n                        warnings\n                    ),\n            }\n\n            if analysis[\n                "candidate"\n            ]:\n\n                report_candidate_count += 1\n\n                candidate_sections.append({\n                    **common,\n\n                    "processing_status":\n                        "timeseries_candidate",\n\n                    "requires_review":\n                        True,\n\n                    "source_rows_json":\n                        json.dumps(\n                            content,\n                            ensure_ascii=False,\n                        ),\n                })\n\n                # Preserve every row in the candidate section.\n                for row_offset, row in enumerate(\n                    content\n                ):\n\n                    candidate_rows.append({\n                        **base,\n\n                        "timeseries_candidate_id":\n                            section_id,\n\n                        "source_heading":\n                            heading,\n\n                        "candidate_family":\n                            analysis[\n                                "family"\n                            ],\n\n                        "source_record":\n                            (\n                                section[\n                                    "start"\n                                ]\n                                + 2\n                                + row_offset\n                            ),\n\n                        "section_row_index":\n                            row_offset,\n\n                        "source_row_json":\n                            json.dumps(\n                                row,\n                                ensure_ascii=False,\n                            ),\n\n                        "populated_cell_count":\n                            len(\n                                populated_cells(\n                                    row\n                                )\n                            ),\n\n                        "first_populated_value":\n                            (\n                                populated_cells(\n                                    row\n                                )[0]\n                                if populated_cells(\n                                    row\n                                )\n                                else ""\n                            ),\n\n                        "numeric_leading_row":\n                            (\n                                bool(\n                                    populated_cells(\n                                        row\n                                    )\n                                )\n                                and (\n                                    is_number(\n                                        populated_cells(\n                                            row\n                                        )[0]\n                                    )\n                                    or is_na(\n                                        populated_cells(\n                                            row\n                                        )[0]\n                                    )\n                                )\n                            ),\n\n                        "requires_review":\n                            True,\n                    })\n\n            else:\n\n                report_review_count += 1\n\n                review_sections.append({\n                    **common,\n\n                    "processing_status":\n                        "near_threshold_review",\n\n                    "requires_review":\n                        True,\n\n                    "source_rows_json":\n                        json.dumps(\n                            content,\n                            ensure_ascii=False,\n                        ),\n                })\n\n        coverage.append({\n            **base,\n\n            "csv_available":\n                True,\n\n            "csv_processed":\n                True,\n\n            "section_count":\n                len(\n                    sections\n                ),\n\n            "timeseries_candidate_count":\n                report_candidate_count,\n\n            "review_section_count":\n                report_review_count,\n\n            "status":\n                (\n                    "timeseries_candidates_found"\n                    if report_candidate_count\n                    else "no_timeseries_candidates"\n                ),\n\n            "issue":\n                (\n                    f"csv_format_warnings:"\n                    f"{len(warnings)}"\n                    if warnings\n                    else ""\n                ),\n        })\n\n        if (\n            number % 25 == 0\n            or number\n            == len(selected)\n        ):\n            print(\n                "Discovered Group 4 CSV "\n                f"{number}/{len(selected)} reports...",\n                flush=True,\n            )\n\n    # ========================================================\n    # Family summary\n    # ========================================================\n\n    family_groups = defaultdict(\n        list\n    )\n\n    for row in candidate_sections:\n\n        family_groups[\n            row[\n                "candidate_family"\n            ]\n        ].append(\n            row\n        )\n\n    family_summary = []\n\n    for family, rows in sorted(\n        family_groups.items()\n    ):\n\n        headings = Counter(\n            row[\n                "source_heading"\n            ]\n            for row in rows\n        )\n\n        axis_types = Counter(\n            row[\n                "time_axis_type_candidate"\n            ]\n            for row in rows\n        )\n\n        report_ids = {\n            row[\n                "report_id"\n            ]\n            for row in rows\n        }\n\n        family_summary.append({\n            "candidate_family":\n                family,\n\n            "section_count":\n                len(rows),\n\n            "report_count":\n                len(\n                    report_ids\n                ),\n\n            "heading_count":\n                len(\n                    headings\n                ),\n\n            "top_headings_json":\n                json.dumps(\n                    headings.most_common(\n                        20\n                    ),\n                    ensure_ascii=False,\n                ),\n\n            "time_axis_type_counts_json":\n                json.dumps(\n                    dict(\n                        axis_types\n                    ),\n                    ensure_ascii=False,\n                ),\n        })\n\n    # ========================================================\n    # Metadata\n    # ========================================================\n\n    reports_with_csv = sum(\n        1\n        for row in coverage\n        if str(\n            row[\n                "csv_available"\n            ]\n        ).casefold()\n        == "true"\n    )\n\n    reports_processed = sum(\n        1\n        for row in coverage\n        if str(\n            row[\n                "csv_processed"\n            ]\n        ).casefold()\n        == "true"\n    )\n\n    reports_with_candidates = sum(\n        1\n        for row in coverage\n        if (\n            int(\n                row[\n                    "timeseries_candidate_count"\n                ]\n            )\n            > 0\n        )\n    )\n\n    candidate_family_counts = Counter(\n        row[\n            "candidate_family"\n        ]\n        for row in candidate_sections\n    )\n\n    time_axis_counts = Counter(\n        row[\n            "time_axis_type_candidate"\n        ]\n        for row in candidate_sections\n    )\n\n    heading_counts = Counter(\n        row[\n            "source_heading"\n        ]\n        for row in candidate_sections\n    )\n\n    coverage_status_counts = Counter(\n        row[\n            "status"\n        ]\n        for row in coverage\n    )\n\n    metadata = {\n\n        "created_at":\n            datetime.now(\n                timezone.utc\n            ).isoformat(),\n\n        "group":\n            "Group 4 - Time-series measurements",\n\n        "stage":\n            "CSV discovery",\n\n        "reports_in_index":\n            len(\n                selected\n            ),\n\n        "reports_with_csv":\n            reports_with_csv,\n\n        "reports_csv_processed":\n            reports_processed,\n\n        "reports_with_timeseries_candidates":\n            reports_with_candidates,\n\n        "candidate_section_count":\n            len(\n                candidate_sections\n            ),\n\n        "candidate_row_count":\n            len(\n                candidate_rows\n            ),\n\n        "near_threshold_review_section_count":\n            len(\n                review_sections\n            ),\n\n        "candidate_family_counts":\n            dict(\n                candidate_family_counts\n            ),\n\n        "time_axis_type_counts":\n            dict(\n                time_axis_counts\n            ),\n\n        "unique_candidate_headings":\n            len(\n                heading_counts\n            ),\n\n        "top_candidate_headings":\n            heading_counts.most_common(\n                30\n            ),\n\n        "coverage_status_counts":\n            dict(\n                coverage_status_counts\n            ),\n\n        "source_errors":\n            len(\n                errors\n            ),\n\n        "scope":\n            (\n                "CSV-first discovery for Group 4 time-series "\n                "measurements. Original CSV sources are scanned "\n                "directly for repeated ordered measurement tables. "\n                "Candidate detection uses structural evidence "\n                "including time/index headers, numeric sample rows, "\n                "buffer axes, repeated row widths, measurement "\n                "headers, and temporal section headings. This stage "\n                "does not perform semantic normalization, unit "\n                "conversion, event identity inference, PDF fallback, "\n                "or final time-series extraction."\n            ),\n    }\n\n    # ========================================================\n    # Write outputs\n    # ========================================================\n\n    out = (\n        args.output_directory\n    )\n\n    out.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    section_columns = [\n        *BASE,\n        "timeseries_candidate_id",\n        "source_path",\n        "source_heading",\n        "source_record_start",\n        "source_record_end",\n        "candidate_family",\n        "time_axis_type_candidate",\n        "discovery_score",\n        "explicit_time_axis",\n        "buffer_axis",\n        "time_header_match_count",\n        "signal_header_match_count",\n        "numeric_leading_row_count",\n        "modal_populated_width",\n        "modal_width_row_count",\n        "discovery_reasons",\n        "csv_warning_count",\n        "processing_status",\n        "requires_review",\n        "source_rows_json",\n    ]\n\n    write_csv(\n        out\n        / "timeseries_candidate_sections.csv",\n        candidate_sections,\n        section_columns,\n    )\n\n    write_csv(\n        out\n        / "timeseries_candidate_rows.csv",\n        candidate_rows,\n        [\n            *BASE,\n            "timeseries_candidate_id",\n            "source_heading",\n            "candidate_family",\n            "source_record",\n            "section_row_index",\n            "source_row_json",\n            "populated_cell_count",\n            "first_populated_value",\n            "numeric_leading_row",\n            "requires_review",\n        ],\n    )\n\n    write_csv(\n        out\n        / "review_sections.csv",\n        review_sections,\n        section_columns,\n    )\n\n    write_csv(\n        out\n        / "timeseries_family_summary.csv",\n        family_summary,\n        [\n            "candidate_family",\n            "section_count",\n            "report_count",\n            "heading_count",\n            "top_headings_json",\n            "time_axis_type_counts_json",\n        ],\n    )\n\n    write_csv(\n        out\n        / "report_coverage.csv",\n        coverage,\n        [\n            *BASE,\n            "csv_available",\n            "csv_processed",\n            "section_count",\n            "timeseries_candidate_count",\n            "review_section_count",\n            "status",\n            "issue",\n        ],\n    )\n\n    write_csv(\n        out\n        / "errors.csv",\n        errors,\n        [\n            *BASE,\n            "source_path",\n            "error",\n        ],\n    )\n\n    metadata_tmp = (\n        out\n        / "metadata.json.part"\n    )\n\n    metadata_tmp.write_text(\n        json.dumps(\n            metadata,\n            indent=2,\n        ),\n        encoding="utf-8",\n    )\n\n    metadata_tmp.replace(\n        out\n        / "metadata.json"\n    )\n\n    print(\n        json.dumps(\n            metadata,\n            indent=2,\n        )\n    )\n\n    print(\n        f"Outputs: {out}"\n    )\n\n\n'

_CSV_AUDIT_SOURCE = '"""\nAudit and clean Group 4 CSV time-series discovery candidates.\n\nThis stage operates on the discovery outputs only. It does NOT reread\nthe original CSV reports.\n\nIt combines:\n    timeseries_candidate_sections.csv\n    review_sections.csv\n\nand classifies sections into:\n\n1. accepted time-series sections\n2. companion metadata for time-series sections\n3. excluded known non-time-series structures\n4. residual review sections\n\nTwo structural orientations are recognized:\n\nA. samples_by_rows\n   Time | Signal A | Signal B\n   -5   | ...\n   -4   | ...\n\nB. samples_by_columns\n   Time       | -5 | -4 | -3\n   Speed      | ...\n   Brake      | ...\n\nNo signal semantics, units, event identities, or values are normalized.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport json\nimport re\n\nfrom collections import Counter, defaultdict\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\n\ncsv.field_size_limit(10_000_000)\n\n\nBASE = [\n    "report_id",\n    "case_id",\n    "vehicle_number",\n    "export_basename",\n]\n\n\n# ============================================================\n# I/O\n# ============================================================\n\ndef read_csv(path: Path):\n    with path.open(\n        encoding="utf-8-sig",\n        newline="",\n    ) as f:\n        return list(csv.DictReader(f))\n\n\ndef write_csv(\n    path: Path,\n    rows: list[dict],\n    columns: list[str],\n):\n    tmp = path.with_suffix(\n        path.suffix + ".part"\n    )\n\n    with tmp.open(\n        "w",\n        encoding="utf-8-sig",\n        newline="",\n    ) as f:\n        writer = csv.DictWriter(\n            f,\n            fieldnames=columns,\n        )\n        writer.writeheader()\n        writer.writerows(rows)\n\n    tmp.replace(path)\n\n\n# ============================================================\n# Helpers\n# ============================================================\ndef is_crash_pulse_scalar_companion(\n    heading,\n    rows,\n):\n    """\n    Identify crash-pulse sections that contain scalar metadata\n    describing a time-series record but do not contain sampled\n    measurements themselves.\n    """\n\n    if "CRASH PULSE" not in heading.upper():\n        return False\n\n    useful_rows = [\n        populated(row)\n        for row in rows\n        if populated(row)\n    ]\n\n    if not useful_rows:\n        return False\n\n    max_width = max(\n        len(row)\n        for row in useful_rows\n    )\n\n    # Scalar field/value structures only.\n    if max_width > 2:\n        return False\n\n    text = " ".join(\n        " ".join(row)\n        for row in useful_rows\n    )\n\n    metadata_patterns = [\n        r"Recording Status.*Time Series",\n        r"Time from TRG to Next Sample",\n        r"Maximum Delta-V",\n        r"Time,\\s*Maximum Delta-V",\n        r"Clipping Time",\n        r"Length of Delta-V",\n        r"RollAngle Peak",\n        r"Roll Angle at the Time of TRG",\n    ]\n\n    return any(\n        re.search(\n            pattern,\n            text,\n            re.I,\n        )\n        for pattern in metadata_patterns\n    )\ndef norm(value):\n    return re.sub(\n        r"\\s+",\n        " ",\n        str(value or "").strip(),\n    )\n\n\ndef load_rows(value):\n    try:\n        parsed = json.loads(value)\n\n        if isinstance(parsed, list):\n            return parsed\n\n    except (\n        json.JSONDecodeError,\n        TypeError,\n    ):\n        pass\n\n    return []\n\n\ndef populated(row):\n    return [\n        norm(value)\n        for value in row\n        if norm(value)\n    ]\n\n\ndef clean_numeric_token(value):\n    """\n    Normalize formatting only for structural detection.\n\n    Examples:\n        "- 5.0" -> "-5.0"\n        "+ 2"   -> "+2"\n\n    Original source values are never changed in outputs.\n    """\n\n    text = norm(value)\n\n    text = re.sub(\n        r"^([+-])\\s+",\n        r"\\1",\n        text,\n    )\n\n    text = text.replace(\n        ",",\n        "",\n    )\n\n    return text\n\n\ndef is_numeric(value):\n    text = clean_numeric_token(\n        value\n    )\n\n    return bool(\n        re.fullmatch(\n            r"[-+]?"\n            r"(?:\\d+(?:\\.\\d*)?|\\.\\d+)"\n            r"(?:[eE][-+]?\\d+)?",\n            text,\n        )\n    )\n\n\ndef is_time_value(value):\n    """\n    Allow simple annotation after a numeric time value.\n\n    Examples:\n        0 (TRG)\n        -5.0\n        100\n    """\n\n    text = norm(value)\n\n    text = re.sub(\n        r"\\([^)]*\\)\\s*$",\n        "",\n        text,\n    )\n\n    return is_numeric(\n        text\n    )\n\n\n# ============================================================\n# Structural evidence\n# ============================================================\n\ndef count_sample_rows(rows):\n    """\n    Samples-by-rows orientation.\n\n    Count rows with:\n    - at least two populated cells\n    - numeric first populated cell\n    """\n\n    count = 0\n\n    for row in rows:\n\n        values = populated(\n            row\n        )\n\n        if len(values) < 2:\n            continue\n\n        if is_numeric(\n            values[0]\n        ):\n            count += 1\n\n    return count\n\n\ndef detect_transposed_time_axis(rows):\n    """\n    Detect samples-by-columns orientation.\n\n    Supports both explicit time coordinates and ordered sample counts.\n\n    Examples:\n\n        Time (sec)      -5  -4  -3  -2\n        Vehicle Speed   ...\n\n    or\n\n        Pre-Crash Sample Count from TRG\n                        -5 count  -4 count ... 0 (TRG)\n        Vehicle Speed   ...\n    """\n\n    for row_index, row in enumerate(rows[:8]):\n\n        if not row:\n            continue\n\n        first = norm(\n            row[0]\n            if row\n            else ""\n        )\n\n        # ----------------------------------------------------\n        # Explicit time axis\n        # ----------------------------------------------------\n\n        explicit_time_header = bool(\n            re.search(\n                r"\\b(?:"\n                r"time|"\n                r"seconds?|"\n                r"sec|"\n                r"msec|"\n                r"ms"\n                r")\\b",\n                first,\n                re.I,\n            )\n        )\n\n        # ----------------------------------------------------\n        # Relative sample-count axis\n        # ----------------------------------------------------\n\n        sample_count_header = bool(\n            re.search(\n                r"\\bsample\\s+count\\b",\n                first,\n                re.I,\n            )\n            and re.search(\n                r"\\bTRG\\b",\n                first,\n                re.I,\n            )\n        )\n\n        if not (\n            explicit_time_header\n            or sample_count_header\n        ):\n            continue\n\n        sample_values = [\n            value\n            for value in row[1:]\n            if norm(value)\n        ]\n\n        valid_count = 0\n\n        for value in sample_values:\n\n            text = norm(value)\n\n            # Remove trigger annotation.\n            text = re.sub(\n                r"\\([^)]*\\)\\s*$",\n                "",\n                text,\n            )\n\n            # Remove "count" suffix.\n            text = re.sub(\n                r"\\s*count\\s*$",\n                "",\n                text,\n                flags=re.I,\n            )\n\n            if is_numeric(text):\n                valid_count += 1\n\n        if valid_count >= 2:\n\n            axis_type = (\n                "sample_count_relative_to_trigger"\n                if sample_count_header\n                else "explicit_time"\n            )\n\n            return (\n                True,\n                row_index,\n                valid_count,\n                axis_type,\n            )\n\n    return (\n        False,\n        "",\n        0,\n        "",\n    )\n\ndef detect_buffer_axis(rows):\n    """\n    PCM-style ordered buffer table.\n    """\n\n    text = " ".join(\n        " ".join(\n            populated(row)\n        )\n        for row\n        in rows[:6]\n    )\n\n    return bool(\n        re.search(\n            r"\\bbuffer\\s+address\\b",\n            text,\n            re.I,\n        )\n    )\n\n\n# ============================================================\n# Known exclusions / companion metadata\n# ============================================================\n\ndef classify_known_non_timeseries(\n    heading,\n):\n    h = (\n        heading\n        .upper()\n        .replace(\n            "_",\n            "-",\n        )\n    )\n\n    if (\n        "EVENT RECORD SUMMARY"\n        in h\n    ):\n        return (\n            "excluded_group2_summary",\n            "Event record summary is a Group 2 record/retrieval structure, not a time series.",\n        )\n\n    if re.search(\n        r"\\bDTCS?\\s+PRESENT\\b",\n        h,\n    ):\n        return (\n            "excluded_dtc_structure",\n            "DTC/PID structure is not a temporal measurement sequence.",\n        )\n\n    if (\n        "DEPLOYMENT COMMAND DATA"\n        in h\n        or re.match(\n            r"^DEPLOYMENT DATA\\b",\n            h,\n        )\n    ):\n        return (\n            "excluded_deployment_scalar",\n            "Deployment timing/status fields are scalar event information rather than repeated samples.",\n        )\n\n    if (\n        "SYSTEM STATUS"\n        in h\n        or "SYSTEM CONFIGURATION"\n        in h\n    ):\n        return (\n            "excluded_status_configuration",\n            "System status/configuration table is scalar/contextual information.",\n        )\n\n    if (\n        "1 SAMPLE"\n        in h\n        or re.search(\n            r"\\bPRE-CRASH DATA -1 SEC\\b",\n            h,\n        )\n    ):\n        return (\n            "excluded_single_snapshot",\n            "Single pre-crash snapshot is not treated as a repeated time series.",\n        )\n\n    return (\n        "",\n        "",\n    )\n\n\ndef is_companion_metadata(\n    heading,\n):\n    h = heading.upper()\n\n    # Common CDR pattern:\n    # table 1 contains metadata/status,\n    # table 2 contains actual sampled pulse data.\n    if (\n        "CRASH PULSE"\n        in h\n        and "TABLE 1 OF 2"\n        in h\n    ):\n        return True\n\n    return False\n\n\n# ============================================================\n# Family/component routing\n# ============================================================\n\ndef structural_family(\n    heading,\n):\n    h = (\n        heading\n        .upper()\n        .replace(\n            "_",\n            "-",\n        )\n    )\n\n    # Order matters.\n\n    if "PCM EDR DATA" in h:\n        return "pcm_edr"\n\n    if re.search(\n        r"\\bPRE-CRASH\\b",\n        h,\n    ):\n        return "pre_crash"\n\n    if re.search(\n        r"\\bPOST-CRASH\\b",\n        h,\n    ):\n        return "post_crash"\n\n    if "CRASH PULSE" in h:\n        return "crash_pulse"\n\n    if re.search(\n        r"\\bDELTA[- ]?V\\b",\n        h,\n    ) or re.search(\n        r"\\bVELOCITY CHANGE\\b",\n        h,\n    ):\n        return "delta_v"\n\n    if "ROLL ANGLE" in h:\n        return "roll_angle"\n\n    if re.search(\n        r"\\bROLL RATE\\b",\n        h,\n    ) or re.search(\n        r"\\bANGULAR RATE\\b",\n        h,\n    ):\n        return "angular_rate"\n\n    if "ACCELERATION" in h:\n        return "acceleration"\n\n    if (\n        "PERIPHERAL SENSOR"\n        in h\n        or "PRESSURE SENSOR"\n        in h\n        or "SATELLITE SENSOR"\n        in h\n        or "LOW-G Z"\n        in h\n    ):\n        return "sensor_timeseries"\n\n    if "ROLLOVER SENSOR DATA" in h:\n        return "rollover_sensor"\n\n    if re.search(\n        r"\\bVEHICLE\\s+LONGITUDINAL\\s+VELOCITY\\b",\n        h,\n    ):\n        return "velocity"\n\n    return "other_timeseries"\n\n\ndef component(\n    heading,\n):\n    h = heading.upper()\n\n    has_longitudinal = (\n        "LONGITUDINAL"\n        in h\n    )\n\n    has_lateral = (\n        "LATERAL"\n        in h\n    )\n\n    if (\n        has_longitudinal\n        and has_lateral\n    ):\n        return "longitudinal_lateral"\n\n    if has_longitudinal:\n        return "longitudinal"\n\n    if has_lateral:\n        return "lateral"\n\n    if (\n        "NORMAL"\n        in h\n        or "VERTICAL"\n        in h\n        or "LOW-G Z"\n        in h\n    ):\n        return "normal_vertical"\n\n    if (\n        "ROLL"\n        in h\n        or "ANGULAR"\n        in h\n    ):\n        return "roll_angular"\n\n    if re.search(\n        r"\\bSENSOR X\\b",\n        h,\n    ):\n        return "x"\n\n    if re.search(\n        r"\\bSENSOR Y\\b",\n        h,\n    ):\n        return "y"\n\n    return "unspecified"\n\n\n# ============================================================\n# Main classification\n# ============================================================\n\ndef audit_row(\n    row,\n    discovery_origin,\n):\n    heading = norm(\n        row.get(\n            "source_heading",\n            "",\n        )\n    )\n\n    rows = load_rows(\n        row.get(\n            "source_rows_json",\n            "",\n        )\n    )\n\n    sample_row_count = (\n        count_sample_rows(\n            rows\n        )\n    )\n\n    (\n        transposed,\n        transposed_time_row,\n        transposed_sample_count,\n        transposed_axis_type,\n    ) = detect_transposed_time_axis(\n        rows\n    )\n\n    buffer_axis = (\n        detect_buffer_axis(\n            rows\n        )\n    )\n\n    exclusion_status, exclusion_reason = (\n        classify_known_non_timeseries(\n            heading\n        )\n    )\n\n    family = structural_family(\n        heading\n    )\n\n    axis_component = component(\n        heading\n    )\n\n    orientation = ""\n\n    if buffer_axis:\n        orientation = (\n            "buffer_order_table"\n        )\n\n    elif sample_row_count >= 2:\n        orientation = (\n            "samples_by_rows"\n        )\n\n    elif transposed:\n        orientation = (\n            "samples_by_columns"\n        )\n\n    # --------------------------------------------------------\n    # Known exclusions have priority.\n    # --------------------------------------------------------\n\n    if exclusion_status:\n\n        final_status = (\n            exclusion_status\n        )\n\n        decision = (\n            "exclude_from_group4"\n        )\n\n        reason = (\n            exclusion_reason\n        )\n\n    # --------------------------------------------------------\n    # Companion metadata is retained separately.\n    # --------------------------------------------------------\n\n    elif is_companion_metadata(\n        heading\n    ):\n\n        final_status = (\n            "timeseries_companion_metadata"\n        )\n\n        decision = (\n            "preserve_as_companion_metadata"\n        )\n\n        reason = (\n            "Crash-pulse Table 1 of 2 appears to contain "\n            "metadata/status associated with the sampled table."\n        )\n    elif is_crash_pulse_scalar_companion(\n        heading,\n        rows,\n    ):\n\n        final_status = (\n            "timeseries_companion_metadata"\n        )\n\n        decision = (\n            "preserve_as_companion_metadata"\n        )\n\n        reason = (\n            "Crash-pulse section contains scalar metadata "\n            "describing the associated sampled time-series record, "\n            "but does not itself contain repeated measurements."\n        )\n    # --------------------------------------------------------\n    # PCM accepted through structural buffer evidence.\n    # --------------------------------------------------------\n\n    elif (\n        family\n        == "pcm_edr"\n        and buffer_axis\n    ):\n\n        final_status = (\n            "accepted_timeseries"\n        )\n\n        decision = (\n            "accept"\n        )\n\n        reason = (\n            "PCM EDR table contains an ordered buffer/time structure."\n        )\n\n    # --------------------------------------------------------\n    # Ordinary samples-down-rows tables.\n    # --------------------------------------------------------\n\n    elif sample_row_count >= 2:\n\n        final_status = (\n            "accepted_timeseries"\n        )\n\n        decision = (\n            "accept"\n        )\n\n        reason = (\n            "At least two repeated numeric-axis sample rows were detected."\n        )\n\n    # --------------------------------------------------------\n    # Transposed time-series tables.\n    # --------------------------------------------------------\n\n    elif transposed:\n\n        final_status = (\n            "accepted_timeseries"\n        )\n\n        decision = (\n            "accept"\n        )\n\n        reason = (\n            "A time-axis row with multiple sample coordinates "\n            "was detected across columns."\n        )\n\n    # --------------------------------------------------------\n    # Everything else remains visible for review.\n    # --------------------------------------------------------\n\n    else:\n\n        final_status = (\n            "requires_structural_review"\n        )\n\n        decision = (\n            "review"\n        )\n\n        reason = (\n            "Heading suggests possible temporal content, but repeated "\n            "sample structure was not demonstrated conservatively."\n        )\n\n    return {\n        **row,\n\n        "discovery_origin":\n            discovery_origin,\n\n        "audit_decision":\n            decision,\n            \n        "transposed_axis_type":\n            transposed_axis_type,\n\n        "audit_status":\n            final_status,\n\n        "audit_reason":\n            reason,\n\n        "audited_family":\n            family,\n\n        "audited_component":\n            axis_component,\n\n        "table_orientation":\n            orientation,\n\n        "sample_row_count":\n            sample_row_count,\n\n        "transposed_time_axis":\n            transposed,\n\n        "transposed_time_row_index":\n            transposed_time_row,\n\n        "transposed_sample_count":\n            transposed_sample_count,\n\n        "audited_buffer_axis":\n            buffer_axis,\n    }\n\n\n# ============================================================\n# Main\n# ============================================================\n\ndef main():\n\n    parser = argparse.ArgumentParser(\n        description=__doc__\n    )\n\n    parser.add_argument(\n        "--discovery-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group4_csv_discovery_v1"\n        ),\n    )\n\n    parser.add_argument(\n        "--output-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group4_csv_audit_v1"\n        ),\n    )\n\n    args = parser.parse_args()\n\n    discovery = (\n        args.discovery_directory\n    )\n\n    candidate_path = (\n        discovery\n        / "timeseries_candidate_sections.csv"\n    )\n\n    review_path = (\n        discovery\n        / "review_sections.csv"\n    )\n\n    if not candidate_path.exists():\n        raise FileNotFoundError(\n            candidate_path\n        )\n\n    if not review_path.exists():\n        raise FileNotFoundError(\n            review_path\n        )\n\n    candidates = read_csv(\n        candidate_path\n    )\n\n    reviews = read_csv(\n        review_path\n    )\n\n    audited = []\n\n    for row in candidates:\n        audited.append(\n            audit_row(\n                row,\n                "discovery_candidate",\n            )\n        )\n\n    for row in reviews:\n        audited.append(\n            audit_row(\n                row,\n                "near_threshold_review",\n            )\n        )\n\n    accepted = [\n        row\n        for row in audited\n        if row[\n            "audit_decision"\n        ]\n        == "accept"\n    ]\n\n    companion = [\n        row\n        for row in audited\n        if row[\n            "audit_decision"\n        ]\n        == "preserve_as_companion_metadata"\n    ]\n\n    excluded = [\n        row\n        for row in audited\n        if row[\n            "audit_decision"\n        ]\n        == "exclude_from_group4"\n    ]\n\n    remaining_review = [\n        row\n        for row in audited\n        if row[\n            "audit_decision"\n        ]\n        == "review"\n    ]\n\n    # ========================================================\n    # Family summary\n    # ========================================================\n\n    family_groups = defaultdict(\n        list\n    )\n\n    for row in accepted:\n        family_groups[\n            (\n                row[\n                    "audited_family"\n                ],\n                row[\n                    "audited_component"\n                ],\n                row[\n                    "table_orientation"\n                ],\n            )\n        ].append(\n            row\n        )\n\n    family_summary = []\n\n    for (\n        family,\n        component_name,\n        orientation,\n    ), rows in sorted(\n        family_groups.items()\n    ):\n\n        headings = Counter(\n            row[\n                "source_heading"\n            ]\n            for row in rows\n        )\n\n        report_ids = {\n            row[\n                "report_id"\n            ]\n            for row in rows\n        }\n\n        family_summary.append({\n            "audited_family":\n                family,\n\n            "audited_component":\n                component_name,\n\n            "table_orientation":\n                orientation,\n\n            "section_count":\n                len(rows),\n\n            "report_count":\n                len(\n                    report_ids\n                ),\n\n            "unique_heading_count":\n                len(\n                    headings\n                ),\n\n            "top_headings_json":\n                json.dumps(\n                    headings.most_common(\n                        30\n                    ),\n                    ensure_ascii=False,\n                ),\n        })\n\n    # ========================================================\n    # Summary metadata\n    # ========================================================\n\n    decision_counts = Counter(\n        row[\n            "audit_decision"\n        ]\n        for row in audited\n    )\n\n    status_counts = Counter(\n        row[\n            "audit_status"\n        ]\n        for row in audited\n    )\n\n    family_counts = Counter(\n        row[\n            "audited_family"\n        ]\n        for row in accepted\n    )\n\n    component_counts = Counter(\n        row[\n            "audited_component"\n        ]\n        for row in accepted\n    )\n\n    orientation_counts = Counter(\n        row[\n            "table_orientation"\n        ]\n        for row in accepted\n    )\n\n    origin_counts = Counter(\n        row[\n            "discovery_origin"\n        ]\n        for row in accepted\n    )\n\n    # ========================================================\n    # Output\n    # ========================================================\n\n    out = (\n        args.output_directory\n    )\n\n    out.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    audit_columns = list(\n        audited[0].keys()\n    )\n\n    write_csv(\n        out\n        / "all_section_audit.csv",\n        audited,\n        audit_columns,\n    )\n\n    write_csv(\n        out\n        / "accepted_timeseries_sections.csv",\n        accepted,\n        audit_columns,\n    )\n\n    write_csv(\n        out\n        / "timeseries_companion_metadata_sections.csv",\n        companion,\n        audit_columns,\n    )\n\n    write_csv(\n        out\n        / "excluded_non_timeseries_sections.csv",\n        excluded,\n        audit_columns,\n    )\n\n    write_csv(\n        out\n        / "remaining_review_sections.csv",\n        remaining_review,\n        audit_columns,\n    )\n\n    write_csv(\n        out\n        / "accepted_family_summary.csv",\n        family_summary,\n        [\n            "audited_family",\n            "audited_component",\n            "table_orientation",\n            "section_count",\n            "report_count",\n            "unique_heading_count",\n            "top_headings_json",\n        ],\n    )\n\n    metadata = {\n\n        "created_at":\n            datetime.now(\n                timezone.utc\n            ).isoformat(),\n\n        "group":\n            "Group 4 - Time-series measurements",\n\n        "stage":\n            "CSV candidate audit",\n\n        "input_discovery_candidates":\n            len(\n                candidates\n            ),\n\n        "input_near_threshold_reviews":\n            len(\n                reviews\n            ),\n\n        "total_sections_audited":\n            len(\n                audited\n            ),\n\n        "accepted_timeseries_sections":\n            len(\n                accepted\n            ),\n\n        "companion_metadata_sections":\n            len(\n                companion\n            ),\n\n        "excluded_non_timeseries_sections":\n            len(\n                excluded\n            ),\n\n        "remaining_review_sections":\n            len(\n                remaining_review\n            ),\n\n        "decision_counts":\n            dict(\n                decision_counts\n            ),\n\n        "status_counts":\n            dict(\n                status_counts\n            ),\n\n        "accepted_family_counts":\n            dict(\n                family_counts\n            ),\n\n        "accepted_component_counts":\n            dict(\n                component_counts\n            ),\n\n        "accepted_orientation_counts":\n            dict(\n                orientation_counts\n            ),\n\n        "accepted_origin_counts":\n            dict(\n                origin_counts\n            ),\n\n        "scope":\n            (\n                "Conservative audit of Group 4 CSV discovery outputs. "\n                "Known non-time-series structures are explicitly "\n                "excluded; crash-pulse companion metadata is preserved "\n                "separately; repeated numeric-axis tables and transposed "\n                "time-axis tables are accepted as time-series candidates. "\n                "No signal normalization, unit conversion, event identity "\n                "inference, or final sample extraction is performed."\n            ),\n    }\n\n    metadata_tmp = (\n        out\n        / "metadata.json.part"\n    )\n\n    metadata_tmp.write_text(\n        json.dumps(\n            metadata,\n            indent=2,\n        ),\n        encoding="utf-8",\n    )\n\n    metadata_tmp.replace(\n        out\n        / "metadata.json"\n    )\n\n    print(\n        json.dumps(\n            metadata,\n            indent=2,\n        )\n    )\n\n    print(\n        f"Outputs: {out}"\n    )\n\n\n'

_CSV_EXTRACT_SOURCE = '"""\nBuild structured Group 4 CSV time-series datasets.\n\nInput\n-----\ndata/processed/edr/group4_csv_audit_v1/\n    accepted_timeseries_sections.csv\n    timeseries_companion_metadata_sections.csv\n\nOutput\n------\ndata/processed/edr/group4_csv_structured_v1/\n    timeseries_registry.csv\n    timeseries_signal_registry.csv\n    timeseries_samples_wide.csv\n    timeseries_values_long.csv\n    timeseries_companion_metadata.csv\n    timeseries_audit.csv\n    extraction_failures.csv\n    validation_report.csv\n    metadata.json\n\nScope\n-----\nThis is a STRUCTURAL extraction stage.\n\nThe script:\n- extracts accepted CSV time-series sections,\n- supports samples-by-rows,\n- supports samples-by-columns,\n- supports PCM/buffer-order tables,\n- trims raw PID/hex payloads beginning at PIDsStart,\n- re-detects transposed tables after trimming PID tails,\n- uses the section heading as the signal identity for single-signal\n  tables whose column header contains only a unit,\n- preserves raw source labels,\n- preserves raw units,\n- preserves raw axis values,\n- preserves source provenance,\n- preserves missing/N/A/SNA values,\n- preserves companion metadata separately.\n\nThe script does NOT:\n- semantically normalize signal names,\n- convert units,\n- invent missing time values,\n- infer crash-event identities,\n- merge signals across manufacturers,\n- use PDF data,\n- or classify signals into biomechanical meaning.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport hashlib\nimport json\nimport math\nimport re\n\nfrom collections import Counter\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\n\ncsv.field_size_limit(50_000_000)\n\n\nBASE = [\n    "report_id",\n    "case_id",\n    "vehicle_number",\n    "export_basename",\n]\n\n\n# ============================================================\n# I/O\n# ============================================================\n\ndef read_csv(path: Path):\n    with path.open(\n        encoding="utf-8-sig",\n        newline="",\n    ) as f:\n        return list(\n            csv.DictReader(f)\n        )\n\n\ndef write_csv(\n    path: Path,\n    rows: list[dict],\n    columns: list[str],\n):\n    tmp = path.with_suffix(\n        path.suffix + ".part"\n    )\n\n    with tmp.open(\n        "w",\n        encoding="utf-8-sig",\n        newline="",\n    ) as f:\n\n        writer = csv.DictWriter(\n            f,\n            fieldnames=columns,\n            extrasaction="ignore",\n        )\n\n        writer.writeheader()\n        writer.writerows(rows)\n\n    tmp.replace(path)\n\n\n# ============================================================\n# General helpers\n# ============================================================\n\ndef norm(value):\n    return re.sub(\n        r"\\s+",\n        " ",\n        str(\n            value\n            if value is not None\n            else ""\n        ).strip(),\n    )\n\n\ndef norm_key(value):\n    return norm(\n        re.sub(\n            r"[^a-z0-9]+",\n            " ",\n            norm(value).casefold(),\n        )\n    )\n\n\ndef identifier(*parts):\n    text = "|".join(\n        norm(part)\n        for part in parts\n    )\n\n    return hashlib.sha256(\n        text.encode(\n            "utf-8"\n        )\n    ).hexdigest()[:24]\n\n\ndef json_compact(value):\n    return json.dumps(\n        value,\n        ensure_ascii=False,\n        separators=(\n            ",",\n            ":",\n        ),\n    )\n\n\ndef load_rows(value):\n    try:\n        result = json.loads(\n            value\n        )\n\n        if isinstance(\n            result,\n            list,\n        ):\n            return result\n\n    except (\n        json.JSONDecodeError,\n        TypeError,\n    ):\n        pass\n\n    return []\n\n\ndef populated_positions(row):\n    return [\n        (\n            index,\n            norm(value),\n        )\n        for index, value\n        in enumerate(row)\n        if norm(value)\n    ]\n\n\ndef populated(row):\n    return [\n        value\n        for _, value\n        in populated_positions(\n            row\n        )\n    ]\n\n\ndef clean_numeric_token(value):\n    text = norm(value)\n\n    text = re.sub(\n        r"^([+-])\\s+",\n        r"\\1",\n        text,\n    )\n\n    text = text.replace(\n        ",",\n        "",\n    )\n\n    return text\n\n\ndef remove_axis_annotation(value):\n    text = norm(value)\n\n    text = re.sub(\n        r"\\([^)]*\\)\\s*$",\n        "",\n        text,\n    )\n\n    text = re.sub(\n        r"\\s+count\\s*$",\n        "",\n        text,\n        flags=re.I,\n    )\n\n    return norm(text)\n\n\ndef is_numeric(value):\n    text = clean_numeric_token(\n        value\n    )\n\n    if not text:\n        return False\n\n    return bool(\n        re.fullmatch(\n            r"[-+]?"\n            r"(?:\\d+(?:\\.\\d*)?|\\.\\d+)"\n            r"(?:[eE][-+]?\\d+)?",\n            text,\n        )\n    )\n\n\ndef axis_is_numeric(value):\n    return is_numeric(\n        remove_axis_annotation(\n            value\n        )\n    )\n\n\ndef numeric_value(value):\n    text = remove_axis_annotation(\n        value\n    )\n\n    text = clean_numeric_token(\n        text\n    )\n\n    if not is_numeric(text):\n        return ""\n\n    try:\n        number = float(\n            text\n        )\n\n        if math.isfinite(\n            number\n        ):\n            return number\n\n    except ValueError:\n        pass\n\n    return ""\n\n\ndef is_na_like(value):\n    return (\n        norm(value).casefold()\n        in {\n            "",\n            "n/a",\n            "na",\n            "not available",\n            "not applicable",\n            "sna",\n            "unknown",\n            "not recorded",\n        }\n    )\n\n\n# ============================================================\n# Known non-timeseries tail trimming\n# ============================================================\n\ndef trim_non_timeseries_tail(rows):\n    """\n    Remove known diagnostic/PID payloads appended after an otherwise\n    valid time-series table.\n\n    The original source is unchanged. This only prevents raw PID/hex\n    payloads from being interpreted as Group 4 sample rows.\n\n    Current known delimiter:\n        PIDsStart\n    """\n\n    trimmed = []\n\n    for row in rows:\n\n        values = [\n            norm(value)\n            for value in row\n            if norm(value)\n        ]\n\n        if any(\n            value.casefold()\n            == "pidsstart"\n            for value in values\n        ):\n            break\n\n        trimmed.append(\n            row\n        )\n\n    return trimmed\n\n\n# ============================================================\n# Header / unit helpers\n# ============================================================\n\nUNIT_PATTERNS = [\n    r"^\\(?\\s*km/h\\s*\\)?$",\n    r"^\\(?\\s*mph\\s*\\)?$",\n    r"^\\(?\\s*km\\/h\\s*\\)?$",\n    r"^\\(?\\s*mi\\/h\\s*\\)?$",\n    r"^\\(?\\s*rpm\\s*\\)?$",\n    r"^\\(?\\s*%\\s*\\)?$",\n    r"^\\(?\\s*g\\s*\\)?$",\n    r"^\\(?\\s*m/s(?:\\^?2|²)?\\s*\\)?$",\n    r"^\\(?\\s*ft/s(?:\\^?2|²)?\\s*\\)?$",\n    r"^\\(?\\s*deg(?:ree)?s?\\s*\\)?$",\n    r"^\\(?\\s*degrees?/s\\s*\\)?$",\n    r"^\\(?\\s*deg/sec\\s*\\)?$",\n    r"^\\(?\\s*rad/s\\s*\\)?$",\n    r"^\\(?\\s*sec(?:onds?)?\\s*\\)?$",\n    r"^\\(?\\s*s\\s*\\)?$",\n    r"^\\(?\\s*ms(?:ec)?\\s*\\)?$",\n    r"^\\(?\\s*msec\\s*\\)?$",\n    r"^\\(?\\s*n/?a\\s*\\)?$",\n]\n\n\ndef looks_like_unit(value):\n    text = norm(value)\n\n    if not text:\n        return False\n\n    return any(\n        re.fullmatch(\n            pattern,\n            text,\n            re.I,\n        )\n        for pattern\n        in UNIT_PATTERNS\n    )\n\n\ndef join_header_fragments(values):\n    cleaned = []\n\n    for value in values:\n\n        text = norm(value)\n\n        if not text:\n            continue\n\n        if text in cleaned:\n            continue\n\n        cleaned.append(\n            text\n        )\n\n    return " | ".join(\n        cleaned\n    )\n\n\ndef derive_label_and_unit(\n    fragments,\n    fallback_label,\n):\n    """\n    Conservatively separate label-like header fragments and unit-like\n    fragments.\n\n    Original fragments are preserved separately.\n    """\n\n    fragments = [\n        norm(value)\n        for value in fragments\n        if norm(value)\n    ]\n\n    unit = ""\n    non_unit = []\n\n    for fragment in fragments:\n\n        if looks_like_unit(\n            fragment\n        ):\n            unit = fragment\n\n        else:\n            non_unit.append(\n                fragment\n            )\n\n    if non_unit:\n        label = non_unit[-1]\n    else:\n        label = fallback_label\n\n    return (\n        label,\n        unit,\n        fragments,\n    )\n\n\n# ============================================================\n# Axis helpers\n# ============================================================\n\ndef classify_axis_label(\n    label,\n    orientation,\n):\n    text = norm_key(\n        label\n    )\n\n    if re.search(\n        r"\\bbuffer address\\b",\n        text,\n    ):\n        return "buffer_address"\n\n    if re.search(\n        r"\\bsample count\\b",\n        text,\n    ):\n        return "sample_count_relative_to_trigger"\n\n    if re.search(\n        r"\\bseconds before\\b",\n        text,\n    ):\n        return "seconds_before_event"\n\n    if re.search(\n        r"\\bseconds after\\b",\n        text,\n    ):\n        return "seconds_after_event"\n\n    if re.search(\n        r"\\brelative time\\b",\n        text,\n    ):\n        return "relative_time"\n\n    if re.search(\n        r"\\btime\\b",\n        text,\n    ):\n        return "explicit_time"\n\n    if orientation == "buffer_order_table":\n        return "buffer_order"\n\n    return "ordered_numeric_axis"\n\n\ndef infer_axis_unit(\n    label,\n    explicit_unit="",\n):\n    if explicit_unit:\n        return explicit_unit\n\n    text = norm(label)\n\n    if re.search(\n        r"\\bmsec\\b|\\bms\\b",\n        text,\n        re.I,\n    ):\n        return "ms"\n\n    if re.search(\n        r"\\bsec\\b|\\bseconds?\\b|\\(s\\)",\n        text,\n        re.I,\n    ):\n        return "s"\n\n    if re.search(\n        r"\\bsample count\\b",\n        text,\n        re.I,\n    ):\n        return "count"\n\n    if re.search(\n        r"\\bbuffer address\\b",\n        text,\n        re.I,\n    ):\n        return "buffer_address"\n\n    return ""\n\n\n# ============================================================\n# Signal record helper\n# ============================================================\n\ndef build_signal_id(\n    series_id,\n    source_signal_index,\n):\n    return (\n        "g4sig_"\n        + identifier(\n            series_id,\n            source_signal_index,\n        )\n    )\n\n\ndef create_signal_record(\n    base,\n    series_id,\n    signal_position,\n    source_column_index,\n    source_row_index,\n    raw_label,\n    raw_unit,\n    header_fragments,\n    orientation,\n):\n    signal_id = build_signal_id(\n        series_id,\n        signal_position,\n    )\n\n    return {\n        **base,\n\n        "series_id":\n            series_id,\n\n        "signal_id":\n            signal_id,\n\n        "signal_position":\n            signal_position,\n\n        "source_column_index":\n            source_column_index,\n\n        "source_row_index":\n            source_row_index,\n\n        "signal_label_raw":\n            raw_label,\n\n        "signal_unit_raw":\n            raw_unit,\n\n        "header_fragments_json":\n            json_compact(\n                header_fragments\n            ),\n\n        "table_orientation":\n            orientation,\n\n        "semantic_normalization_status":\n            "not_normalized",\n    }\n\n\n# ============================================================\n# Transposed axis detection\n# ============================================================\n\ndef detect_transposed_axis_row(rows):\n    """\n    Detect a time/sample axis running across columns.\n\n    Examples:\n\n        Time (sec)  -5  -4  -3  -2  -1  0(TRG)\n\n    or:\n\n        Pre-Crash Sample Count from TRG\n                    -5 count ... 0(TRG)\n    """\n\n    best = None\n\n    for row_index, row in enumerate(\n        rows[:10]\n    ):\n\n        positions = populated_positions(\n            row\n        )\n\n        if len(\n            positions\n        ) < 3:\n            continue\n\n        text = " ".join(\n            value\n            for _, value\n            in positions\n        )\n\n        header_like = bool(\n            re.search(\n                r"\\b(?:"\n                r"time|"\n                r"sec|"\n                r"seconds?|"\n                r"sample count|"\n                r"TRG"\n                r")\\b",\n                text,\n                re.I,\n            )\n        )\n\n        if not header_like:\n            continue\n\n        numeric_positions = [\n            column\n            for column, value\n            in positions\n            if axis_is_numeric(\n                value\n            )\n        ]\n\n        if len(\n            numeric_positions\n        ) < 2:\n            continue\n\n        candidate = (\n            len(\n                numeric_positions\n            ),\n            row_index,\n            numeric_positions,\n        )\n\n        if (\n            best is None\n            or candidate[0]\n            > best[0]\n        ):\n            best = candidate\n\n    if best is None:\n        return None\n\n    _, row_index, sample_columns = (\n        best\n    )\n\n    return (\n        row_index,\n        sample_columns,\n    )\n\n\ndef has_transposed_time_axis(rows):\n    return (\n        detect_transposed_axis_row(\n            rows\n        )\n        is not None\n    )\n\n\n# ============================================================\n# Samples-by-rows extraction\n# ============================================================\n\ndef find_sample_rows_by_rows(rows):\n    result = []\n\n    for row_index, row in enumerate(\n        rows\n    ):\n\n        positions = populated_positions(\n            row\n        )\n\n        if len(\n            positions\n        ) < 2:\n            continue\n\n        first_col, first_value = (\n            positions[0]\n        )\n\n        if axis_is_numeric(\n            first_value\n        ):\n            result.append(\n                (\n                    row_index,\n                    first_col,\n                )\n            )\n\n    return result\n\n\ndef modal_axis_column(\n    sample_rows,\n):\n    if not sample_rows:\n        return None\n\n    counts = Counter(\n        column\n        for _, column\n        in sample_rows\n    )\n\n    return counts.most_common(\n        1\n    )[0][0]\n\n\ndef parse_samples_by_rows(\n    source,\n    rows,\n    series_id,\n):\n    sample_candidates = (\n        find_sample_rows_by_rows(\n            rows\n        )\n    )\n\n    if len(\n        sample_candidates\n    ) < 2:\n\n        raise ValueError(\n            "Could not identify at least two "\n            "numeric-axis sample rows."\n        )\n\n    axis_col = modal_axis_column(\n        sample_candidates\n    )\n\n    sample_row_indexes = [\n        row_index\n        for row_index, column\n        in sample_candidates\n        if column == axis_col\n    ]\n\n    if len(\n        sample_row_indexes\n    ) < 2:\n\n        raise ValueError(\n            "No stable axis column found."\n        )\n\n    first_sample_row = min(\n        sample_row_indexes\n    )\n\n    header_rows = rows[\n        :first_sample_row\n    ]\n\n    # --------------------------------------------------------\n    # Determine measurement columns\n    # --------------------------------------------------------\n\n    data_columns = set()\n\n    for row_index in sample_row_indexes:\n\n        row = rows[\n            row_index\n        ]\n\n        for column_index, value in enumerate(\n            row\n        ):\n\n            if (\n                column_index\n                == axis_col\n            ):\n                continue\n\n            if norm(value):\n                data_columns.add(\n                    column_index\n                )\n\n    data_columns = sorted(\n        data_columns\n    )\n\n    if not data_columns:\n        raise ValueError(\n            "No measurement columns found."\n        )\n\n    single_measurement_column = (\n        len(\n            data_columns\n        )\n        == 1\n    )\n\n    # --------------------------------------------------------\n    # Axis header\n    # --------------------------------------------------------\n\n    axis_fragments = []\n\n    for row in header_rows:\n\n        if axis_col < len(row):\n\n            value = norm(\n                row[\n                    axis_col\n                ]\n            )\n\n            if value:\n                axis_fragments.append(\n                    value\n                )\n\n    (\n        axis_label,\n        axis_unit,\n        axis_fragments,\n    ) = derive_label_and_unit(\n        axis_fragments,\n        fallback_label="Ordered Axis",\n    )\n\n    axis_type = classify_axis_label(\n        axis_label,\n        source[\n            "table_orientation"\n        ],\n    )\n\n    axis_unit = infer_axis_unit(\n        axis_label,\n        axis_unit,\n    )\n\n    # --------------------------------------------------------\n    # Signals\n    # --------------------------------------------------------\n\n    signals = []\n    column_to_signal = {}\n\n    for signal_position, column_index in enumerate(\n        data_columns,\n        1,\n    ):\n\n        fragments = []\n\n        for row in header_rows:\n\n            if column_index < len(\n                row\n            ):\n\n                value = norm(\n                    row[\n                        column_index\n                    ]\n                )\n\n                if value:\n                    fragments.append(\n                        value\n                    )\n\n        (\n            label,\n            unit,\n            fragments,\n        ) = derive_label_and_unit(\n            fragments,\n            fallback_label=(\n                f"source_column_{column_index}"\n            ),\n        )\n\n        # ----------------------------------------------------\n        # Single-signal table with only a unit header:\n        # use source section heading as measurement identity.\n        # ----------------------------------------------------\n\n        if (\n            single_measurement_column\n            and (\n                label.startswith(\n                    "source_column_"\n                )\n                or not label\n            )\n        ):\n\n            source_heading = norm(\n                source.get(\n                    "source_heading",\n                    "",\n                )\n            )\n\n            if source_heading:\n                label = source_heading\n\n        signal = create_signal_record(\n            base={\n                key:\n                    source.get(\n                        key,\n                        ""\n                    )\n                for key in BASE\n            },\n            series_id=series_id,\n            signal_position=signal_position,\n            source_column_index=column_index,\n            source_row_index="",\n            raw_label=label,\n            raw_unit=unit,\n            header_fragments=fragments,\n            orientation=source[\n                "table_orientation"\n            ],\n        )\n\n        signals.append(\n            signal\n        )\n\n        column_to_signal[\n            column_index\n        ] = signal\n\n    # --------------------------------------------------------\n    # Samples and long values\n    # --------------------------------------------------------\n\n    samples = []\n    values_long = []\n\n    for sample_index, row_index in enumerate(\n        sample_row_indexes\n    ):\n\n        row = rows[\n            row_index\n        ]\n\n        axis_raw = (\n            norm(\n                row[\n                    axis_col\n                ]\n            )\n            if axis_col < len(row)\n            else ""\n        )\n\n        sample_id = (\n            "g4sample_"\n            + identifier(\n                series_id,\n                sample_index,\n            )\n        )\n\n        values_map = {}\n\n        for column_index in data_columns:\n\n            signal = column_to_signal[\n                column_index\n            ]\n\n            raw_value = (\n                norm(\n                    row[\n                        column_index\n                    ]\n                )\n                if column_index < len(\n                    row\n                )\n                else ""\n            )\n\n            values_map[\n                signal[\n                    "signal_id"\n                ]\n            ] = raw_value\n\n            values_long.append({\n                **{\n                    key:\n                        source.get(\n                            key,\n                            ""\n                        )\n                    for key in BASE\n                },\n\n                "series_id":\n                    series_id,\n\n                "sample_id":\n                    sample_id,\n\n                "sample_index":\n                    sample_index,\n\n                "signal_id":\n                    signal[\n                        "signal_id"\n                    ],\n\n                "signal_position":\n                    signal[\n                        "signal_position"\n                    ],\n\n                "signal_label_raw":\n                    signal[\n                        "signal_label_raw"\n                    ],\n\n                "signal_unit_raw":\n                    signal[\n                        "signal_unit_raw"\n                    ],\n\n                "axis_type":\n                    axis_type,\n\n                "axis_label_raw":\n                    axis_label,\n\n                "axis_unit_raw":\n                    axis_unit,\n\n                "axis_value_raw":\n                    axis_raw,\n\n                "axis_value_numeric":\n                    numeric_value(\n                        axis_raw\n                    ),\n\n                "value_raw":\n                    raw_value,\n\n                "value_numeric":\n                    (\n                        numeric_value(\n                            raw_value\n                        )\n                        if is_numeric(\n                            raw_value\n                        )\n                        else ""\n                    ),\n\n                "value_is_missing_or_na":\n                    is_na_like(\n                        raw_value\n                    ),\n\n                "source_section_row_index":\n                    row_index,\n\n                "source_column_index":\n                    column_index,\n\n                "table_orientation":\n                    source[\n                        "table_orientation"\n                    ],\n            })\n\n        samples.append({\n            **{\n                key:\n                    source.get(\n                        key,\n                        ""\n                    )\n                for key in BASE\n            },\n\n            "series_id":\n                series_id,\n\n            "sample_id":\n                sample_id,\n\n            "sample_index":\n                sample_index,\n\n            "axis_type":\n                axis_type,\n\n            "axis_label_raw":\n                axis_label,\n\n            "axis_unit_raw":\n                axis_unit,\n\n            "axis_value_raw":\n                axis_raw,\n\n            "axis_value_numeric":\n                numeric_value(\n                    axis_raw\n                ),\n\n            "secondary_axes_json":\n                "{}",\n\n            "values_json":\n                json_compact(\n                    values_map\n                ),\n\n            "source_section_row_index":\n                row_index,\n\n            "table_orientation":\n                source[\n                    "table_orientation"\n                ],\n        })\n\n    return {\n        "signals":\n            signals,\n\n        "samples":\n            samples,\n\n        "values":\n            values_long,\n\n        "axis_type":\n            axis_type,\n\n        "axis_label_raw":\n            axis_label,\n\n        "axis_unit_raw":\n            axis_unit,\n\n        "axis_column_index":\n            axis_col,\n\n        "secondary_axis_columns":\n            [],\n\n        "header_row_count":\n            len(\n                header_rows\n            ),\n\n        "sample_count":\n            len(\n                samples\n            ),\n\n        "signal_count":\n            len(\n                signals\n            ),\n    }\n\n\n# ============================================================\n# Samples-by-columns extraction\n# ============================================================\n\ndef parse_samples_by_columns(\n    source,\n    rows,\n    series_id,\n):\n    detected = (\n        detect_transposed_axis_row(\n            rows\n        )\n    )\n\n    if detected is None:\n        raise ValueError(\n            "Could not identify transposed time/sample axis."\n        )\n\n    (\n        axis_row_index,\n        sample_columns,\n    ) = detected\n\n    axis_row = rows[\n        axis_row_index\n    ]\n\n    first_sample_column = min(\n        sample_columns\n    )\n\n    axis_label_fragments = [\n        norm(\n            axis_row[index]\n        )\n        for index in range(\n            min(\n                first_sample_column,\n                len(\n                    axis_row\n                ),\n            )\n        )\n        if norm(\n            axis_row[index]\n        )\n    ]\n\n    axis_label = (\n        join_header_fragments(\n            axis_label_fragments\n        )\n        or "Ordered Axis"\n    )\n\n    axis_type = classify_axis_label(\n        axis_label,\n        source[\n            "table_orientation"\n        ],\n    )\n\n    axis_unit = infer_axis_unit(\n        axis_label\n    )\n\n    # --------------------------------------------------------\n    # Detect signal rows\n    # --------------------------------------------------------\n\n    signal_rows = []\n\n    for row_index in range(\n        axis_row_index + 1,\n        len(\n            rows\n        ),\n    ):\n\n        row = rows[\n            row_index\n        ]\n\n        positions = populated_positions(\n            row\n        )\n\n        if len(\n            positions\n        ) < 2:\n            continue\n\n        values_on_axis = [\n            (\n                norm(\n                    row[column]\n                )\n                if column < len(\n                    row\n                )\n                else ""\n            )\n            for column\n            in sample_columns\n        ]\n\n        populated_sample_values = sum(\n            1\n            for value\n            in values_on_axis\n            if norm(value)\n        )\n\n        if populated_sample_values < 2:\n            continue\n\n        label_fragments = []\n\n        for column_index in range(\n            first_sample_column\n        ):\n\n            if column_index < len(\n                row\n            ):\n\n                value = norm(\n                    row[\n                        column_index\n                    ]\n                )\n\n                if value:\n                    label_fragments.append(\n                        value\n                    )\n\n        if not label_fragments:\n            continue\n\n        signal_rows.append(\n            (\n                row_index,\n                row,\n                label_fragments,\n            )\n        )\n\n    if not signal_rows:\n        raise ValueError(\n            "No signal rows found below transposed axis."\n        )\n\n    # --------------------------------------------------------\n    # Build signal registry\n    # --------------------------------------------------------\n\n    signals = []\n    row_to_signal = {}\n\n    for signal_position, (\n        row_index,\n        row,\n        label_fragments,\n    ) in enumerate(\n        signal_rows,\n        1,\n    ):\n\n        (\n            label,\n            unit,\n            fragments,\n        ) = derive_label_and_unit(\n            label_fragments,\n            fallback_label=(\n                f"source_row_{row_index}"\n            ),\n        )\n\n        signal = create_signal_record(\n            base={\n                key:\n                    source.get(\n                        key,\n                        ""\n                    )\n                for key in BASE\n            },\n            series_id=series_id,\n            signal_position=signal_position,\n            source_column_index="",\n            source_row_index=row_index,\n            raw_label=label,\n            raw_unit=unit,\n            header_fragments=fragments,\n            orientation="samples_by_columns",\n        )\n\n        signals.append(\n            signal\n        )\n\n        row_to_signal[\n            row_index\n        ] = signal\n\n    # --------------------------------------------------------\n    # Build samples and values\n    # --------------------------------------------------------\n\n    samples = []\n    values_long = []\n\n    for sample_index, column_index in enumerate(\n        sample_columns\n    ):\n\n        axis_raw = (\n            norm(\n                axis_row[\n                    column_index\n                ]\n            )\n            if column_index < len(\n                axis_row\n            )\n            else ""\n        )\n\n        sample_id = (\n            "g4sample_"\n            + identifier(\n                series_id,\n                sample_index,\n            )\n        )\n\n        values_map = {}\n\n        for (\n            row_index,\n            row,\n            _\n        ) in signal_rows:\n\n            signal = row_to_signal[\n                row_index\n            ]\n\n            raw_value = (\n                norm(\n                    row[\n                        column_index\n                    ]\n                )\n                if column_index < len(\n                    row\n                )\n                else ""\n            )\n\n            values_map[\n                signal[\n                    "signal_id"\n                ]\n            ] = raw_value\n\n            values_long.append({\n                **{\n                    key:\n                        source.get(\n                            key,\n                            ""\n                        )\n                    for key in BASE\n                },\n\n                "series_id":\n                    series_id,\n\n                "sample_id":\n                    sample_id,\n\n                "sample_index":\n                    sample_index,\n\n                "signal_id":\n                    signal[\n                        "signal_id"\n                    ],\n\n                "signal_position":\n                    signal[\n                        "signal_position"\n                    ],\n\n                "signal_label_raw":\n                    signal[\n                        "signal_label_raw"\n                    ],\n\n                "signal_unit_raw":\n                    signal[\n                        "signal_unit_raw"\n                    ],\n\n                "axis_type":\n                    axis_type,\n\n                "axis_label_raw":\n                    axis_label,\n\n                "axis_unit_raw":\n                    axis_unit,\n\n                "axis_value_raw":\n                    axis_raw,\n\n                "axis_value_numeric":\n                    numeric_value(\n                        axis_raw\n                    ),\n\n                "value_raw":\n                    raw_value,\n\n                "value_numeric":\n                    (\n                        numeric_value(\n                            raw_value\n                        )\n                        if is_numeric(\n                            raw_value\n                        )\n                        else ""\n                    ),\n\n                "value_is_missing_or_na":\n                    is_na_like(\n                        raw_value\n                    ),\n\n                "source_section_row_index":\n                    row_index,\n\n                "source_column_index":\n                    column_index,\n\n                "table_orientation":\n                    "samples_by_columns",\n            })\n\n        samples.append({\n            **{\n                key:\n                    source.get(\n                        key,\n                        ""\n                    )\n                for key in BASE\n            },\n\n            "series_id":\n                series_id,\n\n            "sample_id":\n                sample_id,\n\n            "sample_index":\n                sample_index,\n\n            "axis_type":\n                axis_type,\n\n            "axis_label_raw":\n                axis_label,\n\n            "axis_unit_raw":\n                axis_unit,\n\n            "axis_value_raw":\n                axis_raw,\n\n            "axis_value_numeric":\n                numeric_value(\n                    axis_raw\n                ),\n\n            "secondary_axes_json":\n                "{}",\n\n            "values_json":\n                json_compact(\n                    values_map\n                ),\n\n            "source_section_row_index":\n                axis_row_index,\n\n            "table_orientation":\n                "samples_by_columns",\n        })\n\n    return {\n        "signals":\n            signals,\n\n        "samples":\n            samples,\n\n        "values":\n            values_long,\n\n        "axis_type":\n            axis_type,\n\n        "axis_label_raw":\n            axis_label,\n\n        "axis_unit_raw":\n            axis_unit,\n\n        "axis_column_index":\n            "",\n\n        "secondary_axis_columns":\n            [],\n\n        "header_row_count":\n            axis_row_index + 1,\n\n        "sample_count":\n            len(\n                samples\n            ),\n\n        "signal_count":\n            len(\n                signals\n            ),\n    }\n\n\n# ============================================================\n# PCM / buffer-order extraction\n# ============================================================\n\ndef parse_buffer_order_table(\n    source,\n    rows,\n    series_id,\n):\n    """\n    Parse PCM/buffer-oriented tables.\n\n    Buffer Address is structural and is not required to be a normal\n    decimal time coordinate.\n\n    Relative Time is preserved when present.\n    """\n\n    header_row_index = None\n    axis_col = None\n\n    for row_index, row in enumerate(\n        rows[:10]\n    ):\n\n        for column_index, value in enumerate(\n            row\n        ):\n\n            if re.search(\n                r"\\bbuffer\\s+address\\b",\n                norm(value),\n                re.I,\n            ):\n\n                header_row_index = (\n                    row_index\n                )\n\n                axis_col = (\n                    column_index\n                )\n\n                break\n\n        if axis_col is not None:\n            break\n\n    if axis_col is None:\n\n        raise ValueError(\n            "Buffer Address column was not found."\n        )\n\n    # --------------------------------------------------------\n    # Locate Relative Time\n    # --------------------------------------------------------\n\n    relative_time_col = None\n\n    for row in rows[\n        header_row_index:\n        min(\n            header_row_index + 3,\n            len(rows),\n        )\n    ]:\n\n        for column_index, value in enumerate(\n            row\n        ):\n\n            if re.search(\n                r"\\brelative\\s+time\\b",\n                norm(value),\n                re.I,\n            ):\n\n                relative_time_col = (\n                    column_index\n                )\n\n                break\n\n        if relative_time_col is not None:\n            break\n\n    # --------------------------------------------------------\n    # Detect PCM data rows\n    # --------------------------------------------------------\n\n    data_row_indexes = []\n\n    for row_index in range(\n        header_row_index + 1,\n        len(\n            rows\n        ),\n    ):\n\n        row = rows[\n            row_index\n        ]\n\n        axis_raw = (\n            norm(\n                row[\n                    axis_col\n                ]\n            )\n            if axis_col < len(row)\n            else ""\n        )\n\n        if not axis_raw:\n            continue\n\n        if re.search(\n            r"\\b(?:"\n            r"buffer\\s+address|"\n            r"relative\\s+time|"\n            r"units?|"\n            r"seconds?|"\n            r"msec|"\n            r"milliseconds?"\n            r")\\b",\n            axis_raw,\n            re.I,\n        ):\n            continue\n\n        other_values = [\n            norm(value)\n            for column_index, value\n            in enumerate(row)\n            if (\n                column_index\n                != axis_col\n                and norm(value)\n            )\n        ]\n\n        if not other_values:\n            continue\n\n        data_row_indexes.append(\n            row_index\n        )\n\n    if len(\n        data_row_indexes\n    ) < 2:\n\n        raise ValueError(\n            "Could not identify at least two "\n            "PCM buffer data rows."\n        )\n\n    first_data_row = min(\n        data_row_indexes\n    )\n\n    header_rows = rows[\n        :first_data_row\n    ]\n\n    # --------------------------------------------------------\n    # Measurement columns\n    # --------------------------------------------------------\n\n    populated_data_columns = set()\n\n    for row_index in data_row_indexes:\n\n        row = rows[\n            row_index\n        ]\n\n        for column_index, value in enumerate(\n            row\n        ):\n\n            if not norm(value):\n                continue\n\n            if column_index == axis_col:\n                continue\n\n            if (\n                relative_time_col is not None\n                and column_index\n                == relative_time_col\n            ):\n                continue\n\n            populated_data_columns.add(\n                column_index\n            )\n\n    data_columns = sorted(\n        populated_data_columns\n    )\n\n    if not data_columns:\n\n        raise ValueError(\n            "No PCM measurement columns found."\n        )\n\n    # --------------------------------------------------------\n    # Signals\n    # --------------------------------------------------------\n\n    signals = []\n    column_to_signal = {}\n\n    for signal_position, column_index in enumerate(\n        data_columns,\n        1,\n    ):\n\n        fragments = []\n\n        for row in header_rows:\n\n            if column_index >= len(\n                row\n            ):\n                continue\n\n            value = norm(\n                row[\n                    column_index\n                ]\n            )\n\n            if value:\n                fragments.append(\n                    value\n                )\n\n        (\n            label,\n            unit,\n            fragments,\n        ) = derive_label_and_unit(\n            fragments,\n            fallback_label=(\n                f"source_column_{column_index}"\n            ),\n        )\n\n        signal = create_signal_record(\n            base={\n                key:\n                    source.get(\n                        key,\n                        ""\n                    )\n                for key in BASE\n            },\n            series_id=series_id,\n            signal_position=signal_position,\n            source_column_index=column_index,\n            source_row_index="",\n            raw_label=label,\n            raw_unit=unit,\n            header_fragments=fragments,\n            orientation="buffer_order_table",\n        )\n\n        signals.append(\n            signal\n        )\n\n        column_to_signal[\n            column_index\n        ] = signal\n\n    # --------------------------------------------------------\n    # Relative time availability\n    # --------------------------------------------------------\n\n    relative_time_values = []\n\n    if relative_time_col is not None:\n\n        for row_index in data_row_indexes:\n\n            row = rows[\n                row_index\n            ]\n\n            value = (\n                norm(\n                    row[\n                        relative_time_col\n                    ]\n                )\n                if relative_time_col\n                < len(row)\n                else ""\n            )\n\n            relative_time_values.append(\n                value\n            )\n\n    numeric_relative_times = sum(\n        1\n        for value\n        in relative_time_values\n        if axis_is_numeric(\n            value\n        )\n    )\n\n    if numeric_relative_times >= 2:\n\n        time_axis_status = (\n            "relative_time_available"\n        )\n\n    else:\n\n        time_axis_status = (\n            "buffer_order_only"\n        )\n\n    # --------------------------------------------------------\n    # Samples\n    # --------------------------------------------------------\n\n    samples = []\n    values_long = []\n\n    for sample_index, row_index in enumerate(\n        data_row_indexes\n    ):\n\n        row = rows[\n            row_index\n        ]\n\n        buffer_address_raw = (\n            norm(\n                row[\n                    axis_col\n                ]\n            )\n            if axis_col < len(row)\n            else ""\n        )\n\n        relative_time_raw = ""\n\n        if relative_time_col is not None:\n\n            relative_time_raw = (\n                norm(\n                    row[\n                        relative_time_col\n                    ]\n                )\n                if relative_time_col\n                < len(row)\n                else ""\n            )\n\n        sample_id = (\n            "g4sample_"\n            + identifier(\n                series_id,\n                sample_index,\n            )\n        )\n\n        values_map = {}\n\n        for column_index in data_columns:\n\n            signal = column_to_signal[\n                column_index\n            ]\n\n            raw_value = (\n                norm(\n                    row[\n                        column_index\n                    ]\n                )\n                if column_index\n                < len(row)\n                else ""\n            )\n\n            values_map[\n                signal[\n                    "signal_id"\n                ]\n            ] = raw_value\n\n            values_long.append({\n                **{\n                    key:\n                        source.get(\n                            key,\n                            ""\n                        )\n                    for key in BASE\n                },\n\n                "series_id":\n                    series_id,\n\n                "sample_id":\n                    sample_id,\n\n                "sample_index":\n                    sample_index,\n\n                "signal_id":\n                    signal[\n                        "signal_id"\n                    ],\n\n                "signal_position":\n                    signal[\n                        "signal_position"\n                    ],\n\n                "signal_label_raw":\n                    signal[\n                        "signal_label_raw"\n                    ],\n\n                "signal_unit_raw":\n                    signal[\n                        "signal_unit_raw"\n                    ],\n\n                "axis_type":\n                    time_axis_status,\n\n                "axis_label_raw":\n                    "Buffer Address",\n\n                "axis_unit_raw":\n                    "buffer_address",\n\n                "axis_value_raw":\n                    buffer_address_raw,\n\n                "axis_value_numeric":\n                    (\n                        numeric_value(\n                            buffer_address_raw\n                        )\n                        if axis_is_numeric(\n                            buffer_address_raw\n                        )\n                        else ""\n                    ),\n\n                "value_raw":\n                    raw_value,\n\n                "value_numeric":\n                    (\n                        numeric_value(\n                            raw_value\n                        )\n                        if is_numeric(\n                            raw_value\n                        )\n                        else ""\n                    ),\n\n                "value_is_missing_or_na":\n                    is_na_like(\n                        raw_value\n                    ),\n\n                "source_section_row_index":\n                    row_index,\n\n                "source_column_index":\n                    column_index,\n\n                "table_orientation":\n                    "buffer_order_table",\n            })\n\n        secondary_axes = {\n            "buffer_address":\n                buffer_address_raw,\n        }\n\n        if relative_time_col is not None:\n\n            secondary_axes[\n                "relative_time"\n            ] = relative_time_raw\n\n        samples.append({\n            **{\n                key:\n                    source.get(\n                        key,\n                        ""\n                    )\n                for key in BASE\n            },\n\n            "series_id":\n                series_id,\n\n            "sample_id":\n                sample_id,\n\n            "sample_index":\n                sample_index,\n\n            "axis_type":\n                time_axis_status,\n\n            "axis_label_raw":\n                "Buffer Address",\n\n            "axis_unit_raw":\n                "buffer_address",\n\n            "axis_value_raw":\n                buffer_address_raw,\n\n            "axis_value_numeric":\n                (\n                    numeric_value(\n                        buffer_address_raw\n                    )\n                    if axis_is_numeric(\n                        buffer_address_raw\n                    )\n                    else ""\n                ),\n\n            "secondary_axes_json":\n                json_compact(\n                    secondary_axes\n                ),\n\n            "values_json":\n                json_compact(\n                    values_map\n                ),\n\n            "source_section_row_index":\n                row_index,\n\n            "table_orientation":\n                "buffer_order_table",\n        })\n\n    return {\n        "signals":\n            signals,\n\n        "samples":\n            samples,\n\n        "values":\n            values_long,\n\n        "axis_type":\n            time_axis_status,\n\n        "axis_label_raw":\n            "Buffer Address",\n\n        "axis_unit_raw":\n            "buffer_address",\n\n        "axis_column_index":\n            axis_col,\n\n        "secondary_axis_columns":\n            (\n                [relative_time_col]\n                if relative_time_col\n                is not None\n                else []\n            ),\n\n        "header_row_count":\n            first_data_row,\n\n        "sample_count":\n            len(\n                samples\n            ),\n\n        "signal_count":\n            len(\n                signals\n            ),\n    }\n\n\n# ============================================================\n# Companion metadata\n# ============================================================\n\ndef build_companion_rows(rows):\n    result = []\n\n    for source in rows:\n\n        source_rows = load_rows(\n            source.get(\n                "source_rows_json",\n                ""\n            )\n        )\n\n        companion_id = (\n            "g4meta_"\n            + identifier(\n                source.get(\n                    "report_id",\n                    "",\n                ),\n                source.get(\n                    "timeseries_candidate_id",\n                    "",\n                ),\n                source.get(\n                    "source_heading",\n                    "",\n                ),\n            )\n        )\n\n        result.append({\n            **{\n                key:\n                    source.get(\n                        key,\n                        ""\n                    )\n                for key in BASE\n            },\n\n            "companion_metadata_id":\n                companion_id,\n\n            "timeseries_candidate_id":\n                source.get(\n                    "timeseries_candidate_id",\n                    "",\n                ),\n\n            "source_heading":\n                source.get(\n                    "source_heading",\n                    "",\n                ),\n\n            "audited_family":\n                source.get(\n                    "audited_family",\n                    "",\n                ),\n\n            "audited_component":\n                source.get(\n                    "audited_component",\n                    "",\n                ),\n\n            "audit_reason":\n                source.get(\n                    "audit_reason",\n                    "",\n                ),\n\n            "source_record_start":\n                source.get(\n                    "source_record_start",\n                    "",\n                ),\n\n            "source_record_end":\n                source.get(\n                    "source_record_end",\n                    "",\n                ),\n\n            "source_rows_json":\n                json_compact(\n                    source_rows\n                ),\n\n            "processing_status":\n                "preserved_companion_metadata",\n\n            "linkage_status":\n                "not_yet_linked_to_series",\n        })\n\n    return result\n\n\n# ============================================================\n# Main\n# ============================================================\n\ndef main():\n\n    parser = argparse.ArgumentParser(\n        description=__doc__\n    )\n\n    parser.add_argument(\n        "--audit-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group4_csv_audit_v1"\n        ),\n    )\n\n    parser.add_argument(\n        "--output-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group4_csv_structured_v1"\n        ),\n    )\n\n    args = parser.parse_args()\n\n    audit_dir = (\n        args.audit_directory\n    )\n\n    accepted_path = (\n        audit_dir\n        / "accepted_timeseries_sections.csv"\n    )\n\n    companion_path = (\n        audit_dir\n        / "timeseries_companion_metadata_sections.csv"\n    )\n\n    if not accepted_path.exists():\n        raise FileNotFoundError(\n            accepted_path\n        )\n\n    if not companion_path.exists():\n        raise FileNotFoundError(\n            companion_path\n        )\n\n    accepted = read_csv(\n        accepted_path\n    )\n\n    companion_input = read_csv(\n        companion_path\n    )\n\n    registry = []\n    signal_registry = []\n    samples = []\n    values_long = []\n    audit_rows = []\n    failures = []\n\n    parser_orientation_counts = Counter()\n    trimmed_pid_section_count = 0\n    orientation_override_count = 0\n\n    # ========================================================\n    # Extract\n    # ========================================================\n\n    for index, source in enumerate(\n        accepted,\n        1,\n    ):\n\n        candidate_id = source.get(\n            "timeseries_candidate_id",\n            "",\n        )\n\n        series_id = (\n            "g4csv_"\n            + identifier(\n                source.get(\n                    "report_id",\n                    "",\n                ),\n                candidate_id,\n                source.get(\n                    "source_heading",\n                    "",\n                ),\n            )\n        )\n\n        audited_orientation = norm(\n            source.get(\n                "table_orientation",\n                "",\n            )\n        )\n\n        source_rows_original = load_rows(\n            source.get(\n                "source_rows_json",\n                ""\n            )\n        )\n\n        source_rows = trim_non_timeseries_tail(\n            source_rows_original\n        )\n\n        if (\n            len(source_rows)\n            < len(\n                source_rows_original\n            )\n        ):\n            trimmed_pid_section_count += 1\n\n        if not source_rows:\n\n            failures.append({\n                **{\n                    key:\n                        source.get(\n                            key,\n                            ""\n                        )\n                    for key in BASE\n                },\n\n                "timeseries_candidate_id":\n                    candidate_id,\n\n                "series_id":\n                    series_id,\n\n                "source_heading":\n                    source.get(\n                        "source_heading",\n                        "",\n                    ),\n\n                "table_orientation":\n                    audited_orientation,\n\n                "error_type":\n                    "empty_source_rows",\n\n                "error":\n                    (\n                        "source_rows_json was empty or became empty "\n                        "after known tail trimming."\n                    ),\n            })\n\n            continue\n\n        try:\n\n            if (\n                audited_orientation\n                == "buffer_order_table"\n            ):\n\n                parser_orientation = (\n                    "buffer_order_table"\n                )\n\n                parsed = (\n                    parse_buffer_order_table(\n                        source,\n                        source_rows,\n                        series_id,\n                    )\n                )\n\n            elif has_transposed_time_axis(\n                source_rows\n            ):\n\n                parser_orientation = (\n                    "samples_by_columns"\n                )\n\n                if (\n                    audited_orientation\n                    != "samples_by_columns"\n                ):\n                    orientation_override_count += 1\n\n                parsed = (\n                    parse_samples_by_columns(\n                        source,\n                        source_rows,\n                        series_id,\n                    )\n                )\n\n            elif (\n                audited_orientation\n                == "samples_by_rows"\n            ):\n\n                parser_orientation = (\n                    "samples_by_rows"\n                )\n\n                parsed = (\n                    parse_samples_by_rows(\n                        source,\n                        source_rows,\n                        series_id,\n                    )\n                )\n\n            elif (\n                audited_orientation\n                == "samples_by_columns"\n            ):\n\n                parser_orientation = (\n                    "samples_by_columns"\n                )\n\n                parsed = (\n                    parse_samples_by_columns(\n                        source,\n                        source_rows,\n                        series_id,\n                    )\n                )\n\n            else:\n\n                raise ValueError(\n                    "Unsupported table orientation: "\n                    f"{audited_orientation}"\n                )\n\n        except Exception as exc:\n\n            failures.append({\n                **{\n                    key:\n                        source.get(\n                            key,\n                            ""\n                        )\n                    for key in BASE\n                },\n\n                "timeseries_candidate_id":\n                    candidate_id,\n\n                "series_id":\n                    series_id,\n\n                "source_heading":\n                    source.get(\n                        "source_heading",\n                        "",\n                    ),\n\n                "table_orientation":\n                    audited_orientation,\n\n                "error_type":\n                    type(\n                        exc\n                    ).__name__,\n\n                "error":\n                    str(\n                        exc\n                    ),\n            })\n\n            continue\n\n        parser_orientation_counts[\n            parser_orientation\n        ] += 1\n\n        signal_registry.extend(\n            parsed[\n                "signals"\n            ]\n        )\n\n        samples.extend(\n            parsed[\n                "samples"\n            ]\n        )\n\n        values_long.extend(\n            parsed[\n                "values"\n            ]\n        )\n\n        registry.append({\n            **{\n                key:\n                    source.get(\n                        key,\n                        ""\n                    )\n                for key in BASE\n            },\n\n            "series_id":\n                series_id,\n\n            "timeseries_candidate_id":\n                candidate_id,\n\n            "source_heading":\n                source.get(\n                    "source_heading",\n                    "",\n                ),\n\n            "source_path":\n                source.get(\n                    "source_path",\n                    "",\n                ),\n\n            "source_record_start":\n                source.get(\n                    "source_record_start",\n                    "",\n                ),\n\n            "source_record_end":\n                source.get(\n                    "source_record_end",\n                    "",\n                ),\n\n            "family":\n                source.get(\n                    "audited_family",\n                    "",\n                ),\n\n            "component":\n                source.get(\n                    "audited_component",\n                    "",\n                ),\n\n            "audited_orientation":\n                audited_orientation,\n\n            "table_orientation":\n                parser_orientation,\n\n            "orientation_overridden":\n                (\n                    parser_orientation\n                    != audited_orientation\n                ),\n\n            "pid_tail_trimmed":\n                (\n                    len(source_rows)\n                    < len(\n                        source_rows_original\n                    )\n                ),\n\n            "axis_type":\n                parsed[\n                    "axis_type"\n                ],\n\n            "axis_label_raw":\n                parsed[\n                    "axis_label_raw"\n                ],\n\n            "axis_unit_raw":\n                parsed[\n                    "axis_unit_raw"\n                ],\n\n            "axis_column_index":\n                parsed[\n                    "axis_column_index"\n                ],\n\n            "secondary_axis_columns_json":\n                json_compact(\n                    parsed[\n                        "secondary_axis_columns"\n                    ]\n                ),\n\n            "header_row_count":\n                parsed[\n                    "header_row_count"\n                ],\n\n            "sample_count":\n                parsed[\n                    "sample_count"\n                ],\n\n            "signal_count":\n                parsed[\n                    "signal_count"\n                ],\n\n            "processing_status":\n                "structured_extracted",\n\n            "semantic_normalization_status":\n                "not_normalized",\n\n            "unit_conversion_status":\n                "not_converted",\n        })\n\n        audit_rows.append({\n            **{\n                key:\n                    source.get(\n                        key,\n                        ""\n                    )\n                for key in BASE\n            },\n\n            "series_id":\n                series_id,\n\n            "timeseries_candidate_id":\n                candidate_id,\n\n            "source_heading":\n                source.get(\n                    "source_heading",\n                    "",\n                ),\n\n            "family":\n                source.get(\n                    "audited_family",\n                    "",\n                ),\n\n            "component":\n                source.get(\n                    "audited_component",\n                    "",\n                ),\n\n            "audited_orientation":\n                audited_orientation,\n\n            "table_orientation":\n                parser_orientation,\n\n            "pid_tail_trimmed":\n                (\n                    len(source_rows)\n                    < len(\n                        source_rows_original\n                    )\n                ),\n\n            "axis_type":\n                parsed[\n                    "axis_type"\n                ],\n\n            "sample_count":\n                parsed[\n                    "sample_count"\n                ],\n\n            "signal_count":\n                parsed[\n                    "signal_count"\n                ],\n\n            "long_value_count":\n                len(\n                    parsed[\n                        "values"\n                    ]\n                ),\n\n            "status":\n                "success",\n\n            "issue":\n                "",\n        })\n\n        if (\n            index % 250 == 0\n            or index\n            == len(\n                accepted\n            )\n        ):\n\n            print(\n                "Structured Group 4 CSV "\n                f"{index}/{len(accepted)} sections...",\n                flush=True,\n            )\n\n    companion_rows = (\n        build_companion_rows(\n            companion_input\n        )\n    )\n\n    # ========================================================\n    # Validation\n    # ========================================================\n\n    validation = []\n\n    def add_check(\n        name,\n        condition,\n        observed,\n        expected,\n        severity="hard",\n    ):\n        validation.append({\n            "check":\n                name,\n\n            "status":\n                (\n                    "PASS"\n                    if condition\n                    else "FAIL"\n                ),\n\n            "severity":\n                severity,\n\n            "observed":\n                str(\n                    observed\n                ),\n\n            "expected":\n                str(\n                    expected\n                ),\n        })\n\n    add_check(\n        "accepted_sections_accounted_for",\n        (\n            len(\n                registry\n            )\n            + len(\n                failures\n            )\n            == len(\n                accepted\n            )\n        ),\n        (\n            len(\n                registry\n            )\n            + len(\n                failures\n            )\n        ),\n        len(\n            accepted\n        ),\n    )\n\n    add_check(\n        "input_accepted_section_count",\n        len(\n            accepted\n        )\n        == 8265,\n        len(\n            accepted\n        ),\n        8265,\n        severity="warning",\n    )\n\n    add_check(\n        "companion_metadata_count",\n        len(\n            companion_rows\n        )\n        == len(\n            companion_input\n        ),\n        len(\n            companion_rows\n        ),\n        len(\n            companion_input\n        ),\n    )\n\n    series_ids = [\n        row[\n            "series_id"\n        ]\n        for row in registry\n    ]\n\n    signal_ids = [\n        row[\n            "signal_id"\n        ]\n        for row in signal_registry\n    ]\n\n    sample_ids = [\n        row[\n            "sample_id"\n        ]\n        for row in samples\n    ]\n\n    add_check(\n        "series_ids_unique",\n        len(\n            series_ids\n        )\n        == len(\n            set(\n                series_ids\n            )\n        ),\n        len(\n            set(\n                series_ids\n            )\n        ),\n        len(\n            series_ids\n        ),\n    )\n\n    add_check(\n        "signal_ids_unique",\n        len(\n            signal_ids\n        )\n        == len(\n            set(\n                signal_ids\n            )\n        ),\n        len(\n            set(\n                signal_ids\n            )\n        ),\n        len(\n            signal_ids\n        ),\n    )\n\n    add_check(\n        "sample_ids_unique",\n        len(\n            sample_ids\n        )\n        == len(\n            set(\n                sample_ids\n            )\n        ),\n        len(\n            set(\n                sample_ids\n            )\n        ),\n        len(\n            sample_ids\n        ),\n    )\n\n    signal_id_set = set(\n        signal_ids\n    )\n\n    sample_id_set = set(\n        sample_ids\n    )\n\n    orphan_signal_values = sum(\n        1\n        for row in values_long\n        if row[\n            "signal_id"\n        ]\n        not in signal_id_set\n    )\n\n    orphan_sample_values = sum(\n        1\n        for row in values_long\n        if row[\n            "sample_id"\n        ]\n        not in sample_id_set\n    )\n\n    add_check(\n        "long_values_have_known_signal",\n        orphan_signal_values\n        == 0,\n        orphan_signal_values,\n        0,\n    )\n\n    add_check(\n        "long_values_have_known_sample",\n        orphan_sample_values\n        == 0,\n        orphan_sample_values,\n        0,\n    )\n\n    empty_sample_series = sum(\n        1\n        for row in registry\n        if int(\n            row[\n                "sample_count"\n            ]\n        ) < 1\n    )\n\n    empty_signal_series = sum(\n        1\n        for row in registry\n        if int(\n            row[\n                "signal_count"\n            ]\n        ) < 1\n    )\n\n    add_check(\n        "successful_series_have_samples",\n        empty_sample_series\n        == 0,\n        empty_sample_series,\n        0,\n    )\n\n    add_check(\n        "successful_series_have_signals",\n        empty_signal_series\n        == 0,\n        empty_signal_series,\n        0,\n    )\n\n    # ========================================================\n    # Summaries\n    # ========================================================\n\n    family_counts = Counter(\n        row[\n            "family"\n        ]\n        for row in registry\n    )\n\n    component_counts = Counter(\n        row[\n            "component"\n        ]\n        for row in registry\n    )\n\n    orientation_counts = Counter(\n        row[\n            "table_orientation"\n        ]\n        for row in registry\n    )\n\n    axis_type_counts = Counter(\n        row[\n            "axis_type"\n        ]\n        for row in registry\n    )\n\n    signal_label_counts = Counter(\n        row[\n            "signal_label_raw"\n        ]\n        for row in signal_registry\n    )\n\n    signal_unit_counts = Counter(\n        row[\n            "signal_unit_raw"\n        ]\n        for row in signal_registry\n        if row[\n            "signal_unit_raw"\n        ]\n    )\n\n    report_ids = {\n        row[\n            "report_id"\n        ]\n        for row in registry\n    }\n\n    # ========================================================\n    # Write outputs\n    # ========================================================\n\n    out = (\n        args.output_directory\n    )\n\n    out.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    write_csv(\n        out\n        / "timeseries_registry.csv",\n        registry,\n        [\n            *BASE,\n            "series_id",\n            "timeseries_candidate_id",\n            "source_heading",\n            "source_path",\n            "source_record_start",\n            "source_record_end",\n            "family",\n            "component",\n            "audited_orientation",\n            "table_orientation",\n            "orientation_overridden",\n            "pid_tail_trimmed",\n            "axis_type",\n            "axis_label_raw",\n            "axis_unit_raw",\n            "axis_column_index",\n            "secondary_axis_columns_json",\n            "header_row_count",\n            "sample_count",\n            "signal_count",\n            "processing_status",\n            "semantic_normalization_status",\n            "unit_conversion_status",\n        ],\n    )\n\n    write_csv(\n        out\n        / "timeseries_signal_registry.csv",\n        signal_registry,\n        [\n            *BASE,\n            "series_id",\n            "signal_id",\n            "signal_position",\n            "source_column_index",\n            "source_row_index",\n            "signal_label_raw",\n            "signal_unit_raw",\n            "header_fragments_json",\n            "table_orientation",\n            "semantic_normalization_status",\n        ],\n    )\n\n    write_csv(\n        out\n        / "timeseries_samples_wide.csv",\n        samples,\n        [\n            *BASE,\n            "series_id",\n            "sample_id",\n            "sample_index",\n            "axis_type",\n            "axis_label_raw",\n            "axis_unit_raw",\n            "axis_value_raw",\n            "axis_value_numeric",\n            "secondary_axes_json",\n            "values_json",\n            "source_section_row_index",\n            "table_orientation",\n        ],\n    )\n\n    write_csv(\n        out\n        / "timeseries_values_long.csv",\n        values_long,\n        [\n            *BASE,\n            "series_id",\n            "sample_id",\n            "sample_index",\n            "signal_id",\n            "signal_position",\n            "signal_label_raw",\n            "signal_unit_raw",\n            "axis_type",\n            "axis_label_raw",\n            "axis_unit_raw",\n            "axis_value_raw",\n            "axis_value_numeric",\n            "value_raw",\n            "value_numeric",\n            "value_is_missing_or_na",\n            "source_section_row_index",\n            "source_column_index",\n            "table_orientation",\n        ],\n    )\n\n    write_csv(\n        out\n        / "timeseries_companion_metadata.csv",\n        companion_rows,\n        [\n            *BASE,\n            "companion_metadata_id",\n            "timeseries_candidate_id",\n            "source_heading",\n            "audited_family",\n            "audited_component",\n            "audit_reason",\n            "source_record_start",\n            "source_record_end",\n            "source_rows_json",\n            "processing_status",\n            "linkage_status",\n        ],\n    )\n\n    write_csv(\n        out\n        / "timeseries_audit.csv",\n        audit_rows,\n        [\n            *BASE,\n            "series_id",\n            "timeseries_candidate_id",\n            "source_heading",\n            "family",\n            "component",\n            "audited_orientation",\n            "table_orientation",\n            "pid_tail_trimmed",\n            "axis_type",\n            "sample_count",\n            "signal_count",\n            "long_value_count",\n            "status",\n            "issue",\n        ],\n    )\n\n    write_csv(\n        out\n        / "extraction_failures.csv",\n        failures,\n        [\n            *BASE,\n            "timeseries_candidate_id",\n            "series_id",\n            "source_heading",\n            "table_orientation",\n            "error_type",\n            "error",\n        ],\n    )\n\n    write_csv(\n        out\n        / "validation_report.csv",\n        validation,\n        [\n            "check",\n            "status",\n            "severity",\n            "observed",\n            "expected",\n        ],\n    )\n\n    # ========================================================\n    # Metadata\n    # ========================================================\n\n    hard_failures = [\n        row\n        for row in validation\n        if (\n            row[\n                "status"\n            ]\n            == "FAIL"\n            and row[\n                "severity"\n            ]\n            == "hard"\n        )\n    ]\n\n    warning_failures = [\n        row\n        for row in validation\n        if (\n            row[\n                "status"\n            ]\n            == "FAIL"\n            and row[\n                "severity"\n            ]\n            == "warning"\n        )\n    ]\n\n    metadata = {\n\n        "created_at":\n            datetime.now(\n                timezone.utc\n            ).isoformat(),\n\n        "group":\n            "Group 4 - Time-series measurements",\n\n        "stage":\n            "CSV structural extraction",\n\n        "input_accepted_sections":\n            len(\n                accepted\n            ),\n\n        "input_companion_metadata_sections":\n            len(\n                companion_input\n            ),\n\n        "structured_series_count":\n            len(\n                registry\n            ),\n\n        "failed_section_count":\n            len(\n                failures\n            ),\n\n        "reports_with_structured_timeseries":\n            len(\n                report_ids\n            ),\n\n        "signal_registry_rows":\n            len(\n                signal_registry\n            ),\n\n        "sample_rows":\n            len(\n                samples\n            ),\n\n        "long_value_rows":\n            len(\n                values_long\n            ),\n\n        "companion_metadata_rows":\n            len(\n                companion_rows\n            ),\n\n        "pid_tail_trimmed_section_count":\n            trimmed_pid_section_count,\n\n        "orientation_override_count":\n            orientation_override_count,\n\n        "parser_orientation_counts":\n            dict(\n                parser_orientation_counts\n            ),\n\n        "family_counts":\n            dict(\n                family_counts\n            ),\n\n        "component_counts":\n            dict(\n                component_counts\n            ),\n\n        "orientation_counts":\n            dict(\n                orientation_counts\n            ),\n\n        "axis_type_counts":\n            dict(\n                axis_type_counts\n            ),\n\n        "unique_raw_signal_labels":\n            len(\n                signal_label_counts\n            ),\n\n        "top_raw_signal_labels":\n            signal_label_counts.most_common(\n                40\n            ),\n\n        "raw_unit_counts":\n            dict(\n                signal_unit_counts\n            ),\n\n        "validation_checks":\n            len(\n                validation\n            ),\n\n        "validation_failures":\n            sum(\n                1\n                for row\n                in validation\n                if row[\n                    "status"\n                ]\n                == "FAIL"\n            ),\n\n        "hard_validation_failures":\n            len(\n                hard_failures\n            ),\n\n        "warning_validation_failures":\n            len(\n                warning_failures\n            ),\n\n        "scope":\n            (\n                "Structural extraction of accepted Group 4 CSV "\n                "time-series sections. PID/hex tails beginning at "\n                "PIDsStart are excluded from Group 4 parsing. "\n                "Samples-by-rows, samples-by-columns, and PCM/buffer "\n                "layouts are supported. Transposed structure is "\n                "re-detected after PID trimming. Single-signal tables "\n                "with unit-only column headers use the source section "\n                "heading as the structural signal identity. Raw values, "\n                "units, source labels, and provenance remain preserved. "\n                "No semantic normalization, unit conversion, event "\n                "identity inference, or PDF extraction is performed."\n            ),\n    }\n\n    metadata_tmp = (\n        out\n        / "metadata.json.part"\n    )\n\n    metadata_tmp.write_text(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        ),\n        encoding="utf-8",\n    )\n\n    metadata_tmp.replace(\n        out\n        / "metadata.json"\n    )\n\n    print(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        )\n    )\n\n    print()\n    print(\n        f"Outputs: {out}"\n    )\n\n    if hard_failures:\n\n        print()\n        print(\n            "GROUP 4 CSV STRUCTURAL EXTRACTION "\n            "HAS HARD VALIDATION FAILURES."\n        )\n\n        for row in hard_failures:\n\n            print(\n                f"- {row[\'check\']}: "\n                f"observed={row[\'observed\']} "\n                f"expected={row[\'expected\']}"\n            )\n\n        raise SystemExit(1)\n\n    print()\n    print(\n        "GROUP 4 CSV STRUCTURAL EXTRACTION COMPLETE."\n    )\n\n\n'

_PDF_DISCOVERY_SOURCE = '"""\nGroup 4 PDF-only discovery: Time-series measurements.\n\nPurpose\n-------\nDiscover time-series-like structures directly from ORIGINAL PDF reports\nfor reports where no CSV source is available.\n\nSource hierarchy\n----------------\n1. CSV available:\n       NOT processed here.\n\n2. CSV unavailable + PDF available:\n       original PDF is inspected directly.\n\n3. Existing Group 2 PDF time-series handoff:\n       used only as locator/supporting evidence when available.\n       It is NOT treated as the measurement source.\n\nThis is a discovery pass only.\n\nIt does NOT:\n- create the final structured PDF time-series dataset,\n- normalize signal names,\n- convert units,\n- infer event identities,\n- interpolate missing time,\n- merge PDF and CSV data,\n- or modify the frozen CSV Group 4 package.\n\nOutputs\n-------\ndata/processed/edr/group4_pdf_discovery_v1/\n\n    pdf_timeseries_candidate_tables.csv\n    pdf_timeseries_candidate_rows.csv\n    pdf_review_tables.csv\n    pdf_report_coverage.csv\n    pdf_heading_summary.csv\n    pdf_family_summary.csv\n    errors.csv\n    metadata.json\n\nDependencies\n------------\npdfplumber\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport hashlib\nimport json\nimport re\n\nfrom collections import Counter, defaultdict\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\nimport pdfplumber\n\n\ncsv.field_size_limit(100_000_000)\n\n\nBASE = [\n    "report_id",\n    "case_id",\n    "vehicle_number",\n    "export_basename",\n]\n\n\n# ============================================================\n# I/O\n# ============================================================\n\ndef read_csv(path: Path):\n    with path.open(\n        encoding="utf-8-sig",\n        newline="",\n    ) as f:\n        return list(\n            csv.DictReader(f)\n        )\n\n\ndef write_csv(\n    path: Path,\n    rows: list[dict],\n    columns: list[str],\n):\n    tmp = path.with_suffix(\n        path.suffix + ".part"\n    )\n\n    with tmp.open(\n        "w",\n        encoding="utf-8-sig",\n        newline="",\n    ) as f:\n\n        writer = csv.DictWriter(\n            f,\n            fieldnames=columns,\n            extrasaction="ignore",\n        )\n\n        writer.writeheader()\n        writer.writerows(rows)\n\n    tmp.replace(path)\n\n\n# ============================================================\n# General helpers\n# ============================================================\n\ndef norm(value):\n    return re.sub(\n        r"\\s+",\n        " ",\n        str(\n            value\n            if value is not None\n            else ""\n        ).strip(),\n    )\n\n\ndef norm_key(value):\n    return norm(\n        re.sub(\n            r"[^a-z0-9]+",\n            " ",\n            norm(value).casefold(),\n        )\n    )\n\n\ndef identifier(*parts):\n    text = "|".join(\n        norm(part)\n        for part in parts\n    )\n\n    return hashlib.sha256(\n        text.encode(\n            "utf-8"\n        )\n    ).hexdigest()[:24]\n\n\ndef first_nonblank(\n    row: dict,\n    keys: list[str],\n):\n    for key in keys:\n\n        value = norm(\n            row.get(\n                key,\n                ""\n            )\n        )\n\n        if value:\n            return value\n\n    return ""\n\n\ndef resolve_path(\n    value,\n    source_root: Path,\n):\n    raw = norm(value)\n\n    if not raw:\n        return None\n\n    path = Path(raw)\n\n    if path.exists():\n        return path\n\n    candidate = (\n        source_root\n        / path\n    )\n\n    if candidate.exists():\n        return candidate\n\n    return None\n\n\ndef clean_numeric_token(value):\n    text = norm(value)\n\n    text = re.sub(\n        r"^([+-])\\s+",\n        r"\\1",\n        text,\n    )\n\n    text = text.replace(\n        ",",\n        "",\n    )\n\n    return text\n\n\ndef remove_axis_annotation(value):\n    text = norm(value)\n\n    text = re.sub(\n        r"\\([^)]*\\)\\s*$",\n        "",\n        text,\n    )\n\n    text = re.sub(\n        r"\\s+count\\s*$",\n        "",\n        text,\n        flags=re.I,\n    )\n\n    return norm(text)\n\n\ndef is_numeric(value):\n    text = clean_numeric_token(\n        remove_axis_annotation(\n            value\n        )\n    )\n\n    if not text:\n        return False\n\n    return bool(\n        re.fullmatch(\n            r"[-+]?"\n            r"(?:\\d+(?:\\.\\d*)?|\\.\\d+)"\n            r"(?:[eE][-+]?\\d+)?",\n            text,\n        )\n    )\n\n\ndef is_na(value):\n    return (\n        norm(value).casefold()\n        in {\n            "n/a",\n            "na",\n            "sna",\n            "not available",\n            "not applicable",\n            "unknown",\n            "not recorded",\n        }\n    )\n\n\ndef row_values(row):\n    return [\n        norm(value)\n        for value in row\n        if norm(value)\n    ]\n\n\ndef row_text(row):\n    return " ".join(\n        row_values(\n            row\n        )\n    )\n\n\ndef table_text(rows):\n    return " ".join(\n        row_text(row)\n        for row in rows\n    )\n\n\n# ============================================================\n# Report-source helpers\n# ============================================================\n\ndef get_csv_path_value(row):\n    return first_nonblank(\n        row,\n        [\n            "csv_path",\n            "source_csv_path",\n            "csv_file",\n        ],\n    )\n\n\ndef get_pdf_path_value(row):\n    return first_nonblank(\n        row,\n        [\n            "pdf_path",\n            "source_pdf_path",\n            "pdf_file",\n        ],\n    )\n\n\n# ============================================================\n# Group 2 handoff locator\n# ============================================================\n\ndef load_group2_handoff(\n    path: Path,\n):\n    """\n    Build lightweight locator maps from the frozen Group 2 handoff.\n\n    This is SUPPORTING evidence only.\n    """\n\n    if not path.exists():\n        return {\n            "by_report":\n                defaultdict(\n                    list\n                ),\n\n            "count":\n                0,\n        }\n\n    rows = read_csv(\n        path\n    )\n\n    by_report = defaultdict(\n        list\n    )\n\n    for row in rows:\n\n        report_id = norm(\n            row.get(\n                "report_id",\n                ""\n            )\n        )\n\n        if not report_id:\n            continue\n\n        by_report[\n            report_id\n        ].append(\n            row\n        )\n\n    return {\n        "by_report":\n            by_report,\n\n        "count":\n            len(\n                rows\n            ),\n    }\n\n\ndef handoff_matches_page(\n    handoff_rows,\n    page_number,\n):\n    """\n    Return Group 2 locator evidence matching this PDF page.\n\n    Accept both zero-based and one-based page conventions conservatively.\n    """\n\n    matches = []\n\n    for row in handoff_rows:\n\n        raw_page = first_nonblank(\n            row,\n            [\n                "source_page",\n                "page",\n                "page_number",\n            ],\n        )\n\n        if not raw_page:\n            continue\n\n        try:\n            value = int(\n                float(\n                    raw_page\n                )\n            )\n\n        except ValueError:\n            continue\n\n        if value in {\n            page_number,\n            page_number - 1,\n        }:\n            matches.append(\n                row\n            )\n\n    return matches\n\n\n# ============================================================\n# Heading / family detection\n# ============================================================\n\nFAMILY_RULES = [\n    (\n        "pcm_edr",\n        r"\\bPCM\\s+EDR\\s+DATA\\b",\n    ),\n\n    (\n        "pre_crash",\n        r"\\bPRE[-_ ]?CRASH\\b",\n    ),\n\n    (\n        "post_crash",\n        r"\\bPOST[-_ ]?CRASH\\b",\n    ),\n\n    (\n        "crash_pulse",\n        r"\\bCRASH\\s+PULSE\\b",\n    ),\n\n    (\n        "delta_v",\n        r"\\b(?:DELTA[- ]?V|VELOCITY\\s+CHANGE)\\b",\n    ),\n\n    (\n        "roll_angle",\n        r"\\bROLL\\s+ANGLE\\b",\n    ),\n\n    (\n        "angular_rate",\n        r"\\b(?:ROLL\\s+RATE|ANGULAR\\s+RATE)\\b",\n    ),\n\n    (\n        "acceleration",\n        r"\\bACCELERATION\\b",\n    ),\n\n    (\n        "rollover_sensor",\n        r"\\bROLLOVER\\s+SENSOR\\b",\n    ),\n\n    (\n        "sensor_timeseries",\n        r"\\b(?:"\n        r"PERIPHERAL\\s+SENSOR|"\n        r"PRESSURE\\s+SENSOR|"\n        r"SATELLITE\\s+SENSOR"\n        r")\\b",\n    ),\n]\n\n\ndef detect_family(text):\n    text = norm(text)\n\n    for family, pattern in FAMILY_RULES:\n\n        if re.search(\n            pattern,\n            text,\n            re.I,\n        ):\n            return family\n\n    return "other_timeseries"\n\n\ndef detect_component(text):\n    upper = norm(\n        text\n    ).upper()\n\n    has_long = (\n        "LONGITUDINAL"\n        in upper\n    )\n\n    has_lat = (\n        "LATERAL"\n        in upper\n    )\n\n    if (\n        has_long\n        and has_lat\n    ):\n        return "longitudinal_lateral"\n\n    if has_long:\n        return "longitudinal"\n\n    if has_lat:\n        return "lateral"\n\n    if (\n        "NORMAL"\n        in upper\n        or "VERTICAL"\n        in upper\n    ):\n        return "normal_vertical"\n\n    if (\n        "ROLL"\n        in upper\n        or "ANGULAR"\n        in upper\n    ):\n        return "roll_angular"\n\n    return "unspecified"\n\n\ndef extract_heading_hint(\n    page_text,\n    table_rows,\n):\n    """\n    PDF tables do not always preserve section headings inside the table.\n\n    Use:\n    1. table text when it clearly contains a structural heading;\n    2. otherwise page text as a broad heading/context hint.\n\n    No semantic identity is inferred.\n    """\n\n    candidate_text = table_text(\n        table_rows\n    )\n\n    for family, pattern in FAMILY_RULES:\n\n        match = re.search(\n            pattern,\n            candidate_text,\n            re.I,\n        )\n\n        if match:\n\n            lines = [\n                norm(line)\n                for line\n                in candidate_text.split(\n                    "\\n"\n                )\n                if norm(line)\n            ]\n\n            if lines:\n                return lines[0]\n\n    page_lines = [\n        norm(line)\n        for line\n        in (\n            page_text\n            or ""\n        ).splitlines()\n        if norm(line)\n    ]\n\n    # Prefer lines with known temporal family wording.\n    for line in page_lines:\n\n        if any(\n            re.search(\n                pattern,\n                line,\n                re.I,\n            )\n            for _, pattern\n            in FAMILY_RULES\n        ):\n            return line\n\n    # Otherwise preserve a short page-context string.\n    return (\n        page_lines[0]\n        if page_lines\n        else ""\n    )\n\n\n# ============================================================\n# Known non-time-series structures\n# ============================================================\n\nNON_TIMESERIES_PATTERNS = [\n    (\n        "group2_summary",\n        r"\\bEVENT\\s+RECORD\\s+SUMMARY\\b",\n    ),\n\n    (\n        "dtc_structure",\n        r"\\bDTCS?\\s+PRESENT\\b",\n    ),\n\n    (\n        "status_configuration",\n        r"\\bSYSTEM\\s+(?:STATUS|CONFIGURATION)\\b",\n    ),\n\n    (\n        "deployment_scalar",\n        r"\\bDEPLOYMENT\\s+(?:COMMAND\\s+)?DATA\\b",\n    ),\n]\n\n\ndef known_non_timeseries_reason(\n    text,\n):\n    for reason, pattern in (\n        NON_TIMESERIES_PATTERNS\n    ):\n\n        if re.search(\n            pattern,\n            text,\n            re.I,\n        ):\n            return reason\n\n    return ""\n\n\n# ============================================================\n# Time-series structural evidence\n# ============================================================\n\nTIME_PATTERNS = [\n    r"\\btime\\b",\n    r"\\bseconds?\\s+before\\b",\n    r"\\bseconds?\\s+after\\b",\n    r"\\bsec\\b",\n    r"\\bmsec\\b",\n    r"\\bmilliseconds?\\b",\n    r"\\brelative\\s+time\\b",\n    r"\\bsample\\s+count\\b",\n    r"\\bbuffer\\s+address\\b",\n]\n\n\nSIGNAL_PATTERNS = [\n    r"\\bvehicle\\s+speed\\b",\n    r"\\bengine\\s+(?:speed|rpm)\\b",\n    r"\\bthrottle\\b",\n    r"\\baccelerator\\b",\n    r"\\bbrake\\b",\n    r"\\bacceleration\\b",\n    r"\\bdelta[- ]?v\\b",\n    r"\\bvelocity\\b",\n    r"\\byaw\\b",\n    r"\\bsteering\\b",\n    r"\\broll\\b",\n]\n\n\ndef detect_samples_by_rows(rows):\n    """\n    Find repeated numeric-axis rows.\n\n    Returns:\n        numeric_row_count\n        modal_first_populated_column\n    """\n\n    columns = []\n\n    for row in rows:\n\n        positions = [\n            (\n                index,\n                norm(value),\n            )\n            for index, value\n            in enumerate(row)\n            if norm(value)\n        ]\n\n        if len(\n            positions\n        ) < 2:\n            continue\n\n        first_column, first_value = (\n            positions[0]\n        )\n\n        if (\n            is_numeric(\n                first_value\n            )\n            or is_na(\n                first_value\n            )\n        ):\n            columns.append(\n                first_column\n            )\n\n    if not columns:\n        return (\n            0,\n            "",\n        )\n\n    counts = Counter(\n        columns\n    )\n\n    modal_column, modal_count = (\n        counts.most_common(\n            1\n        )[0]\n    )\n\n    return (\n        modal_count,\n        modal_column,\n    )\n\n\ndef detect_samples_by_columns(rows):\n    """\n    Detect transposed tables such as:\n\n        Time (sec)   -5  -4  -3  -2  -1\n        Speed        20  18  ...\n    """\n\n    for row_index, row in enumerate(\n        rows[:10]\n    ):\n\n        values = row_values(\n            row\n        )\n\n        if len(\n            values\n        ) < 3:\n            continue\n\n        text = " ".join(\n            values\n        )\n\n        if not re.search(\n            r"\\b(?:"\n            r"time|"\n            r"seconds?|"\n            r"sec|"\n            r"msec|"\n            r"sample\\s+count|"\n            r"TRG"\n            r")\\b",\n            text,\n            re.I,\n        ):\n            continue\n\n        numeric_count = sum(\n            1\n            for value\n            in values\n            if is_numeric(\n                value\n            )\n        )\n\n        if numeric_count >= 2:\n            return (\n                True,\n                row_index,\n                numeric_count,\n            )\n\n    return (\n        False,\n        "",\n        0,\n    )\n\n\ndef detect_buffer_axis(rows):\n    text = " ".join(\n        row_text(row)\n        for row in rows[:8]\n    )\n\n    return bool(\n        re.search(\n            r"\\bbuffer\\s+address\\b",\n            text,\n            re.I,\n        )\n    )\n\n\ndef detect_explicit_time_header(rows):\n    text = " ".join(\n        row_text(row)\n        for row in rows[:8]\n    )\n\n    matches = [\n        pattern\n        for pattern in TIME_PATTERNS\n        if re.search(\n            pattern,\n            text,\n            re.I,\n        )\n    ]\n\n    return (\n        len(\n            matches\n        ),\n        matches,\n    )\n\n\ndef detect_signal_headers(rows):\n    text = " ".join(\n        row_text(row)\n        for row in rows[:10]\n    )\n\n    matches = [\n        pattern\n        for pattern\n        in SIGNAL_PATTERNS\n        if re.search(\n            pattern,\n            text,\n            re.I,\n        )\n    ]\n\n    return (\n        len(\n            matches\n        ),\n        matches,\n    )\n\n\ndef repeated_width_evidence(rows):\n    widths = []\n\n    for row in rows:\n\n        width = len(\n            row_values(\n                row\n            )\n        )\n\n        if width >= 2:\n            widths.append(\n                width\n            )\n\n    if not widths:\n        return (\n            0,\n            0,\n        )\n\n    counts = Counter(\n        widths\n    )\n\n    return counts.most_common(\n        1\n    )[0]\n\n\n# ============================================================\n# Candidate analysis\n# ============================================================\n\ndef analyze_table(\n    rows,\n    heading_hint,\n    page_text,\n    handoff_page_matches,\n):\n    combined_text = " ".join(\n        [\n            norm(\n                heading_hint\n            ),\n            table_text(\n                rows\n            ),\n        ]\n    )\n\n    exclusion_reason = (\n        known_non_timeseries_reason(\n            combined_text\n        )\n    )\n\n    (\n        numeric_row_count,\n        numeric_axis_column,\n    ) = detect_samples_by_rows(\n        rows\n    )\n\n    (\n        transposed,\n        transposed_axis_row,\n        transposed_sample_count,\n    ) = detect_samples_by_columns(\n        rows\n    )\n\n    buffer_axis = (\n        detect_buffer_axis(\n            rows\n        )\n    )\n\n    (\n        time_header_count,\n        time_header_patterns,\n    ) = detect_explicit_time_header(\n        rows\n    )\n\n    (\n        signal_header_count,\n        signal_patterns,\n    ) = detect_signal_headers(\n        rows\n    )\n\n    (\n        modal_width,\n        modal_width_count,\n    ) = repeated_width_evidence(\n        rows\n    )\n\n    family = detect_family(\n        combined_text\n    )\n\n    component = detect_component(\n        combined_text\n    )\n\n    family_evidence = (\n        family\n        != "other_timeseries"\n    )\n\n    score = 0\n    reasons = []\n\n    if numeric_row_count >= 2:\n        score += 4\n        reasons.append(\n            "repeated_numeric_axis_rows"\n        )\n\n    if transposed:\n        score += 5\n        reasons.append(\n            "transposed_time_axis"\n        )\n\n    if buffer_axis:\n        score += 5\n        reasons.append(\n            "buffer_axis"\n        )\n\n    if time_header_count:\n        score += 2\n        reasons.append(\n            "time_or_index_header"\n        )\n\n    if signal_header_count:\n        score += 1\n        reasons.append(\n            "measurement_signal_header"\n        )\n\n    if modal_width_count >= 3:\n        score += 1\n        reasons.append(\n            "repeated_table_width"\n        )\n\n    if family_evidence:\n        score += 2\n        reasons.append(\n            "known_temporal_family"\n        )\n\n    if handoff_page_matches:\n        score += 1\n        reasons.append(\n            "group2_handoff_page_support"\n        )\n\n    # --------------------------------------------------------\n    # Structural orientation\n    # --------------------------------------------------------\n\n    if buffer_axis:\n\n        orientation = (\n            "buffer_order_table"\n        )\n\n    elif transposed:\n\n        orientation = (\n            "samples_by_columns"\n        )\n\n    elif numeric_row_count >= 2:\n\n        orientation = (\n            "samples_by_rows"\n        )\n\n    else:\n\n        orientation = (\n            "unknown"\n        )\n\n    # --------------------------------------------------------\n    # Candidate decision\n    # --------------------------------------------------------\n\n    if exclusion_reason:\n\n        candidate = False\n        review = False\n        decision = (\n            "known_non_timeseries"\n        )\n\n    else:\n\n        strong_structure = (\n            buffer_axis\n            or transposed\n            or numeric_row_count >= 2\n        )\n\n        candidate = (\n            strong_structure\n            and score >= 5\n        )\n\n        review = (\n            not candidate\n            and score >= 3\n        )\n\n        decision = (\n            "candidate"\n            if candidate\n            else (\n                "review"\n                if review\n                else "ignore"\n            )\n        )\n\n    return {\n        "decision":\n            decision,\n\n        "candidate":\n            candidate,\n\n        "review":\n            review,\n\n        "score":\n            score,\n\n        "family":\n            family,\n\n        "component":\n            component,\n\n        "orientation":\n            orientation,\n\n        "numeric_row_count":\n            numeric_row_count,\n\n        "numeric_axis_column":\n            numeric_axis_column,\n\n        "transposed_axis_detected":\n            transposed,\n\n        "transposed_axis_row":\n            transposed_axis_row,\n\n        "transposed_sample_count":\n            transposed_sample_count,\n\n        "buffer_axis":\n            buffer_axis,\n\n        "time_header_count":\n            time_header_count,\n\n        "time_header_patterns":\n            time_header_patterns,\n\n        "signal_header_count":\n            signal_header_count,\n\n        "signal_patterns":\n            signal_patterns,\n\n        "modal_width":\n            modal_width,\n\n        "modal_width_count":\n            modal_width_count,\n\n        "known_non_timeseries_reason":\n            exclusion_reason,\n\n        "reasons":\n            reasons,\n    }\n\n\n# ============================================================\n# Main\n# ============================================================\n\ndef main():\n\n    parser = argparse.ArgumentParser(\n        description=__doc__\n    )\n\n    parser.add_argument(\n        "--index",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group1_v4/"\n            "report_index.csv"\n        ),\n    )\n\n    parser.add_argument(\n        "--source-root",\n        type=Path,\n        default=Path(\n            "data/temp"\n        ),\n    )\n\n    parser.add_argument(\n        "--group2-handoff",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group2_final_v1/"\n            "group4_pdf_timeseries_handoff_sections.csv"\n        ),\n    )\n\n    parser.add_argument(\n        "--output-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group4_pdf_discovery_v1"\n        ),\n    )\n\n    parser.add_argument(\n        "--limit",\n        type=int,\n        default=None,\n    )\n\n    args = parser.parse_args()\n\n    index_rows = read_csv(\n        args.index\n    )\n\n    handoff = load_group2_handoff(\n        args.group2_handoff\n    )\n\n    candidates = []\n    candidate_rows = []\n    reviews = []\n    coverage = []\n    errors = []\n\n    # ========================================================\n    # Determine PDF-only population first\n    # ========================================================\n\n    pdf_only_reports = []\n\n    for report in index_rows:\n\n        csv_value = get_csv_path_value(\n            report\n        )\n\n        csv_path = resolve_path(\n            csv_value,\n            args.source_root,\n        )\n\n        # CSV exists -> this report is already handled\n        # by frozen Group 4 CSV.\n        if csv_path is not None:\n            continue\n\n        pdf_only_reports.append(\n            report\n        )\n\n    if args.limit is not None:\n\n        pdf_only_reports = (\n            pdf_only_reports[\n                :args.limit\n            ]\n        )\n\n    print(\n        "PDF-only reports selected: "\n        f"{len(pdf_only_reports)}",\n        flush=True,\n    )\n\n    # ========================================================\n    # Process original PDFs\n    # ========================================================\n\n    for report_number, report in enumerate(\n        pdf_only_reports,\n        1,\n    ):\n\n        base = {\n            key:\n                report.get(\n                    key,\n                    ""\n                )\n            for key in BASE\n        }\n\n        report_id = norm(\n            report.get(\n                "report_id",\n                ""\n            )\n        )\n\n        pdf_value = get_pdf_path_value(\n            report\n        )\n\n        pdf_path = resolve_path(\n            pdf_value,\n            args.source_root,\n        )\n\n        handoff_rows = (\n            handoff[\n                "by_report"\n            ].get(\n                report_id,\n                [],\n            )\n        )\n\n        if pdf_path is None:\n\n            coverage.append({\n                **base,\n\n                "pdf_available":\n                    False,\n\n                "pdf_processed":\n                    False,\n\n                "page_count":\n                    0,\n\n                "table_count":\n                    0,\n\n                "candidate_table_count":\n                    0,\n\n                "review_table_count":\n                    0,\n\n                "group2_handoff_locator_count":\n                    len(\n                        handoff_rows\n                    ),\n\n                "status":\n                    "pdf_missing",\n\n                "issue":\n                    norm(\n                        pdf_value\n                    ),\n            })\n\n            continue\n\n        report_table_count = 0\n        report_candidate_count = 0\n        report_review_count = 0\n        page_count = 0\n\n        try:\n\n            with pdfplumber.open(\n                pdf_path\n            ) as pdf:\n\n                page_count = len(\n                    pdf.pages\n                )\n\n                for page_number, page in enumerate(\n                    pdf.pages,\n                    1,\n                ):\n\n                    try:\n\n                        page_text = (\n                            page.extract_text()\n                            or ""\n                        )\n\n                    except Exception:\n\n                        page_text = ""\n\n                    page_handoff_matches = (\n                        handoff_matches_page(\n                            handoff_rows,\n                            page_number,\n                        )\n                    )\n\n                    # ----------------------------------------\n                    # Extract page tables\n                    # ----------------------------------------\n\n                    try:\n\n                        tables = (\n                            page.extract_tables()\n                            or []\n                        )\n\n                    except Exception as exc:\n\n                        errors.append({\n                            **base,\n\n                            "source_path":\n                                str(\n                                    pdf_path\n                                ),\n\n                            "page_number":\n                                page_number,\n\n                            "stage":\n                                "extract_tables",\n\n                            "error":\n                                (\n                                    f"{type(exc).__name__}: "\n                                    f"{exc}"\n                                ),\n                        })\n\n                        continue\n\n                    for table_index, table in enumerate(\n                        tables\n                    ):\n\n                        if not table:\n                            continue\n\n                        cleaned_rows = [\n                            [\n                                norm(cell)\n                                for cell in row\n                            ]\n                            for row in table\n                            if row is not None\n                        ]\n\n                        cleaned_rows = [\n                            row\n                            for row\n                            in cleaned_rows\n                            if row_values(\n                                row\n                            )\n                        ]\n\n                        if len(\n                            cleaned_rows\n                        ) < 2:\n                            continue\n\n                        report_table_count += 1\n\n                        heading_hint = (\n                            extract_heading_hint(\n                                page_text,\n                                cleaned_rows,\n                            )\n                        )\n\n                        analysis = (\n                            analyze_table(\n                                cleaned_rows,\n                                heading_hint,\n                                page_text,\n                                page_handoff_matches,\n                            )\n                        )\n\n                        if (\n                            not analysis[\n                                "candidate"\n                            ]\n                            and not analysis[\n                                "review"\n                            ]\n                        ):\n                            continue\n\n                        candidate_id = (\n                            "g4pdf_"\n                            + identifier(\n                                report_id,\n                                page_number,\n                                table_index,\n                                heading_hint,\n                            )\n                        )\n\n                        handoff_headings = [\n                            first_nonblank(\n                                row,\n                                [\n                                    "source_heading",\n                                    "heading",\n                                ],\n                            )\n                            for row\n                            in page_handoff_matches\n                        ]\n\n                        common = {\n                            **base,\n\n                            "pdf_candidate_id":\n                                candidate_id,\n\n                            "source_path":\n                                str(\n                                    pdf_path\n                                ),\n\n                            "page_number":\n                                page_number,\n\n                            "table_index_on_page":\n                                table_index,\n\n                            "source_heading_hint":\n                                heading_hint,\n\n                            "family_candidate":\n                                analysis[\n                                    "family"\n                                ],\n\n                            "component_candidate":\n                                analysis[\n                                    "component"\n                                ],\n\n                            "table_orientation_candidate":\n                                analysis[\n                                    "orientation"\n                                ],\n\n                            "discovery_score":\n                                analysis[\n                                    "score"\n                                ],\n\n                            "numeric_axis_row_count":\n                                analysis[\n                                    "numeric_row_count"\n                                ],\n\n                            "numeric_axis_column":\n                                analysis[\n                                    "numeric_axis_column"\n                                ],\n\n                            "transposed_axis_detected":\n                                analysis[\n                                    "transposed_axis_detected"\n                                ],\n\n                            "transposed_axis_row":\n                                analysis[\n                                    "transposed_axis_row"\n                                ],\n\n                            "transposed_sample_count":\n                                analysis[\n                                    "transposed_sample_count"\n                                ],\n\n                            "buffer_axis_detected":\n                                analysis[\n                                    "buffer_axis"\n                                ],\n\n                            "time_header_match_count":\n                                analysis[\n                                    "time_header_count"\n                                ],\n\n                            "signal_header_match_count":\n                                analysis[\n                                    "signal_header_count"\n                                ],\n\n                            "modal_populated_width":\n                                analysis[\n                                    "modal_width"\n                                ],\n\n                            "modal_width_row_count":\n                                analysis[\n                                    "modal_width_count"\n                                ],\n\n                            "group2_handoff_page_support":\n                                bool(\n                                    page_handoff_matches\n                                ),\n\n                            "group2_handoff_match_count":\n                                len(\n                                    page_handoff_matches\n                                ),\n\n                            "group2_handoff_headings_json":\n                                json.dumps(\n                                    handoff_headings,\n                                    ensure_ascii=False,\n                                ),\n\n                            "discovery_reasons":\n                                "|".join(\n                                    analysis[\n                                        "reasons"\n                                    ]\n                                ),\n\n                            "source_rows_json":\n                                json.dumps(\n                                    cleaned_rows,\n                                    ensure_ascii=False,\n                                ),\n\n                            "page_text_context":\n                                norm(\n                                    page_text\n                                )[:4000],\n                        }\n\n                        if analysis[\n                            "candidate"\n                        ]:\n\n                            report_candidate_count += 1\n\n                            candidates.append({\n                                **common,\n\n                                "processing_status":\n                                    "pdf_timeseries_candidate",\n\n                                "requires_review":\n                                    True,\n                            })\n\n                            for row_index, row in enumerate(\n                                cleaned_rows\n                            ):\n\n                                candidate_rows.append({\n                                    **base,\n\n                                    "pdf_candidate_id":\n                                        candidate_id,\n\n                                    "page_number":\n                                        page_number,\n\n                                    "table_index_on_page":\n                                        table_index,\n\n                                    "source_heading_hint":\n                                        heading_hint,\n\n                                    "family_candidate":\n                                        analysis[\n                                            "family"\n                                        ],\n\n                                    "table_orientation_candidate":\n                                        analysis[\n                                            "orientation"\n                                        ],\n\n                                    "table_row_index":\n                                        row_index,\n\n                                    "source_row_json":\n                                        json.dumps(\n                                            row,\n                                            ensure_ascii=False,\n                                        ),\n\n                                    "populated_cell_count":\n                                        len(\n                                            row_values(\n                                                row\n                                            )\n                                        ),\n\n                                    "first_populated_value":\n                                        (\n                                            row_values(\n                                                row\n                                            )[0]\n                                            if row_values(\n                                                row\n                                            )\n                                            else ""\n                                        ),\n                                })\n\n                        elif analysis[\n                            "review"\n                        ]:\n\n                            report_review_count += 1\n\n                            reviews.append({\n                                **common,\n\n                                "processing_status":\n                                    "pdf_near_threshold_review",\n\n                                "requires_review":\n                                    True,\n                            })\n\n        except Exception as exc:\n\n            errors.append({\n                **base,\n\n                "source_path":\n                    str(\n                        pdf_path\n                    ),\n\n                "page_number":\n                    "",\n\n                "stage":\n                    "open_pdf",\n\n                "error":\n                    (\n                        f"{type(exc).__name__}: "\n                        f"{exc}"\n                    ),\n            })\n\n            coverage.append({\n                **base,\n\n                "pdf_available":\n                    True,\n\n                "pdf_processed":\n                    False,\n\n                "page_count":\n                    0,\n\n                "table_count":\n                    0,\n\n                "candidate_table_count":\n                    0,\n\n                "review_table_count":\n                    0,\n\n                "group2_handoff_locator_count":\n                    len(\n                        handoff_rows\n                    ),\n\n                "status":\n                    "pdf_processing_failed",\n\n                "issue":\n                    (\n                        f"{type(exc).__name__}: "\n                        f"{exc}"\n                    ),\n            })\n\n            continue\n\n        # ----------------------------------------------------\n        # Report coverage\n        # ----------------------------------------------------\n\n        coverage.append({\n            **base,\n\n            "pdf_available":\n                True,\n\n            "pdf_processed":\n                True,\n\n            "page_count":\n                page_count,\n\n            "table_count":\n                report_table_count,\n\n            "candidate_table_count":\n                report_candidate_count,\n\n            "review_table_count":\n                report_review_count,\n\n            "group2_handoff_locator_count":\n                len(\n                    handoff_rows\n                ),\n\n            "status":\n                (\n                    "timeseries_candidates_found"\n                    if report_candidate_count\n                    else (\n                        "review_only"\n                        if report_review_count\n                        else "no_timeseries_candidates"\n                    )\n                ),\n\n            "issue":\n                "",\n        })\n\n        print(\n            "Discovered Group 4 PDF "\n            f"{report_number}/"\n            f"{len(pdf_only_reports)} reports...",\n            flush=True,\n        )\n\n    # ========================================================\n    # Summaries\n    # ========================================================\n\n    family_counts = Counter(\n        row[\n            "family_candidate"\n        ]\n        for row in candidates\n    )\n\n    orientation_counts = Counter(\n        row[\n            "table_orientation_candidate"\n        ]\n        for row in candidates\n    )\n\n    heading_counts = Counter(\n        row[\n            "source_heading_hint"\n        ]\n        for row in candidates\n    )\n\n    coverage_counts = Counter(\n        row[\n            "status"\n        ]\n        for row in coverage\n    )\n\n    family_summary = []\n\n    grouped_family = defaultdict(\n        list\n    )\n\n    for row in candidates:\n\n        grouped_family[\n            (\n                row[\n                    "family_candidate"\n                ],\n                row[\n                    "component_candidate"\n                ],\n                row[\n                    "table_orientation_candidate"\n                ],\n            )\n        ].append(\n            row\n        )\n\n    for (\n        family,\n        component,\n        orientation,\n    ), rows in sorted(\n        grouped_family.items()\n    ):\n\n        reports = {\n            row[\n                "report_id"\n            ]\n            for row in rows\n        }\n\n        headings = Counter(\n            row[\n                "source_heading_hint"\n            ]\n            for row in rows\n        )\n\n        family_summary.append({\n            "family_candidate":\n                family,\n\n            "component_candidate":\n                component,\n\n            "table_orientation_candidate":\n                orientation,\n\n            "table_count":\n                len(\n                    rows\n                ),\n\n            "report_count":\n                len(\n                    reports\n                ),\n\n            "unique_heading_count":\n                len(\n                    headings\n                ),\n\n            "top_headings_json":\n                json.dumps(\n                    headings.most_common(\n                        30\n                    ),\n                    ensure_ascii=False,\n                ),\n        })\n\n    heading_summary = [\n        {\n            "source_heading_hint":\n                heading,\n\n            "candidate_table_count":\n                count,\n        }\n        for heading, count\n        in heading_counts.most_common()\n    ]\n\n    # ========================================================\n    # Write outputs\n    # ========================================================\n\n    out = args.output_directory\n\n    out.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    candidate_columns = [\n        *BASE,\n        "pdf_candidate_id",\n        "source_path",\n        "page_number",\n        "table_index_on_page",\n        "source_heading_hint",\n        "family_candidate",\n        "component_candidate",\n        "table_orientation_candidate",\n        "discovery_score",\n        "numeric_axis_row_count",\n        "numeric_axis_column",\n        "transposed_axis_detected",\n        "transposed_axis_row",\n        "transposed_sample_count",\n        "buffer_axis_detected",\n        "time_header_match_count",\n        "signal_header_match_count",\n        "modal_populated_width",\n        "modal_width_row_count",\n        "group2_handoff_page_support",\n        "group2_handoff_match_count",\n        "group2_handoff_headings_json",\n        "discovery_reasons",\n        "processing_status",\n        "requires_review",\n        "source_rows_json",\n        "page_text_context",\n    ]\n\n    write_csv(\n        out\n        / "pdf_timeseries_candidate_tables.csv",\n        candidates,\n        candidate_columns,\n    )\n\n    write_csv(\n        out\n        / "pdf_review_tables.csv",\n        reviews,\n        candidate_columns,\n    )\n\n    write_csv(\n        out\n        / "pdf_timeseries_candidate_rows.csv",\n        candidate_rows,\n        [\n            *BASE,\n            "pdf_candidate_id",\n            "page_number",\n            "table_index_on_page",\n            "source_heading_hint",\n            "family_candidate",\n            "table_orientation_candidate",\n            "table_row_index",\n            "source_row_json",\n            "populated_cell_count",\n            "first_populated_value",\n        ],\n    )\n\n    write_csv(\n        out\n        / "pdf_report_coverage.csv",\n        coverage,\n        [\n            *BASE,\n            "pdf_available",\n            "pdf_processed",\n            "page_count",\n            "table_count",\n            "candidate_table_count",\n            "review_table_count",\n            "group2_handoff_locator_count",\n            "status",\n            "issue",\n        ],\n    )\n\n    write_csv(\n        out\n        / "pdf_heading_summary.csv",\n        heading_summary,\n        [\n            "source_heading_hint",\n            "candidate_table_count",\n        ],\n    )\n\n    write_csv(\n        out\n        / "pdf_family_summary.csv",\n        family_summary,\n        [\n            "family_candidate",\n            "component_candidate",\n            "table_orientation_candidate",\n            "table_count",\n            "report_count",\n            "unique_heading_count",\n            "top_headings_json",\n        ],\n    )\n\n    write_csv(\n        out\n        / "errors.csv",\n        errors,\n        [\n            *BASE,\n            "source_path",\n            "page_number",\n            "stage",\n            "error",\n        ],\n    )\n\n    # ========================================================\n    # Metadata\n    # ========================================================\n\n    processed_count = sum(\n        1\n        for row in coverage\n        if str(\n            row[\n                "pdf_processed"\n            ]\n        ).casefold()\n        == "true"\n    )\n\n    reports_with_candidates = sum(\n        1\n        for row in coverage\n        if int(\n            row[\n                "candidate_table_count"\n            ]\n        ) > 0\n    )\n\n    candidates_with_handoff_support = sum(\n        1\n        for row in candidates\n        if str(\n            row[\n                "group2_handoff_page_support"\n            ]\n        ).casefold()\n        == "true"\n    )\n\n    metadata = {\n\n        "created_at":\n            datetime.now(\n                timezone.utc\n            ).isoformat(),\n\n        "group":\n            "Group 4 - Time-series measurements",\n\n        "stage":\n            "PDF-only discovery",\n\n        "reports_in_index":\n            len(\n                index_rows\n            ),\n\n        "pdf_only_reports_selected":\n            len(\n                pdf_only_reports\n            ),\n\n        "pdf_reports_processed":\n            processed_count,\n\n        "reports_with_timeseries_candidates":\n            reports_with_candidates,\n\n        "candidate_table_count":\n            len(\n                candidates\n            ),\n\n        "candidate_row_count":\n            len(\n                candidate_rows\n            ),\n\n        "review_table_count":\n            len(\n                reviews\n            ),\n\n        "candidate_family_counts":\n            dict(\n                family_counts\n            ),\n\n        "candidate_orientation_counts":\n            dict(\n                orientation_counts\n            ),\n\n        "unique_candidate_heading_hints":\n            len(\n                heading_counts\n            ),\n\n        "top_candidate_heading_hints":\n            heading_counts.most_common(\n                30\n            ),\n\n        "coverage_status_counts":\n            dict(\n                coverage_counts\n            ),\n\n        "group2_handoff_total_locator_sections":\n            handoff[\n                "count"\n            ],\n\n        "candidate_tables_with_group2_handoff_page_support":\n            candidates_with_handoff_support,\n\n        "source_errors":\n            len(\n                errors\n            ),\n\n        "scope":\n            (\n                "PDF-only discovery for Group 4 time-series "\n                "measurements. Only reports without an available CSV "\n                "source are processed. Original PDFs are the discovery "\n                "source. The frozen Group 2 PDF time-series handoff is "\n                "used only as supporting page-level locator evidence. "\n                "Candidate detection uses repeated numeric-axis rows, "\n                "transposed time axes, buffer axes, time/index headers, "\n                "measurement headers, repeated table geometry, and "\n                "known temporal family headings. No final structured "\n                "extraction, semantic normalization, unit conversion, "\n                "event identity inference, or CSV/PDF integration is "\n                "performed."\n            ),\n    }\n\n    tmp = (\n        out\n        / "metadata.json.part"\n    )\n\n    tmp.write_text(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        ),\n        encoding="utf-8",\n    )\n\n    tmp.replace(\n        out\n        / "metadata.json"\n    )\n\n    print()\n    print(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        )\n    )\n\n    print()\n    print(\n        f"Outputs: {out}"\n    )\n\n    print()\n    print(\n        "GROUP 4 PDF-ONLY DISCOVERY COMPLETE."\n    )\n\n\n'

_PDF_AUDIT_SOURCE = '"""\nAudit Group 4 PDF-only time-series candidates.\n\nInputs\n------\ndata/processed/edr/group4_pdf_discovery_v1/\n    pdf_timeseries_candidate_tables.csv\n    pdf_review_tables.csv\n\nOutputs\n-------\ndata/processed/edr/group4_pdf_audit_v1/\n\n    accepted_timeseries_tables.csv\n    companion_metadata_tables.csv\n    excluded_non_timeseries_tables.csv\n    remaining_review_tables.csv\n    audit_all_tables.csv\n    family_summary.csv\n    decision_summary.csv\n    metadata.json\n\nPurpose\n-------\nThis stage audits PDF discovery results before structured extraction.\n\nIt:\n\n1. Re-evaluates all discovery candidates.\n2. Re-evaluates all near-threshold review tables.\n3. Recognizes:\n       - samples-by-rows temporal tables\n       - samples-by-columns / transposed tables\n       - "Parameter | -5 sec | -4 sec ..." pre-crash tables\n       - repeated time/signal blocks\n4. Separates:\n       - accepted time-series\n       - time-series companion metadata\n       - explicit non-time-series structures\n       - graphical/garbled structures requiring review\n       - unresolved review cases\n5. Refines structural family classification using the actual table,\n   not only the PDF page heading.\n6. Preserves continuation hints such as "Table 1 of 4".\n\nThis stage does NOT:\n- extract final sample/value datasets,\n- normalize signals,\n- convert units,\n- infer event identity,\n- merge physical PDF tables,\n- or modify the frozen Group 4 CSV package.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport hashlib\nimport json\nimport re\n\nfrom collections import Counter, defaultdict\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\n\ncsv.field_size_limit(100_000_000)\n\n\nBASE = [\n    "report_id",\n    "case_id",\n    "vehicle_number",\n    "export_basename",\n]\n\n\n# ============================================================\n# I/O\n# ============================================================\n\ndef read_csv(path: Path):\n    with path.open(\n        encoding="utf-8-sig",\n        newline="",\n    ) as f:\n        return list(\n            csv.DictReader(f)\n        )\n\n\ndef write_csv(\n    path: Path,\n    rows: list[dict],\n    columns: list[str],\n):\n    tmp = path.with_suffix(\n        path.suffix + ".part"\n    )\n\n    with tmp.open(\n        "w",\n        encoding="utf-8-sig",\n        newline="",\n    ) as f:\n\n        writer = csv.DictWriter(\n            f,\n            fieldnames=columns,\n            extrasaction="ignore",\n        )\n\n        writer.writeheader()\n        writer.writerows(rows)\n\n    tmp.replace(path)\n\n\n# ============================================================\n# General helpers\n# ============================================================\n\ndef norm(value):\n    return re.sub(\n        r"\\s+",\n        " ",\n        str(\n            value\n            if value is not None\n            else ""\n        ).strip(),\n    )\n\n\ndef norm_key(value):\n    return norm(\n        re.sub(\n            r"[^a-z0-9]+",\n            " ",\n            norm(value).casefold(),\n        )\n    )\n\n\ndef identifier(*parts):\n    text = "|".join(\n        norm(part)\n        for part in parts\n    )\n\n    return hashlib.sha256(\n        text.encode(\n            "utf-8"\n        )\n    ).hexdigest()[:24]\n\n\ndef load_rows(value):\n    try:\n        rows = json.loads(\n            value\n        )\n\n        if isinstance(\n            rows,\n            list,\n        ):\n            return rows\n\n    except (\n        json.JSONDecodeError,\n        TypeError,\n    ):\n        pass\n\n    return []\n\n\ndef populated(row):\n    return [\n        norm(value)\n        for value in row\n        if norm(value)\n    ]\n\n\ndef row_text(row):\n    return " ".join(\n        populated(\n            row\n        )\n    )\n\n\ndef table_text(rows):\n    return " ".join(\n        row_text(\n            row\n        )\n        for row in rows\n    )\n\n\ndef first_populated(row):\n    for index, value in enumerate(\n        row\n    ):\n\n        value = norm(\n            value\n        )\n\n        if value:\n            return (\n                index,\n                value,\n            )\n\n    return (\n        None,\n        "",\n    )\n\n\n# ============================================================\n# Numeric / axis helpers\n# ============================================================\n\ndef strip_axis_annotation(value):\n    text = norm(\n        value\n    )\n\n    # Examples:\n    # -5 sec\n    # -0.5 seconds\n    # 10 ms\n    # -5 count\n    # 0 (TRG)\n\n    text = re.sub(\n        r"\\(\\s*TRG[^)]*\\)\\s*$",\n        "",\n        text,\n        flags=re.I,\n    )\n\n    text = re.sub(\n        r"\\s+count\\s*$",\n        "",\n        text,\n        flags=re.I,\n    )\n\n    text = re.sub(\n        r"\\s*(?:"\n        r"seconds?|"\n        r"secs?|"\n        r"msec|"\n        r"milliseconds?|"\n        r"ms"\n        r")\\s*$",\n        "",\n        text,\n        flags=re.I,\n    )\n\n    return norm(\n        text\n    )\n\n\ndef is_numeric_axis_token(value):\n    text = strip_axis_annotation(\n        value\n    )\n\n    text = text.replace(\n        ",",\n        "",\n    )\n\n    return bool(\n        re.fullmatch(\n            r"[-+]?"\n            r"(?:\\d+(?:\\.\\d*)?|\\.\\d+)"\n            r"(?:[eE][-+]?\\d+)?",\n            text,\n        )\n    )\n\n\ndef is_time_header(value):\n    text = norm_key(\n        value\n    )\n\n    return bool(\n        re.search(\n            r"\\b(?:"\n            r"time|"\n            r"times|"\n            r"seconds before|"\n            r"seconds after|"\n            r"sample count|"\n            r"relative time|"\n            r"buffer address"\n            r")\\b",\n            text,\n            re.I,\n        )\n    )\n\n\ndef is_parameter_axis_header(value):\n    return bool(\n        re.search(\n            r"\\bparameter\\b",\n            norm(\n                value\n            ),\n            re.I,\n        )\n    )\n\n\n# ============================================================\n# Structural temporal detection\n# ============================================================\n\ndef detect_samples_by_rows(rows):\n    """\n    Identify tables such as:\n\n        Time (ms) | Delta-V\n        10        | 0.0\n        20        | -0.5\n        30        | -1.0\n\n    or:\n\n        Seconds Before AE | Vehicle Speed | ...\n        -5                | ...\n        -4                | ...\n    """\n\n    best = None\n\n    for header_index, row in enumerate(\n        rows[:8]\n    ):\n\n        axis_col, header_value = (\n            first_populated(\n                row\n            )\n        )\n\n        if axis_col is None:\n            continue\n\n        if not is_time_header(\n            header_value\n        ):\n            continue\n\n        numeric_rows = []\n\n        for row_index in range(\n            header_index + 1,\n            len(\n                rows\n            ),\n        ):\n\n            candidate = rows[\n                row_index\n            ]\n\n            if axis_col >= len(\n                candidate\n            ):\n                continue\n\n            axis_value = norm(\n                candidate[\n                    axis_col\n                ]\n            )\n\n            if not is_numeric_axis_token(\n                axis_value\n            ):\n                continue\n\n            if len(\n                populated(\n                    candidate\n                )\n            ) < 2:\n                continue\n\n            numeric_rows.append(\n                row_index\n            )\n\n        if len(\n            numeric_rows\n        ) < 2:\n            continue\n\n        candidate = {\n            "header_row_index":\n                header_index,\n\n            "axis_column_index":\n                axis_col,\n\n            "sample_row_count":\n                len(\n                    numeric_rows\n                ),\n\n            "sample_row_indexes":\n                numeric_rows,\n\n            "axis_label":\n                header_value,\n        }\n\n        if (\n            best is None\n            or candidate[\n                "sample_row_count"\n            ]\n            > best[\n                "sample_row_count"\n            ]\n        ):\n            best = candidate\n\n    return best\n\n\ndef detect_samples_by_columns(rows):\n    """\n    Identify tables such as:\n\n        Time (ms) | 0 | 10 | 20 | 30\n        Delta-V   | 0 | -1 | -2 | -3\n\n    and:\n\n        Parameter     | -5 sec | -4 sec | -3 sec\n        Vehicle Speed | 50     | 48     | 45\n    """\n\n    best = None\n\n    for header_index, row in enumerate(\n        rows[:10]\n    ):\n\n        values = [\n            norm(value)\n            for value in row\n        ]\n\n        if not values:\n            continue\n\n        first_col, first_value = (\n            first_populated(\n                row\n            )\n        )\n\n        if first_col is None:\n            continue\n\n        valid_header = (\n            is_time_header(\n                first_value\n            )\n            or is_parameter_axis_header(\n                first_value\n            )\n        )\n\n        if not valid_header:\n            continue\n\n        axis_columns = [\n            column_index\n            for column_index, value\n            in enumerate(values)\n            if (\n                column_index\n                != first_col\n                and is_numeric_axis_token(\n                    value\n                )\n            )\n        ]\n\n        if len(\n            axis_columns\n        ) < 2:\n            continue\n\n        signal_rows = []\n\n        for row_index in range(\n            header_index + 1,\n            len(\n                rows\n            ),\n        ):\n\n            signal_row = rows[\n                row_index\n            ]\n\n            _, label = first_populated(\n                signal_row\n            )\n\n            if not label:\n                continue\n\n            values_on_axis = sum(\n                1\n                for column_index\n                in axis_columns\n                if (\n                    column_index\n                    < len(\n                        signal_row\n                    )\n                    and norm(\n                        signal_row[\n                            column_index\n                        ]\n                    )\n                )\n            )\n\n            if values_on_axis >= 2:\n                signal_rows.append(\n                    row_index\n                )\n\n        if not signal_rows:\n            continue\n\n        candidate = {\n            "header_row_index":\n                header_index,\n\n            "axis_columns":\n                axis_columns,\n\n            "sample_count":\n                len(\n                    axis_columns\n                ),\n\n            "signal_row_count":\n                len(\n                    signal_rows\n                ),\n\n            "signal_row_indexes":\n                signal_rows,\n\n            "axis_label":\n                first_value,\n        }\n\n        if (\n            best is None\n            or candidate[\n                "sample_count"\n            ]\n            > best[\n                "sample_count"\n            ]\n        ):\n            best = candidate\n\n    return best\n\n\ndef detect_repeated_transposed_blocks(rows):\n    """\n    Identify a table containing multiple transposed time/signal blocks.\n\n    Example:\n\n        Time (ms)     0 10 20 ...\n        Delta-V       0 -1 -2 ...\n        Time (ms)     80 90 ...\n        Delta-V       ...\n    """\n\n    blocks = []\n\n    for row_index, row in enumerate(\n        rows\n    ):\n\n        first_col, first_value = (\n            first_populated(\n                row\n            )\n        )\n\n        if first_col is None:\n            continue\n\n        if not is_time_header(\n            first_value\n        ):\n            continue\n\n        axis_count = sum(\n            1\n            for column_index, value\n            in enumerate(row)\n            if (\n                column_index\n                != first_col\n                and is_numeric_axis_token(\n                    value\n                )\n            )\n        )\n\n        if axis_count < 2:\n            continue\n\n        if (\n            row_index + 1\n            >= len(\n                rows\n            )\n        ):\n            continue\n\n        next_row = rows[\n            row_index + 1\n        ]\n\n        next_values = populated(\n            next_row\n        )\n\n        if len(\n            next_values\n        ) < 3:\n            continue\n\n        blocks.append(\n            row_index\n        )\n\n    return blocks\n\n\n# ============================================================\n# Companion metadata detection\n# ============================================================\n\nCOMPANION_PATTERNS = [\n    r"\\brecording status\\b.*\\btime series data\\b",\n    r"\\btime from trg to next sample\\b",\n    r"\\bmaximum delta[- ]?v\\b",\n    r"\\btime,?\\s*maximum delta[- ]?v\\b",\n    r"\\bclipping time\\b",\n    r"\\blength of delta[- ]?v\\b",\n    r"\\brollangle peak\\b",\n    r"\\broll angle at (?:the )?time of trg\\b",\n    r"\\btrg count\\b",\n    r"\\bevent type\\b",\n    r"\\bprevious crash type\\b",\n    r"\\bfreeze signal\\b",\n    r"\\bdiagnostic trouble codes?\\b",\n    r"\\bignition cycle since dtc\\b",\n    r"\\bedr generation\\b",\n    r"\\bcomplete file recorded\\b",\n]\n\n\ndef companion_score(rows):\n    text = table_text(\n        rows\n    )\n\n    matches = [\n        pattern\n        for pattern\n        in COMPANION_PATTERNS\n        if re.search(\n            pattern,\n            text,\n            re.I,\n        )\n    ]\n\n    return (\n        len(\n            matches\n        ),\n        matches,\n    )\n\n\n# ============================================================\n# Explicit non-time-series detection\n# ============================================================\n\nNON_TIMESERIES_PATTERNS = [\n    (\n        "event_record_summary",\n        r"\\bevent record summary\\b",\n    ),\n\n    (\n        "dtc_structure",\n        r"\\bdtcs?\\s+present\\b",\n    ),\n\n    (\n        "system_status",\n        r"\\bsystem\\s+(?:status|configuration)\\b",\n    ),\n\n    (\n        "deployment_scalar",\n        r"\\bdeployment\\s+(?:command\\s+)?data\\b",\n    ),\n]\n\n\ndef explicit_non_timeseries_reason(\n    rows,\n):\n    text = table_text(\n        rows\n    )\n\n    for reason, pattern in (\n        NON_TIMESERIES_PATTERNS\n    ):\n\n        if re.search(\n            pattern,\n            text,\n            re.I,\n        ):\n            return reason\n\n    return ""\n\n\n# ============================================================\n# Numbered legends / deployment lists\n# ============================================================\n\ndef is_numbered_legend(rows):\n    """\n    Detect structures like:\n\n        1 | Driver Airbag Deployment Time\n        2 | Passenger Airbag Deployment Time\n        3 | Pretensioner Deployment\n\n    These are index/legend structures, not sampled time-series.\n    """\n\n    numeric_first = 0\n    temporal_headers = 0\n\n    for row in rows:\n\n        column, value = first_populated(\n            row\n        )\n\n        if column is None:\n            continue\n\n        if is_numeric_axis_token(\n            value\n        ):\n            numeric_first += 1\n\n        if is_time_header(\n            value\n        ):\n            temporal_headers += 1\n\n    return (\n        numeric_first >= 3\n        and temporal_headers == 0\n    )\n\n\n# ============================================================\n# Garbled graphical table detection\n# ============================================================\n\ndef duplicated_character_ratio(text):\n    """\n    PDF plot text often appears as:\n\n        DDeellttaa--VV\n        LLoonnggiittuuddiinnaall\n\n    Estimate repeated-character corruption.\n    """\n\n    letters = [\n        char\n        for char in text\n        if char.isalpha()\n    ]\n\n    if len(\n        letters\n    ) < 8:\n        return 0.0\n\n    repeated = 0\n\n    for index in range(\n        1,\n        len(\n            letters\n        )\n    ):\n\n        if (\n            letters[\n                index\n            ].lower()\n            ==\n            letters[\n                index - 1\n            ].lower()\n        ):\n            repeated += 1\n\n    return (\n        repeated\n        / max(\n            1,\n            len(\n                letters\n            )\n            - 1,\n        )\n    )\n\n\ndef is_garbled_graphical_structure(\n    rows,\n):\n    """\n    Identify plot/graph extraction where numeric axes are collapsed\n    into single cells instead of a usable source table.\n    """\n\n    if len(\n        rows\n    ) > 8:\n        return False\n\n    text = table_text(\n        rows\n    )\n\n    has_graph_terms = bool(\n        re.search(\n            r"\\b(?:"\n            r"delta[- ]?v|"\n            r"crash pulse|"\n            r"acceleration"\n            r")\\b",\n            text,\n            re.I,\n        )\n    )\n\n    has_time_embedded = bool(\n        re.search(\n            r"\\btime\\s*\\(?(?:msec|ms|milliseconds?)\\)?",\n            text,\n            re.I,\n        )\n    )\n\n    long_single_cells = sum(\n        1\n        for row in rows\n        for value in row\n        if len(\n            norm(\n                value\n            )\n        ) > 60\n    )\n\n    repeated_ratio = (\n        duplicated_character_ratio(\n            text\n        )\n    )\n\n    return (\n        has_graph_terms\n        and (\n            long_single_cells >= 2\n            or repeated_ratio > 0.18\n        )\n        and has_time_embedded\n    )\n\n\n# ============================================================\n# Family refinement\n# ============================================================\n\ndef temporal_header_text(rows):\n    pieces = []\n\n    for row in rows[:5]:\n\n        values = populated(\n            row\n        )\n\n        if not values:\n            continue\n\n        pieces.extend(\n            values[:8]\n        )\n\n    return " ".join(\n        pieces\n    )\n\n\ndef refine_family(\n    rows,\n    heading_hint,\n    original_family,\n):\n    """\n    Structural table content has priority over broad PDF page headings.\n    """\n\n    header_text = temporal_header_text(\n        rows\n    )\n\n    table = table_text(\n        rows\n    )\n\n    combined = (\n        header_text\n        + " "\n        + norm(\n            heading_hint\n        )\n    )\n\n    # --------------------------------------------------------\n    # Pre-crash\n    # --------------------------------------------------------\n\n    if re.search(\n        r"\\bseconds?\\s+before\\s+(?:ae|event)\\b",\n        header_text,\n        re.I,\n    ):\n        return "pre_crash"\n\n    if re.search(\n        r"\\bpre[-_ ]?crash\\b",\n        combined,\n        re.I,\n    ):\n        return "pre_crash"\n\n    if (\n        re.search(\n            r"\\bparameter\\b",\n            header_text,\n            re.I,\n        )\n        and re.search(\n            r"-\\s*\\d+(?:\\.\\d+)?\\s*sec",\n            header_text,\n            re.I,\n        )\n    ):\n        return "pre_crash"\n\n    # --------------------------------------------------------\n    # Roll angle before generic acceleration\n    # --------------------------------------------------------\n\n    if re.search(\n        r"\\bvehicle\\s+roll\\s+angle\\b|\\broll\\s+angle\\b",\n        header_text,\n        re.I,\n    ):\n        return "roll_angle"\n\n    # --------------------------------------------------------\n    # Angular / rollover\n    # --------------------------------------------------------\n\n    if re.search(\n        r"\\broll\\s+rate\\b|\\bangular\\s+rate\\b",\n        header_text,\n        re.I,\n    ):\n        return "angular_rate"\n\n    # --------------------------------------------------------\n    # Delta-V\n    # --------------------------------------------------------\n\n    if re.search(\n        r"\\b(?:"\n        r"delta[- ]?v|"\n        r"recorded velocity change|"\n        r"velocity change"\n        r")\\b",\n        header_text,\n        re.I,\n    ):\n        return "delta_v"\n\n    # --------------------------------------------------------\n    # Acceleration\n    # --------------------------------------------------------\n\n    if re.search(\n        r"\\bacceleration\\b",\n        header_text,\n        re.I,\n    ):\n        return "acceleration"\n\n    # --------------------------------------------------------\n    # Crash pulse\n    # --------------------------------------------------------\n\n    if re.search(\n        r"\\bcrash pulse\\b",\n        combined,\n        re.I,\n    ):\n        return "crash_pulse"\n\n    return (\n        norm(\n            original_family\n        )\n        or "other_timeseries"\n    )\n\n\ndef refine_component(\n    rows,\n    heading_hint,\n    original_component,\n):\n    text = (\n        temporal_header_text(\n            rows\n        )\n        + " "\n        + norm(\n            heading_hint\n        )\n    )\n\n    has_longitudinal = bool(\n        re.search(\n            r"\\blongitudinal\\b",\n            text,\n            re.I,\n        )\n    )\n\n    has_lateral = bool(\n        re.search(\n            r"\\blateral\\b",\n            text,\n            re.I,\n        )\n    )\n\n    if (\n        has_longitudinal\n        and has_lateral\n    ):\n        return (\n            "longitudinal_lateral"\n        )\n\n    if has_longitudinal:\n        return "longitudinal"\n\n    if has_lateral:\n        return "lateral"\n\n    if re.search(\n        r"\\b(?:normal|vertical)\\b",\n        text,\n        re.I,\n    ):\n        return "normal_vertical"\n\n    if re.search(\n        r"\\b(?:roll|angular)\\b",\n        text,\n        re.I,\n    ):\n        return "roll_angular"\n\n    return (\n        norm(\n            original_component\n        )\n        or "unspecified"\n    )\n\n\n# ============================================================\n# Continuation / multi-part hints\n# ============================================================\n\nTABLE_PART_PATTERN = re.compile(\n    r"\\btable\\s+(\\d+)\\s+of\\s+(\\d+)\\b",\n    re.I,\n)\n\n\ndef extract_table_part(\n    heading,\n):\n    match = TABLE_PART_PATTERN.search(\n        norm(\n            heading\n        )\n    )\n\n    if not match:\n        return (\n            "",\n            "",\n        )\n\n    return (\n        int(\n            match.group(\n                1\n            )\n        ),\n        int(\n            match.group(\n                2\n            )\n        ),\n    )\n\n\ndef continuation_heading_key(\n    heading,\n):\n    text = norm(\n        heading\n    )\n\n    text = TABLE_PART_PATTERN.sub(\n        "",\n        text,\n    )\n\n    text = re.sub(\n        r"\\s*[-–—]\\s*$",\n        "",\n        text,\n    )\n\n    return norm_key(\n        text\n    )\n\n\n# ============================================================\n# Header signature\n# ============================================================\n\ndef build_header_signature(\n    rows,\n    row_structure,\n    column_structure,\n):\n    if row_structure is not None:\n\n        row_index = (\n            row_structure[\n                "header_row_index"\n            ]\n        )\n\n        return norm_key(\n            " | ".join(\n                populated(\n                    rows[\n                        row_index\n                    ]\n                )\n            )\n        )\n\n    if column_structure is not None:\n\n        row_index = (\n            column_structure[\n                "header_row_index"\n            ]\n        )\n\n        first_header = norm(\n            rows[\n                row_index\n            ][0]\n            if rows[\n                row_index\n            ]\n            else ""\n        )\n\n        signal_labels = []\n\n        for signal_row_index in (\n            column_structure[\n                "signal_row_indexes"\n            ]\n        ):\n\n            _, label = (\n                first_populated(\n                    rows[\n                        signal_row_index\n                    ]\n                )\n            )\n\n            if label:\n                signal_labels.append(\n                    label\n                )\n\n        return norm_key(\n            " | ".join(\n                [\n                    first_header,\n                    *signal_labels,\n                ]\n            )\n        )\n\n    return ""\n\n\n# ============================================================\n# Audit one table\n# ============================================================\n\ndef audit_table(\n    source,\n):\n    rows = load_rows(\n        source.get(\n            "source_rows_json",\n            ""\n        )\n    )\n\n    heading = norm(\n        source.get(\n            "source_heading_hint",\n            ""\n        )\n    )\n\n    # --------------------------------------------------------\n    # Structural detection\n    # --------------------------------------------------------\n\n    row_structure = (\n        detect_samples_by_rows(\n            rows\n        )\n    )\n\n    column_structure = (\n        detect_samples_by_columns(\n            rows\n        )\n    )\n\n    repeated_blocks = (\n        detect_repeated_transposed_blocks(\n            rows\n        )\n    )\n\n    companion_count, companion_matches = (\n        companion_score(\n            rows\n        )\n    )\n\n    non_timeseries_reason = (\n        explicit_non_timeseries_reason(\n            rows\n        )\n    )\n\n    numbered_legend = (\n        is_numbered_legend(\n            rows\n        )\n    )\n\n    graphical = (\n        is_garbled_graphical_structure(\n            rows\n        )\n    )\n\n    family = refine_family(\n        rows,\n        heading,\n        source.get(\n            "family_candidate",\n            "",\n        ),\n    )\n\n    component = refine_component(\n        rows,\n        heading,\n        source.get(\n            "component_candidate",\n            "",\n        ),\n    )\n\n    # --------------------------------------------------------\n    # Orientation\n    # --------------------------------------------------------\n\n    if column_structure is not None:\n\n        orientation = (\n            "samples_by_columns"\n        )\n\n    elif row_structure is not None:\n\n        orientation = (\n            "samples_by_rows"\n        )\n\n    else:\n\n        orientation = (\n            "unknown"\n        )\n\n    # --------------------------------------------------------\n    # Decision\n    # --------------------------------------------------------\n\n    structural_timeseries = (\n        row_structure is not None\n        or column_structure is not None\n    )\n\n    if structural_timeseries:\n\n        decision = "accept"\n\n        audit_status = (\n            "accepted_structural_timeseries"\n        )\n\n        audit_reason = (\n            "validated_temporal_axis_structure"\n        )\n\n    elif graphical:\n\n        decision = "review"\n\n        audit_status = (\n            "review_graphical_timeseries"\n        )\n\n        audit_reason = (\n            "graphical_or_garbled_pdf_structure"\n        )\n\n    elif numbered_legend:\n\n        decision = "exclude"\n\n        audit_status = (\n            "excluded_numbered_legend"\n        )\n\n        audit_reason = (\n            "ordered_labels_not_sampled_time_axis"\n        )\n\n    elif non_timeseries_reason:\n\n        decision = "exclude"\n\n        audit_status = (\n            "excluded_known_non_timeseries"\n        )\n\n        audit_reason = (\n            non_timeseries_reason\n        )\n\n    elif companion_count >= 2:\n\n        decision = "companion"\n\n        audit_status = (\n            "companion_metadata"\n        )\n\n        audit_reason = (\n            "timeseries_context_without_sample_axis"\n        )\n\n    else:\n\n        decision = "review"\n\n        audit_status = (\n            "remaining_review"\n        )\n\n        audit_reason = (\n            "insufficient_structural_evidence"\n        )\n\n    # --------------------------------------------------------\n    # Continuation hints\n    # --------------------------------------------------------\n\n    (\n        table_part_index,\n        table_part_total,\n    ) = extract_table_part(\n        heading\n    )\n\n    continuation_key = ""\n\n    if table_part_total:\n\n        continuation_key = (\n            "g4pdfcont_"\n            + identifier(\n                source.get(\n                    "report_id",\n                    "",\n                ),\n                continuation_heading_key(\n                    heading\n                ),\n                family,\n                component,\n            )\n        )\n\n    header_signature = (\n        build_header_signature(\n            rows,\n            row_structure,\n            column_structure,\n        )\n    )\n\n    # --------------------------------------------------------\n    # Counts\n    # --------------------------------------------------------\n\n    if row_structure is not None:\n\n        detected_sample_count = (\n            row_structure[\n                "sample_row_count"\n            ]\n        )\n\n        detected_signal_count = ""\n\n    elif column_structure is not None:\n\n        detected_sample_count = (\n            column_structure[\n                "sample_count"\n            ]\n        )\n\n        detected_signal_count = (\n            column_structure[\n                "signal_row_count"\n            ]\n        )\n\n    else:\n\n        detected_sample_count = ""\n        detected_signal_count = ""\n\n    return {\n        "decision":\n            decision,\n\n        "audit_status":\n            audit_status,\n\n        "audit_reason":\n            audit_reason,\n\n        "audited_family":\n            family,\n\n        "audited_component":\n            component,\n\n        "audited_orientation":\n            orientation,\n\n        "detected_sample_count":\n            detected_sample_count,\n\n        "detected_signal_count":\n            detected_signal_count,\n\n        "row_axis_detected":\n            row_structure\n            is not None,\n\n        "column_axis_detected":\n            column_structure\n            is not None,\n\n        "repeated_transposed_block_count":\n            len(\n                repeated_blocks\n            ),\n\n        "companion_pattern_count":\n            companion_count,\n\n        "companion_patterns_json":\n            json.dumps(\n                companion_matches,\n                ensure_ascii=False,\n            ),\n\n        "numbered_legend_detected":\n            numbered_legend,\n\n        "graphical_structure_detected":\n            graphical,\n\n        "non_timeseries_reason":\n            non_timeseries_reason,\n\n        "header_signature":\n            header_signature,\n\n        "table_part_index":\n            table_part_index,\n\n        "table_part_total":\n            table_part_total,\n\n        "continuation_candidate_key":\n            continuation_key,\n    }\n\n\n# ============================================================\n# Main\n# ============================================================\n\ndef main():\n\n    parser = argparse.ArgumentParser(\n        description=__doc__\n    )\n\n    parser.add_argument(\n        "--discovery-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group4_pdf_discovery_v1"\n        ),\n    )\n\n    parser.add_argument(\n        "--output-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group4_pdf_audit_v1"\n        ),\n    )\n\n    args = parser.parse_args()\n\n    discovery = (\n        args.discovery_directory\n    )\n\n    candidate_path = (\n        discovery\n        / "pdf_timeseries_candidate_tables.csv"\n    )\n\n    review_path = (\n        discovery\n        / "pdf_review_tables.csv"\n    )\n\n    if not candidate_path.exists():\n        raise FileNotFoundError(\n            candidate_path\n        )\n\n    if not review_path.exists():\n        raise FileNotFoundError(\n            review_path\n        )\n\n    candidates = read_csv(\n        candidate_path\n    )\n\n    reviews = read_csv(\n        review_path\n    )\n\n    combined = []\n\n    for row in candidates:\n\n        combined.append({\n            **row,\n\n            "discovery_origin":\n                "candidate",\n        })\n\n    for row in reviews:\n\n        combined.append({\n            **row,\n\n            "discovery_origin":\n                "near_threshold_review",\n        })\n\n    audited = []\n\n    for index, source in enumerate(\n        combined,\n        1,\n    ):\n\n        result = audit_table(\n            source\n        )\n\n        audited.append({\n            **source,\n            **result,\n        })\n\n        if (\n            index % 250 == 0\n            or index\n            == len(\n                combined\n            )\n        ):\n\n            print(\n                "Audited Group 4 PDF "\n                f"{index}/{len(combined)} tables...",\n                flush=True,\n            )\n\n    # ========================================================\n    # Split decisions\n    # ========================================================\n\n    accepted = [\n        row\n        for row in audited\n        if row[\n            "decision"\n        ]\n        == "accept"\n    ]\n\n    companions = [\n        row\n        for row in audited\n        if row[\n            "decision"\n        ]\n        == "companion"\n    ]\n\n    excluded = [\n        row\n        for row in audited\n        if row[\n            "decision"\n        ]\n        == "exclude"\n    ]\n\n    remaining_review = [\n        row\n        for row in audited\n        if row[\n            "decision"\n        ]\n        == "review"\n    ]\n\n    # ========================================================\n    # Summaries\n    # ========================================================\n\n    decision_counts = Counter(\n        row[\n            "decision"\n        ]\n        for row in audited\n    )\n\n    status_counts = Counter(\n        row[\n            "audit_status"\n        ]\n        for row in audited\n    )\n\n    origin_decision_counts = Counter(\n        (\n            row[\n                "discovery_origin"\n            ],\n            row[\n                "decision"\n            ],\n        )\n        for row in audited\n    )\n\n    family_counts = Counter(\n        row[\n            "audited_family"\n        ]\n        for row in accepted\n    )\n\n    orientation_counts = Counter(\n        row[\n            "audited_orientation"\n        ]\n        for row in accepted\n    )\n\n    reports_with_accepted = {\n        row[\n            "report_id"\n        ]\n        for row in accepted\n    }\n\n    continuation_tables = [\n        row\n        for row in accepted\n        if row[\n            "continuation_candidate_key"\n        ]\n    ]\n\n    continuation_groups = {\n        row[\n            "continuation_candidate_key"\n        ]\n        for row in continuation_tables\n    }\n\n    # --------------------------------------------------------\n    # Family summary\n    # --------------------------------------------------------\n\n    family_grouped = defaultdict(\n        list\n    )\n\n    for row in accepted:\n\n        family_grouped[\n            (\n                row[\n                    "audited_family"\n                ],\n                row[\n                    "audited_component"\n                ],\n                row[\n                    "audited_orientation"\n                ],\n            )\n        ].append(\n            row\n        )\n\n    family_summary = []\n\n    for (\n        family,\n        component,\n        orientation,\n    ), rows in sorted(\n        family_grouped.items()\n    ):\n\n        family_summary.append({\n            "audited_family":\n                family,\n\n            "audited_component":\n                component,\n\n            "audited_orientation":\n                orientation,\n\n            "table_count":\n                len(\n                    rows\n                ),\n\n            "report_count":\n                len(\n                    {\n                        row[\n                            "report_id"\n                        ]\n                        for row\n                        in rows\n                    }\n                ),\n\n            "origin_candidate_count":\n                sum(\n                    1\n                    for row in rows\n                    if row[\n                        "discovery_origin"\n                    ]\n                    == "candidate"\n                ),\n\n            "origin_review_recovered_count":\n                sum(\n                    1\n                    for row in rows\n                    if row[\n                        "discovery_origin"\n                    ]\n                    == "near_threshold_review"\n                ),\n        })\n\n    # --------------------------------------------------------\n    # Decision summary\n    # --------------------------------------------------------\n\n    decision_summary = []\n\n    for (\n        origin,\n        decision,\n    ), count in sorted(\n        origin_decision_counts.items()\n    ):\n\n        decision_summary.append({\n            "discovery_origin":\n                origin,\n\n            "audit_decision":\n                decision,\n\n            "table_count":\n                count,\n        })\n\n    # ========================================================\n    # Write outputs\n    # ========================================================\n\n    out = args.output_directory\n\n    out.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    audit_columns = list(\n        audited[0].keys()\n    ) if audited else []\n\n    write_csv(\n        out\n        / "audit_all_tables.csv",\n        audited,\n        audit_columns,\n    )\n\n    write_csv(\n        out\n        / "accepted_timeseries_tables.csv",\n        accepted,\n        audit_columns,\n    )\n\n    write_csv(\n        out\n        / "companion_metadata_tables.csv",\n        companions,\n        audit_columns,\n    )\n\n    write_csv(\n        out\n        / "excluded_non_timeseries_tables.csv",\n        excluded,\n        audit_columns,\n    )\n\n    write_csv(\n        out\n        / "remaining_review_tables.csv",\n        remaining_review,\n        audit_columns,\n    )\n\n    write_csv(\n        out\n        / "family_summary.csv",\n        family_summary,\n        [\n            "audited_family",\n            "audited_component",\n            "audited_orientation",\n            "table_count",\n            "report_count",\n            "origin_candidate_count",\n            "origin_review_recovered_count",\n        ],\n    )\n\n    write_csv(\n        out\n        / "decision_summary.csv",\n        decision_summary,\n        [\n            "discovery_origin",\n            "audit_decision",\n            "table_count",\n        ],\n    )\n\n    # ========================================================\n    # Validation\n    # ========================================================\n\n    accounted = (\n        len(\n            accepted\n        )\n        + len(\n            companions\n        )\n        + len(\n            excluded\n        )\n        + len(\n            remaining_review\n        )\n    )\n\n    validation = {\n\n        "input_tables":\n            len(\n                combined\n            ),\n\n        "accounted_tables":\n            accounted,\n\n        "all_tables_accounted_for":\n            (\n                accounted\n                == len(\n                    combined\n                )\n            ),\n\n        "duplicate_candidate_ids":\n            (\n                len(\n                    [\n                        candidate_id\n                        for candidate_id, count\n                        in Counter(\n                            row[\n                                "pdf_candidate_id"\n                            ]\n                            for row\n                            in combined\n                        ).items()\n                        if count > 1\n                    ]\n                )\n            ),\n    }\n\n    if not validation[\n        "all_tables_accounted_for"\n    ]:\n\n        raise RuntimeError(\n            "Audit accounting failure."\n        )\n\n    # ========================================================\n    # Metadata\n    # ========================================================\n\n    metadata = {\n\n        "created_at":\n            datetime.now(\n                timezone.utc\n            ).isoformat(),\n\n        "group":\n            "Group 4 - Time-series measurements",\n\n        "stage":\n            "PDF candidate audit",\n\n        "input_discovery_candidates":\n            len(\n                candidates\n            ),\n\n        "input_near_threshold_reviews":\n            len(\n                reviews\n            ),\n\n        "total_tables_audited":\n            len(\n                combined\n            ),\n\n        "accepted_timeseries_tables":\n            len(\n                accepted\n            ),\n\n        "companion_metadata_tables":\n            len(\n                companions\n            ),\n\n        "excluded_non_timeseries_tables":\n            len(\n                excluded\n            ),\n\n        "remaining_review_tables":\n            len(\n                remaining_review\n            ),\n\n        "reports_with_accepted_timeseries":\n            len(\n                reports_with_accepted\n            ),\n\n        "decision_counts":\n            dict(\n                decision_counts\n            ),\n\n        "audit_status_counts":\n            dict(\n                status_counts\n            ),\n\n        "accepted_family_counts":\n            dict(\n                family_counts\n            ),\n\n        "accepted_orientation_counts":\n            dict(\n                orientation_counts\n            ),\n\n        "recovered_from_near_threshold_review":\n            sum(\n                1\n                for row in accepted\n                if row[\n                    "discovery_origin"\n                ]\n                == "near_threshold_review"\n            ),\n\n        "original_candidates_rejected_or_reviewed":\n            sum(\n                1\n                for row in audited\n                if (\n                    row[\n                        "discovery_origin"\n                    ]\n                    == "candidate"\n                    and row[\n                        "decision"\n                    ]\n                    != "accept"\n                )\n            ),\n\n        "continuation_candidate_table_count":\n            len(\n                continuation_tables\n            ),\n\n        "continuation_candidate_group_count":\n            len(\n                continuation_groups\n            ),\n\n        "validation":\n            validation,\n\n        "scope":\n            (\n                "Audit of all Group 4 PDF discovery candidates and "\n                "near-threshold review tables. Temporal structure is "\n                "validated using explicit row-wise or column-wise "\n                "sample axes. Parameter-by-time pre-crash structures "\n                "are recovered. Companion metadata, numbered deployment "\n                "legends, known scalar/status structures, and graphical "\n                "PDF artifacts are separated. Structural family "\n                "classification is refined from actual table contents. "\n                "Multi-part table numbering is preserved as continuation "\n                "evidence only; physical tables are not merged. No final "\n                "time-series extraction, semantic normalization, unit "\n                "conversion, event identity inference, or CSV/PDF "\n                "integration is performed."\n            ),\n    }\n\n    tmp = (\n        out\n        / "metadata.json.part"\n    )\n\n    tmp.write_text(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        ),\n        encoding="utf-8",\n    )\n\n    tmp.replace(\n        out\n        / "metadata.json"\n    )\n\n    print()\n    print(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        )\n    )\n\n    print()\n    print(\n        f"Outputs: {out}"\n    )\n\n    print()\n    print(\n        "GROUP 4 PDF CANDIDATE AUDIT COMPLETE."\n    )\n\n\n'

_PDF_RESOLVE_SOURCE = '"""\nResolve remaining Group 4 PDF audit review tables.\n\nInputs\n------\ndata/processed/edr/group4_pdf_audit_v1/\n    remaining_review_tables.csv\n    companion_metadata_tables.csv\n    accepted_timeseries_tables.csv\n    excluded_non_timeseries_tables.csv\n\nOutputs\n-------\ndata/processed/edr/group4_pdf_resolved_v1/\n\n    accepted_timeseries_tables.csv\n    companion_metadata_tables.csv\n    excluded_non_timeseries_tables.csv\n    graphical_review_tables.csv\n    remaining_review_tables.csv\n    review_resolution_all.csv\n    resolution_summary.csv\n    metadata.json\n\nPurpose\n-------\nResolve the residual Group 4 PDF review population conservatively.\n\nThe first PDF audit already accepted explicit sampled time-series.\n\nThis resolver addresses tables that lacked an explicit repeated temporal\naxis and separates them into:\n\n1. companion metadata\n2. single-snapshot exclusions\n3. static/report/documentation exclusions\n4. graphical time-series evidence that cannot be safely reconstructed\n   from PDF table extraction\n5. any genuinely unresolved residual\n\nImportant\n---------\nGraphical crash-pulse and Delta-V plots are NOT force-parsed.\n\nExamples of known PDF graphical corruption include strings such as:\n\n    DDeellttaa--VV\n    LLoonnggiittuuddiinnaall\n    CCrraasshh PPuullssee\n\nand collapsed axis text such as:\n\n    0 20 40 60 ... 260 msec\n\nThese remain explicit review evidence.\n\nNo accepted time-series from the first audit are modified.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport json\nimport re\n\nfrom collections import Counter\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\n\ncsv.field_size_limit(100_000_000)\n\n\n# ============================================================\n# I/O\n# ============================================================\n\ndef read_csv(path: Path):\n    with path.open(\n        encoding="utf-8-sig",\n        newline="",\n    ) as f:\n\n        return list(\n            csv.DictReader(f)\n        )\n\n\ndef write_csv(\n    path: Path,\n    rows: list[dict],\n    columns: list[str],\n):\n    tmp = path.with_suffix(\n        path.suffix + ".part"\n    )\n\n    with tmp.open(\n        "w",\n        encoding="utf-8-sig",\n        newline="",\n    ) as f:\n\n        writer = csv.DictWriter(\n            f,\n            fieldnames=columns,\n            extrasaction="ignore",\n        )\n\n        writer.writeheader()\n        writer.writerows(rows)\n\n    tmp.replace(\n        path\n    )\n\n\n# ============================================================\n# General helpers\n# ============================================================\n\ndef norm(value):\n    return re.sub(\n        r"\\s+",\n        " ",\n        str(\n            value\n            if value is not None\n            else ""\n        ).strip(),\n    )\n\n\ndef norm_key(value):\n    return norm(\n        re.sub(\n            r"[^a-z0-9]+",\n            " ",\n            norm(value).casefold(),\n        )\n    )\n\n\ndef load_rows(value):\n    try:\n\n        rows = json.loads(\n            value\n        )\n\n        if isinstance(\n            rows,\n            list,\n        ):\n            return rows\n\n    except (\n        json.JSONDecodeError,\n        TypeError,\n    ):\n        pass\n\n    return []\n\n\ndef populated(row):\n    return [\n        norm(value)\n        for value in row\n        if norm(value)\n    ]\n\n\ndef row_text(row):\n    return " ".join(\n        populated(\n            row\n        )\n    )\n\n\ndef table_text(rows):\n    return " ".join(\n        row_text(row)\n        for row in rows\n    )\n\n\ndef populated_count(row):\n    return len(\n        populated(\n            row\n        )\n    )\n\n\n# ============================================================\n# Graphical PDF detection\n# ============================================================\n\nGRAPHICAL_CORRUPTION_PATTERNS = [\n    r"DDeellttaa",\n    r"LLoonnggiittuuddiinnaall",\n    r"LLaatteerraall",\n    r"CCrraasshh",\n    r"PPuullssee",\n    r"AAAcc?c?e?l?e?r?a?t?i?o?n",\n]\n\n\ndef looks_like_doubled_pdf_text(\n    text,\n):\n    return any(\n        re.search(\n            pattern,\n            text,\n        )\n        for pattern\n        in GRAPHICAL_CORRUPTION_PATTERNS\n    )\n\n\ndef has_collapsed_time_axis(\n    text,\n):\n    """\n    Detect graphical x-axis text collapsed into a single cell.\n\n    Examples:\n        0 20 40 60 ... 260 msec\n        -60 -50 -40 ... 60 Time (msec)\n    """\n\n    if not re.search(\n        r"\\b(?:msec|ms|milliseconds?)\\b",\n        text,\n        re.I,\n    ):\n        return False\n\n    numbers = re.findall(\n        r"(?<![A-Za-z])"\n        r"[-+]?\\d+(?:\\.\\d+)?",\n        text,\n    )\n\n    return (\n        len(numbers) >= 6\n    )\n\n\ndef is_graphical_timeseries(\n    rows,\n    page_text,\n):\n    table = table_text(\n        rows\n    )\n\n    context = (\n        table\n        + " "\n        + norm(\n            page_text\n        )\n    )\n\n    temporal_family = bool(\n        re.search(\n            r"\\b(?:"\n            r"delta[- ]?v|"\n            r"crash pulse|"\n            r"acceleration|"\n            r"cumulative delta"\n            r")\\b",\n            context,\n            re.I,\n        )\n        or looks_like_doubled_pdf_text(\n            context\n        )\n    )\n\n    return (\n        temporal_family\n        and (\n            looks_like_doubled_pdf_text(\n                table\n            )\n            or has_collapsed_time_axis(\n                table\n            )\n        )\n    )\n\n\n# ============================================================\n# Single-sample temporal tables\n# ============================================================\n\ndef is_time_header(value):\n    return bool(\n        re.search(\n            r"\\btime\\b",\n            norm(value),\n            re.I,\n        )\n    )\n\n\ndef is_numeric(value):\n    text = norm(\n        value\n    )\n\n    text = re.sub(\n        r"\\([^)]*\\)",\n        "",\n        text,\n    )\n\n    text = re.sub(\n        r"\\s*(?:"\n        r"msec|"\n        r"ms|"\n        r"milliseconds?|"\n        r"seconds?|"\n        r"secs?"\n        r")\\s*$",\n        "",\n        text,\n        flags=re.I,\n    )\n\n    text = norm(\n        text\n    )\n\n    return bool(\n        re.fullmatch(\n            r"[-+]?"\n            r"(?:\\d+(?:\\.\\d*)?|\\.\\d+)",\n            text,\n        )\n    )\n\n\ndef is_single_sample_temporal(\n    rows,\n):\n    """\n    Example:\n\n        Time (ms) | Normal Acceleration (g)\n        250       | 0.3\n\n    A single timestamp is a snapshot, not a repeated Group 4 series.\n    """\n\n    if len(\n        rows\n    ) != 2:\n        return False\n\n    header = populated(\n        rows[0]\n    )\n\n    data = populated(\n        rows[1]\n    )\n\n    if len(\n        header\n    ) < 2:\n        return False\n\n    if len(\n        data\n    ) < 2:\n        return False\n\n    if not is_time_header(\n        header[0]\n    ):\n        return False\n\n    return is_numeric(\n        data[0]\n    )\n\n\n# ============================================================\n# Scalar-table detection\n# ============================================================\n\ndef is_scalar_two_column_table(\n    rows,\n):\n    """\n    Most residual PDF context consists of repeated:\n\n        field | value\n\n    rows.\n\n    These are not sampled time-series.\n    """\n\n    if len(\n        rows\n    ) < 2:\n        return False\n\n    populated_counts = [\n        populated_count(\n            row\n        )\n        for row in rows\n    ]\n\n    useful = [\n        count\n        for count\n        in populated_counts\n        if count > 0\n    ]\n\n    if not useful:\n        return False\n\n    two_or_less = sum(\n        1\n        for count\n        in useful\n        if count <= 2\n    )\n\n    return (\n        two_or_less\n        / len(\n            useful\n        )\n        >= 0.90\n    )\n\n\n# ============================================================\n# Companion metadata rules\n# ============================================================\n\nCOMPANION_PATTERNS = [\n    r"\\brecording status\\b",\n    r"\\btime series data\\b",\n    r"\\btime from trg to next sample\\b",\n\n    r"\\bmaximum delta[- ]?v\\b",\n    r"\\bmaximum .*velocity change\\b",\n    r"\\btime,?\\s*maximum delta[- ]?v\\b",\n    r"\\btime .* maximum .* velocity change\\b",\n\n    r"\\bclipping time\\b",\n    r"\\blength of delta[- ]?v\\b",\n\n    r"\\broll angle at .*trg\\b",\n    r"\\brollangle peak\\b",\n    r"\\broll angle peak\\b",\n\n    r"\\bevent recording complete\\b",\n    r"\\bcomplete file recorded\\b",\n    r"\\bcrash record locked\\b",\n\n    r"\\btime between events\\b",\n    r"\\bevent counter\\b",\n    r"\\bdeployment event counter\\b",\n\n    r"\\bpre[- ]?crash.*associated\\b",\n    r"\\bvehicle event data .*pre[- ]?crash\\b",\n\n    r"\\btime from algorithm enable\\b",\n    r"\\bdeployment time\\b",\n\n    r"\\balgorithm run time\\b",\n    r"\\bvelocity change during algorithm run time\\b",\n\n    r"\\btrg count\\b",\n    r"\\btime zero\\b",\n]\n\n\nPRECRASH_CONTEXT_PATTERNS = [\n    r"\\bpre[-_ ]?crash data\\b",\n    r"\\bassociated events not recorded\\b",\n    r"\\bextended concatenated event\\b",\n    r"\\bvehicle power mode\\b",\n    r"\\bremote start status\\b",\n    r"\\blow tire pressure warning\\b",\n]\n\n\ndef companion_match_count(\n    text,\n):\n    return sum(\n        1\n        for pattern\n        in COMPANION_PATTERNS\n        if re.search(\n            pattern,\n            text,\n            re.I,\n        )\n    )\n\n\ndef is_precrash_context(\n    text,\n):\n    return any(\n        re.search(\n            pattern,\n            text,\n            re.I,\n        )\n        for pattern\n        in PRECRASH_CONTEXT_PATTERNS\n    )\n\n\n# ============================================================\n# Static / documentation exclusions\n# ============================================================\n\nSTATIC_PATTERNS = [\n    r"\\buser entered vin\\b",\n    r"\\bvehicle identification number\\b",\n    r"\\bmodule serial number\\b",\n    r"\\bpart number\\b",\n    r"\\bsoftware version\\b",\n    r"\\bsoftware date\\b",\n\n    r"\\bdata element name\\b",\n    r"\\bpositive sign notation\\b",\n\n    r"\\bcase number\\b",\n    r"\\bprinted on\\b",\n    r"\\buser\\b",\n\n    r"\\bminimum resultant\\b",\n    r"\\bdoes not deploy the air bag\\b",\n\n    r"\\brestraints system faults\\b",\n]\n\n\ndef is_static_documentation(\n    text,\n):\n    matches = sum(\n        1\n        for pattern\n        in STATIC_PATTERNS\n        if re.search(\n            pattern,\n            text,\n            re.I,\n        )\n    )\n\n    return (\n        matches >= 1\n    )\n\n\n# ============================================================\n# Deployment / status context\n# ============================================================\n\nSTATUS_PATTERNS = [\n    r"\\bsir warning lamp\\b",\n    r"\\bbelt switch\\b",\n    r"\\bseat position\\b",\n    r"\\bpassenger classification\\b",\n    r"\\bair bag indicator\\b",\n    r"\\bdiagnostic trouble codes?\\b",\n    r"\\bignition cycles?\\b",\n    r"\\bdeployment loop commanded\\b",\n    r"\\brollover sensor status\\b",\n    r"\\bside air bag deployment status\\b",\n    r"\\bevent severity status\\b",\n    r"\\balgorithm active\\b",\n]\n\n\ndef is_event_status_context(\n    text,\n):\n    match_count = sum(\n        1\n        for pattern\n        in STATUS_PATTERNS\n        if re.search(\n            pattern,\n            text,\n            re.I,\n        )\n    )\n\n    return (\n        match_count >= 2\n    )\n\n\n# ============================================================\n# Resolve one residual table\n# ============================================================\n\ndef resolve_table(\n    source,\n):\n    rows = load_rows(\n        source.get(\n            "source_rows_json",\n            ""\n        )\n    )\n\n    table = table_text(\n        rows\n    )\n\n    heading = norm(\n        source.get(\n            "source_heading_hint",\n            ""\n        )\n    )\n\n    page_text = norm(\n        source.get(\n            "page_text_context",\n            ""\n        )\n    )\n\n    context = " ".join(\n        [\n            heading,\n            table,\n            page_text,\n        ]\n    )\n\n    # --------------------------------------------------------\n    # 1. Graphical / garbled time-series\n    # --------------------------------------------------------\n\n    if is_graphical_timeseries(\n        rows,\n        page_text,\n    ):\n\n        return {\n            "resolution_decision":\n                "graphical_review",\n\n            "resolution_status":\n                "preserved_graphical_timeseries_evidence",\n\n            "resolution_reason":\n                "pdf_graph_or_plot_not_safely_reconstructable_from_table_text",\n        }\n\n    # --------------------------------------------------------\n    # 2. One-sample snapshots\n    # --------------------------------------------------------\n\n    if is_single_sample_temporal(\n        rows\n    ):\n\n        return {\n            "resolution_decision":\n                "exclude",\n\n            "resolution_status":\n                "excluded_single_snapshot",\n\n            "resolution_reason":\n                "single_temporal_measurement_not_repeated_timeseries",\n        }\n\n    # --------------------------------------------------------\n    # 3. Two-column scalar/context structures\n    # --------------------------------------------------------\n\n    scalar_table = (\n        is_scalar_two_column_table(\n            rows\n        )\n    )\n\n    companion_matches = (\n        companion_match_count(\n            context\n        )\n    )\n\n    if (\n        scalar_table\n        and (\n            companion_matches > 0\n            or is_precrash_context(\n                context\n            )\n            or is_event_status_context(\n                context\n            )\n        )\n    ):\n\n        return {\n            "resolution_decision":\n                "companion",\n\n            "resolution_status":\n                "companion_metadata_resolved",\n\n            "resolution_reason":\n                "scalar_event_or_timeseries_context_without_sample_axis",\n        }\n\n    # --------------------------------------------------------\n    # 4. Static documentation / sign conventions\n    # --------------------------------------------------------\n\n    if (\n        scalar_table\n        and is_static_documentation(\n            context\n        )\n    ):\n\n        return {\n            "resolution_decision":\n                "exclude",\n\n            "resolution_status":\n                "excluded_static_documentation",\n\n            "resolution_reason":\n                "report_or_module_documentation_not_timeseries",\n        }\n\n    # --------------------------------------------------------\n    # 5. Generic scalar structure\n    # --------------------------------------------------------\n\n    if scalar_table:\n\n        return {\n            "resolution_decision":\n                "companion",\n\n            "resolution_status":\n                "companion_scalar_context",\n\n            "resolution_reason":\n                "scalar_field_value_structure_without_sample_axis",\n        }\n\n    # --------------------------------------------------------\n    # 6. Remaining pre-crash context\n    # --------------------------------------------------------\n\n    if is_precrash_context(\n        context\n    ):\n\n        return {\n            "resolution_decision":\n                "companion",\n\n            "resolution_status":\n                "companion_precrash_context",\n\n            "resolution_reason":\n                "precrash_context_without_repeated_sample_axis",\n        }\n\n    # --------------------------------------------------------\n    # 7. Unresolved\n    # --------------------------------------------------------\n\n    return {\n        "resolution_decision":\n            "review",\n\n        "resolution_status":\n            "remaining_review",\n\n        "resolution_reason":\n            "no_safe_structural_resolution_rule",\n    }\n\n\n# ============================================================\n# Main\n# ============================================================\n\ndef main():\n\n    parser = argparse.ArgumentParser(\n        description=__doc__\n    )\n\n    parser.add_argument(\n        "--audit-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group4_pdf_audit_v1"\n        ),\n    )\n\n    parser.add_argument(\n        "--output-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group4_pdf_resolved_v1"\n        ),\n    )\n\n    args = parser.parse_args()\n\n    audit_dir = (\n        args.audit_directory\n    )\n\n    required = {\n        "accepted":\n            audit_dir\n            / "accepted_timeseries_tables.csv",\n\n        "companions":\n            audit_dir\n            / "companion_metadata_tables.csv",\n\n        "excluded":\n            audit_dir\n            / "excluded_non_timeseries_tables.csv",\n\n        "review":\n            audit_dir\n            / "remaining_review_tables.csv",\n    }\n\n    for name, path in required.items():\n\n        if not path.exists():\n\n            raise FileNotFoundError(\n                f"Missing required {name}: "\n                f"{path}"\n            )\n\n    accepted_existing = read_csv(\n        required[\n            "accepted"\n        ]\n    )\n\n    companions_existing = read_csv(\n        required[\n            "companions"\n        ]\n    )\n\n    excluded_existing = read_csv(\n        required[\n            "excluded"\n        ]\n    )\n\n    review_input = read_csv(\n        required[\n            "review"\n        ]\n    )\n\n    # ========================================================\n    # Resolve residual review population\n    # ========================================================\n\n    resolved_rows = []\n\n    for index, source in enumerate(\n        review_input,\n        1,\n    ):\n\n        result = resolve_table(\n            source\n        )\n\n        resolved_rows.append({\n            **source,\n            **result,\n        })\n\n        if (\n            index % 100 == 0\n            or index\n            == len(\n                review_input\n            )\n        ):\n\n            print(\n                "Resolved Group 4 PDF review "\n                f"{index}/"\n                f"{len(review_input)} tables...",\n                flush=True,\n            )\n\n    # ========================================================\n    # Split\n    # ========================================================\n\n    resolved_companions = [\n        row\n        for row\n        in resolved_rows\n        if row[\n            "resolution_decision"\n        ]\n        == "companion"\n    ]\n\n    resolved_excluded = [\n        row\n        for row\n        in resolved_rows\n        if row[\n            "resolution_decision"\n        ]\n        == "exclude"\n    ]\n\n    graphical_review = [\n        row\n        for row\n        in resolved_rows\n        if row[\n            "resolution_decision"\n        ]\n        == "graphical_review"\n    ]\n\n    remaining_review = [\n        row\n        for row\n        in resolved_rows\n        if row[\n            "resolution_decision"\n        ]\n        == "review"\n    ]\n\n    # ========================================================\n    # Combine with first audit\n    # ========================================================\n\n    final_accepted = list(\n        accepted_existing\n    )\n\n    final_companions = (\n        list(\n            companions_existing\n        )\n        + resolved_companions\n    )\n\n    final_excluded = (\n        list(\n            excluded_existing\n        )\n        + resolved_excluded\n    )\n\n    # ========================================================\n    # Decision accounting\n    # ========================================================\n\n    resolution_counts = Counter(\n        row[\n            "resolution_decision"\n        ]\n        for row in resolved_rows\n    )\n\n    status_counts = Counter(\n        row[\n            "resolution_status"\n        ]\n        for row in resolved_rows\n    )\n\n    original_total = (\n        len(\n            accepted_existing\n        )\n        + len(\n            companions_existing\n        )\n        + len(\n            excluded_existing\n        )\n        + len(\n            review_input\n        )\n    )\n\n    final_total = (\n        len(\n            final_accepted\n        )\n        + len(\n            final_companions\n        )\n        + len(\n            final_excluded\n        )\n        + len(\n            graphical_review\n        )\n        + len(\n            remaining_review\n        )\n    )\n\n    if (\n        original_total\n        != final_total\n    ):\n\n        raise RuntimeError(\n            "Resolution accounting mismatch: "\n            f"{original_total} != {final_total}"\n        )\n\n    # ========================================================\n    # Output\n    # ========================================================\n\n    out = (\n        args.output_directory\n    )\n\n    out.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    accepted_columns = (\n        list(\n            accepted_existing[\n                0\n            ].keys()\n        )\n        if accepted_existing\n        else []\n    )\n\n    companion_columns = list(\n        {\n            key: None\n            for row in final_companions\n            for key in row.keys()\n        }.keys()\n    )\n\n    excluded_columns = list(\n        {\n            key: None\n            for row in final_excluded\n            for key in row.keys()\n        }.keys()\n    )\n\n    resolved_columns = (\n        list(\n            resolved_rows[\n                0\n            ].keys()\n        )\n        if resolved_rows\n        else []\n    )\n\n    write_csv(\n        out\n        / "accepted_timeseries_tables.csv",\n        final_accepted,\n        accepted_columns,\n    )\n\n    write_csv(\n        out\n        / "companion_metadata_tables.csv",\n        final_companions,\n        companion_columns,\n    )\n\n    write_csv(\n        out\n        / "excluded_non_timeseries_tables.csv",\n        final_excluded,\n        excluded_columns,\n    )\n\n    write_csv(\n        out\n        / "graphical_review_tables.csv",\n        graphical_review,\n        resolved_columns,\n    )\n\n    write_csv(\n        out\n        / "remaining_review_tables.csv",\n        remaining_review,\n        resolved_columns,\n    )\n\n    write_csv(\n        out\n        / "review_resolution_all.csv",\n        resolved_rows,\n        resolved_columns,\n    )\n\n    resolution_summary = []\n\n    for (\n        decision,\n        status,\n    ), count in sorted(\n        Counter(\n            (\n                row[\n                    "resolution_decision"\n                ],\n                row[\n                    "resolution_status"\n                ],\n            )\n            for row in resolved_rows\n        ).items()\n    ):\n\n        resolution_summary.append({\n            "resolution_decision":\n                decision,\n\n            "resolution_status":\n                status,\n\n            "table_count":\n                count,\n        })\n\n    write_csv(\n        out\n        / "resolution_summary.csv",\n        resolution_summary,\n        [\n            "resolution_decision",\n            "resolution_status",\n            "table_count",\n        ],\n    )\n\n    # ========================================================\n    # Metadata\n    # ========================================================\n\n    reports_with_accepted = {\n        row[\n            "report_id"\n        ]\n        for row\n        in final_accepted\n    }\n\n    accepted_family_counts = Counter(\n        row.get(\n            "audited_family",\n            ""\n        )\n        for row\n        in final_accepted\n    )\n\n    metadata = {\n\n        "created_at":\n            datetime.now(\n                timezone.utc\n            ).isoformat(),\n\n        "group":\n            "Group 4 - Time-series measurements",\n\n        "stage":\n            "PDF residual review resolution",\n\n        "input_remaining_review_tables":\n            len(\n                review_input\n            ),\n\n        "resolved_companion_tables":\n            len(\n                resolved_companions\n            ),\n\n        "resolved_excluded_tables":\n            len(\n                resolved_excluded\n            ),\n\n        "graphical_review_tables":\n            len(\n                graphical_review\n            ),\n\n        "remaining_review_tables":\n            len(\n                remaining_review\n            ),\n\n        "resolution_decision_counts":\n            dict(\n                resolution_counts\n            ),\n\n        "resolution_status_counts":\n            dict(\n                status_counts\n            ),\n\n        "final_accepted_timeseries_tables":\n            len(\n                final_accepted\n            ),\n\n        "final_companion_metadata_tables":\n            len(\n                final_companions\n            ),\n\n        "final_excluded_non_timeseries_tables":\n            len(\n                final_excluded\n            ),\n\n        "reports_with_accepted_timeseries":\n            len(\n                reports_with_accepted\n            ),\n\n        "accepted_family_counts":\n            dict(\n                accepted_family_counts\n            ),\n\n        "input_accounting_total":\n            original_total,\n\n        "output_accounting_total":\n            final_total,\n\n        "all_tables_accounted_for":\n            (\n                original_total\n                == final_total\n            ),\n\n        "scope":\n            (\n                "Targeted resolution of the residual Group 4 PDF "\n                "review population. Repeated sampled time-series "\n                "accepted in the first PDF audit are unchanged. "\n                "Scalar event/pre-crash/time-series context is routed "\n                "to companion metadata. Single temporal snapshots and "\n                "static documentation are excluded from Group 4 "\n                "sampled time-series. Garbled PDF graph/plot structures "\n                "are preserved explicitly as graphical review evidence "\n                "and are not force-reconstructed from unreliable table "\n                "text. No semantic normalization, unit conversion, "\n                "event identity inference, or CSV/PDF integration is "\n                "performed."\n            ),\n    }\n\n    tmp = (\n        out\n        / "metadata.json.part"\n    )\n\n    tmp.write_text(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        ),\n        encoding="utf-8",\n    )\n\n    tmp.replace(\n        out\n        / "metadata.json"\n    )\n\n    print()\n    print(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        )\n    )\n\n    print()\n    print(\n        f"Outputs: {out}"\n    )\n\n    print()\n    print(\n        "GROUP 4 PDF REVIEW RESOLUTION COMPLETE."\n    )\n\n\n'

_PDF_EXTRACT_SOURCE = '"""\nBuild structured Group 4 PDF time-series datasets.\n\nTargeted corrections in this version\n------------------------------------\n1. Samples-by-rows accepts both "Time" and "Times" axis headers.\n   This fixes the four accepted pre-crash tables headed "Times (sec)".\n\n2. Samples-by-columns supports repeated transposed blocks, e.g.:\n\n       Time (milliseconds) | -70 ... 70\n       Delta-V             | ...\n       Time (milliseconds) |  80 ... 220\n       Delta-V             | ...\n\n   Later Time rows are treated as additional axis blocks, not signals.\n   Signal identities are unified across blocks by their raw labels.\n\n3. Physical PDF tables remain independent. Continuation groups are\n   preserved but are NOT merged.\n\nNo semantic normalization, unit conversion, event-identity inference,\nor CSV/PDF integration is performed.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport hashlib\nimport json\nimport math\nimport re\nfrom collections import Counter, defaultdict\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\ncsv.field_size_limit(100_000_000)\n\nBASE = [\n    "report_id",\n    "case_id",\n    "vehicle_number",\n    "export_basename",\n]\n\n\n# ============================================================\n# I/O\n# ============================================================\n\ndef read_csv(path: Path):\n    with path.open(encoding="utf-8-sig", newline="") as f:\n        return list(csv.DictReader(f))\n\n\ndef write_csv(path: Path, rows: list[dict], columns: list[str]):\n    tmp = path.with_suffix(path.suffix + ".part")\n    with tmp.open("w", encoding="utf-8-sig", newline="") as f:\n        writer = csv.DictWriter(\n            f,\n            fieldnames=columns,\n            extrasaction="ignore",\n        )\n        writer.writeheader()\n        writer.writerows(rows)\n    tmp.replace(path)\n\n\n# ============================================================\n# General helpers\n# ============================================================\n\ndef norm(value):\n    return re.sub(\n        r"\\s+",\n        " ",\n        str(value if value is not None else "").strip(),\n    )\n\n\ndef norm_key(value):\n    return norm(\n        re.sub(\n            r"[^a-z0-9]+",\n            " ",\n            norm(value).casefold(),\n        )\n    )\n\n\ndef identifier(*parts):\n    text = "|".join(norm(part) for part in parts)\n    return hashlib.sha256(\n        text.encode("utf-8")\n    ).hexdigest()[:24]\n\n\ndef load_rows(value):\n    try:\n        rows = json.loads(value)\n        if isinstance(rows, list):\n            return rows\n    except (json.JSONDecodeError, TypeError):\n        pass\n    return []\n\n\ndef json_compact(value):\n    return json.dumps(\n        value,\n        ensure_ascii=False,\n        separators=(",", ":"),\n    )\n\n\ndef populated(row):\n    return [\n        norm(value)\n        for value in row\n        if norm(value)\n    ]\n\n\ndef first_populated(row):\n    for index, value in enumerate(row):\n        value = norm(value)\n        if value:\n            return index, value\n    return None, ""\n\n\ndef as_int_or_blank(value):\n    text = norm(value)\n    if not text:\n        return ""\n    try:\n        return int(float(text))\n    except ValueError:\n        return ""\n\n\n# ============================================================\n# Missing / unavailable values\n# ============================================================\n\nMISSING_VALUES = {\n    "",\n    "n/a",\n    "na",\n    "sna",\n    "not available",\n    "data not available",\n    "not applicable",\n    "unknown",\n    "not recorded",\n    "invalid",\n}\n\n\ndef is_missing_or_na(value):\n    return norm(value).casefold() in MISSING_VALUES\n\n\n# ============================================================\n# Numeric helpers\n# ============================================================\n\ndef strip_axis_annotation(value):\n    text = norm(value)\n\n    text = re.sub(\n        r"\\(\\s*TRG[^)]*\\)\\s*$",\n        "",\n        text,\n        flags=re.I,\n    )\n\n    text = re.sub(\n        r"\\s+count\\s*$",\n        "",\n        text,\n        flags=re.I,\n    )\n\n    text = re.sub(\n        r"\\s*(?:"\n        r"seconds?|"\n        r"secs?|"\n        r"msec|"\n        r"milliseconds?|"\n        r"ms"\n        r")\\s*$",\n        "",\n        text,\n        flags=re.I,\n    )\n\n    return norm(text)\n\n\ndef is_numeric(value):\n    text = strip_axis_annotation(value).replace(",", "")\n    if not text:\n        return False\n\n    return bool(\n        re.fullmatch(\n            r"[-+]?"\n            r"(?:\\d+(?:\\.\\d*)?|\\.\\d+)"\n            r"(?:[eE][-+]?\\d+)?",\n            text,\n        )\n    )\n\n\ndef numeric_value(value):\n    text = strip_axis_annotation(value).replace(",", "")\n\n    if not is_numeric(text):\n        return ""\n\n    try:\n        number = float(text)\n        if math.isfinite(number):\n            return number\n    except ValueError:\n        pass\n\n    return ""\n\n\n# ============================================================\n# Unit helpers\n# ============================================================\n\nUNIT_PATTERNS = [\n    r"km/h",\n    r"mph",\n    r"rpm",\n    r"\\bg\\b",\n    r"m/s(?:\\^?2|²)?",\n    r"ft/s(?:\\^?2|²)?",\n    r"deg(?:ree)?s?",\n    r"deg/sec",\n    r"degrees?/sec",\n    r"rad/s",\n    r"percent",\n    r"%",\n    r"sec(?:onds?)?",\n    r"msec",\n    r"milliseconds?",\n    r"\\bms\\b",\n]\n\n\ndef extract_unit_from_text(value):\n    text = norm(value)\n\n    if not text:\n        return ""\n\n    matches = re.findall(\n        r"\\(([^()]*)\\)",\n        text,\n    )\n\n    for candidate in reversed(matches):\n        candidate = norm(candidate)\n\n        if any(\n            re.search(pattern, candidate, re.I)\n            for pattern in UNIT_PATTERNS\n        ):\n            return candidate\n\n    # Be conservative outside parentheses. Only standalone unit-like\n    # text should be treated as a unit; words such as "Percent Throttle"\n    # are labels, not units.\n    if re.fullmatch(\n        r"\\s*(?:"\n        r"km/h|mph|rpm|g|"\n        r"m/s(?:\\^?2|²)?|"\n        r"ft/s(?:\\^?2|²)?|"\n        r"deg(?:ree)?s?|"\n        r"deg/sec|degrees?/sec|rad/s|"\n        r"percent|%|"\n        r"sec(?:onds?)?|msec|milliseconds?|ms"\n        r")\\s*",\n        text,\n        re.I,\n    ):\n        return text\n\n    return ""\n\n\n# ============================================================\n# Axis helpers\n# ============================================================\n\ndef is_axis_header_text(value):\n    text = norm(value)\n\n    return bool(\n        re.search(\n            r"\\b(?:"\n            r"times?|"\n            r"seconds?\\s+before|"\n            r"seconds?\\s+after|"\n            r"sample\\s+count|"\n            r"parameter"\n            r")\\b",\n            text,\n            re.I,\n        )\n    )\n\n\ndef classify_axis_type(label):\n    text = norm_key(label)\n\n    if "sample count" in text:\n        return "sample_count_relative_to_trigger"\n\n    if (\n        "seconds before" in text\n        or "sec before" in text\n    ):\n        return "relative_time_before_event"\n\n    if (\n        "seconds after" in text\n        or "sec after" in text\n    ):\n        return "relative_time_after_event"\n\n    if "time" in text:\n        return "explicit_time"\n\n    return "ordered_numeric_axis"\n\n\ndef infer_axis_unit(label, values=None):\n    text = norm(label)\n\n    if re.search(\n        r"\\bmsec\\b|\\bms\\b|milliseconds?",\n        text,\n        re.I,\n    ):\n        return "ms"\n\n    if re.search(\n        r"\\bsec\\b|\\bseconds?\\b",\n        text,\n        re.I,\n    ):\n        return "s"\n\n    if re.search(\n        r"\\bsample count\\b",\n        text,\n        re.I,\n    ):\n        return "count"\n\n    if values:\n        sample_text = " ".join(\n            norm(value)\n            for value in values[:10]\n        )\n\n        if re.search(\n            r"\\bsec\\b|\\bseconds?\\b",\n            sample_text,\n            re.I,\n        ):\n            return "s"\n\n        if re.search(\n            r"\\bms\\b|\\bmsec\\b",\n            sample_text,\n            re.I,\n        ):\n            return "ms"\n\n    return ""\n\n\n# ============================================================\n# Signal helper\n# ============================================================\n\ndef make_signal(\n    source,\n    series_id,\n    signal_position,\n    label,\n    unit,\n    source_row_index="",\n    source_column_index="",\n    header_fragments=None,\n    orientation="",\n):\n    signal_id = (\n        "g4pdfsig_"\n        + identifier(\n            series_id,\n            signal_position,\n        )\n    )\n\n    return {\n        **{\n            key: source.get(key, "")\n            for key in BASE\n        },\n\n        "series_id":\n            series_id,\n\n        "signal_id":\n            signal_id,\n\n        "signal_position":\n            signal_position,\n\n        "source_row_index":\n            source_row_index,\n\n        "source_column_index":\n            source_column_index,\n\n        "signal_label_raw":\n            norm(label),\n\n        "signal_unit_raw":\n            norm(unit),\n\n        "header_fragments_json":\n            json_compact(\n                header_fragments or []\n            ),\n\n        "table_orientation":\n            orientation,\n\n        "semantic_normalization_status":\n            "not_normalized",\n    }\n\n\n# ============================================================\n# Samples-by-rows parser\n# ============================================================\n\ndef detect_row_axis_structure(rows):\n    """\n    Detect row-oriented temporal tables.\n\n    Targeted correction:\n        accepts "Time (...)" and "Times (...)".\n    """\n\n    best = None\n\n    for header_index in range(\n        min(len(rows), 10)\n    ):\n        header = rows[header_index]\n\n        for axis_col, header_value in enumerate(header):\n            header_value = norm(header_value)\n\n            if not header_value:\n                continue\n\n            if not is_axis_header_text(\n                header_value\n            ):\n                continue\n\n            # "Parameter" generally belongs to transposed layout,\n            # not row-wise layout.\n            if (\n                norm(header_value).casefold()\n                == "parameter"\n            ):\n                continue\n\n            sample_rows = []\n\n            for row_index in range(\n                header_index + 1,\n                len(rows),\n            ):\n                row = rows[row_index]\n\n                if axis_col >= len(row):\n                    continue\n\n                axis_value = norm(\n                    row[axis_col]\n                )\n\n                if not is_numeric(axis_value):\n                    continue\n\n                if len(populated(row)) < 2:\n                    continue\n\n                sample_rows.append(\n                    row_index\n                )\n\n            if len(sample_rows) < 2:\n                continue\n\n            candidate = {\n                "header_row_index":\n                    header_index,\n\n                "axis_column_index":\n                    axis_col,\n\n                "axis_label":\n                    header_value,\n\n                "sample_row_indexes":\n                    sample_rows,\n\n                "sample_count":\n                    len(sample_rows),\n            }\n\n            if (\n                best is None\n                or candidate["sample_count"]\n                > best["sample_count"]\n            ):\n                best = candidate\n\n    return best\n\n\ndef parse_samples_by_rows(\n    source,\n    rows,\n    series_id,\n):\n    structure = detect_row_axis_structure(\n        rows\n    )\n\n    if structure is None:\n        raise ValueError(\n            "Could not reconstruct samples-by-rows temporal axis."\n        )\n\n    header_row_index = (\n        structure["header_row_index"]\n    )\n\n    axis_col = (\n        structure["axis_column_index"]\n    )\n\n    axis_label = (\n        structure["axis_label"]\n    )\n\n    sample_row_indexes = (\n        structure["sample_row_indexes"]\n    )\n\n    header = rows[\n        header_row_index\n    ]\n\n    measurement_columns = []\n\n    max_width = max(\n        len(rows[row_index])\n        for row_index\n        in sample_row_indexes\n    )\n\n    for column_index in range(\n        max_width\n    ):\n        if column_index == axis_col:\n            continue\n\n        nonblank_count = 0\n\n        for row_index in sample_row_indexes:\n            row = rows[row_index]\n\n            if (\n                column_index < len(row)\n                and norm(\n                    row[column_index]\n                )\n            ):\n                nonblank_count += 1\n\n        if nonblank_count >= 1:\n            measurement_columns.append(\n                column_index\n            )\n\n    if not measurement_columns:\n        raise ValueError(\n            "No measurement columns found."\n        )\n\n    signals = []\n    signal_by_column = {}\n\n    for signal_position, column_index in enumerate(\n        measurement_columns,\n        1,\n    ):\n        raw_header = (\n            norm(header[column_index])\n            if column_index < len(header)\n            else ""\n        )\n\n        fragments = []\n\n        for row_index in range(\n            header_row_index + 1\n        ):\n            row = rows[row_index]\n\n            if column_index < len(row):\n                value = norm(\n                    row[column_index]\n                )\n\n                if value:\n                    fragments.append(\n                        value\n                    )\n\n        if not raw_header:\n            raw_header = (\n                fragments[-1]\n                if fragments\n                else (\n                    f"source_column_"\n                    f"{column_index}"\n                )\n            )\n\n        unit = extract_unit_from_text(\n            raw_header\n        )\n\n        label = raw_header\n\n        only_unit_like = bool(\n            unit\n            and norm_key(raw_header)\n            == norm_key(unit)\n        )\n\n        if (\n            only_unit_like\n            or label.startswith(\n                "source_column_"\n            )\n        ):\n            heading = norm(\n                source.get(\n                    "source_heading_hint",\n                    "",\n                )\n            )\n\n            if heading:\n                label = heading\n\n        signal = make_signal(\n            source=source,\n            series_id=series_id,\n            signal_position=signal_position,\n            label=label,\n            unit=unit,\n            source_row_index=header_row_index,\n            source_column_index=column_index,\n            header_fragments=(\n                fragments\n                if fragments\n                else [raw_header]\n            ),\n            orientation="samples_by_rows",\n        )\n\n        signals.append(signal)\n        signal_by_column[\n            column_index\n        ] = signal\n\n    axis_values_raw = [\n        norm(\n            rows[row_index][axis_col]\n        )\n        for row_index\n        in sample_row_indexes\n    ]\n\n    axis_type = classify_axis_type(\n        axis_label\n    )\n\n    axis_unit = infer_axis_unit(\n        axis_label,\n        axis_values_raw,\n    )\n\n    samples = []\n    values_long = []\n\n    for sample_index, row_index in enumerate(\n        sample_row_indexes\n    ):\n        row = rows[row_index]\n\n        axis_raw = (\n            norm(row[axis_col])\n            if axis_col < len(row)\n            else ""\n        )\n\n        sample_id = (\n            "g4pdfsample_"\n            + identifier(\n                series_id,\n                sample_index,\n            )\n        )\n\n        values_map = {}\n\n        for column_index in measurement_columns:\n            signal = signal_by_column[\n                column_index\n            ]\n\n            raw_value = (\n                norm(row[column_index])\n                if column_index < len(row)\n                else ""\n            )\n\n            values_map[\n                signal["signal_id"]\n            ] = raw_value\n\n            values_long.append({\n                **{\n                    key:\n                        source.get(\n                            key,\n                            ""\n                        )\n                    for key in BASE\n                },\n\n                "series_id":\n                    series_id,\n\n                "sample_id":\n                    sample_id,\n\n                "sample_index":\n                    sample_index,\n\n                "signal_id":\n                    signal["signal_id"],\n\n                "signal_position":\n                    signal[\n                        "signal_position"\n                    ],\n\n                "signal_label_raw":\n                    signal[\n                        "signal_label_raw"\n                    ],\n\n                "signal_unit_raw":\n                    signal[\n                        "signal_unit_raw"\n                    ],\n\n                "axis_type":\n                    axis_type,\n\n                "axis_label_raw":\n                    axis_label,\n\n                "axis_unit_raw":\n                    axis_unit,\n\n                "axis_value_raw":\n                    axis_raw,\n\n                "axis_value_numeric":\n                    numeric_value(\n                        axis_raw\n                    ),\n\n                "value_raw":\n                    raw_value,\n\n                "value_numeric":\n                    (\n                        numeric_value(\n                            raw_value\n                        )\n                        if is_numeric(\n                            raw_value\n                        )\n                        else ""\n                    ),\n\n                "value_is_missing_or_na":\n                    is_missing_or_na(\n                        raw_value\n                    ),\n\n                "source_page_number":\n                    source.get(\n                        "page_number",\n                        "",\n                    ),\n\n                "source_table_index_on_page":\n                    source.get(\n                        "table_index_on_page",\n                        "",\n                    ),\n\n                "source_table_row_index":\n                    row_index,\n\n                "source_table_column_index":\n                    column_index,\n\n                "table_orientation":\n                    "samples_by_rows",\n            })\n\n        samples.append({\n            **{\n                key:\n                    source.get(\n                        key,\n                        ""\n                    )\n                for key in BASE\n            },\n\n            "series_id":\n                series_id,\n\n            "sample_id":\n                sample_id,\n\n            "sample_index":\n                sample_index,\n\n            "axis_type":\n                axis_type,\n\n            "axis_label_raw":\n                axis_label,\n\n            "axis_unit_raw":\n                axis_unit,\n\n            "axis_value_raw":\n                axis_raw,\n\n            "axis_value_numeric":\n                numeric_value(\n                    axis_raw\n                ),\n\n            "secondary_axes_json":\n                "{}",\n\n            "values_json":\n                json_compact(\n                    values_map\n                ),\n\n            "source_page_number":\n                source.get(\n                    "page_number",\n                    "",\n                ),\n\n            "source_table_index_on_page":\n                source.get(\n                    "table_index_on_page",\n                    "",\n                ),\n\n            "source_table_row_index":\n                row_index,\n\n            "table_orientation":\n                "samples_by_rows",\n        })\n\n    return {\n        "signals":\n            signals,\n\n        "samples":\n            samples,\n\n        "values":\n            values_long,\n\n        "axis_type":\n            axis_type,\n\n        "axis_label_raw":\n            axis_label,\n\n        "axis_unit_raw":\n            axis_unit,\n\n        "sample_count":\n            len(samples),\n\n        "signal_count":\n            len(signals),\n\n        "header_row_index":\n            header_row_index,\n\n        "axis_column_index":\n            axis_col,\n\n        "transposed_block_count":\n            "",\n    }\n\n\n# ============================================================\n# Samples-by-columns parser\n# ============================================================\n\ndef find_transposed_blocks(rows):\n    """\n    Find ALL transposed temporal blocks in a physical PDF table.\n\n    Example:\n\n        Time (milliseconds) | -70 ... 70\n        Delta-V             | ...\n        Time (milliseconds) |  80 ... 220\n        Delta-V             | ...\n\n    Returns one block record for each axis row.\n    """\n\n    axis_rows = []\n\n    for row_index in range(\n        min(len(rows), 1000)\n    ):\n        row = rows[row_index]\n\n        axis_label_col, axis_label = (\n            first_populated(row)\n        )\n\n        if axis_label_col is None:\n            continue\n\n        if not is_axis_header_text(\n            axis_label\n        ):\n            continue\n\n        sample_columns = []\n\n        for column_index, value in enumerate(\n            row\n        ):\n            if column_index == axis_label_col:\n                continue\n\n            if is_numeric(value):\n                sample_columns.append(\n                    column_index\n                )\n\n        if len(sample_columns) < 2:\n            continue\n\n        axis_rows.append({\n            "axis_row_index":\n                row_index,\n\n            "axis_label_column":\n                axis_label_col,\n\n            "axis_label":\n                axis_label,\n\n            "sample_columns":\n                sample_columns,\n        })\n\n    if not axis_rows:\n        return []\n\n    blocks = []\n\n    for block_index, axis_info in enumerate(\n        axis_rows\n    ):\n        axis_row_index = (\n            axis_info[\n                "axis_row_index"\n            ]\n        )\n\n        next_axis_row_index = (\n            axis_rows[\n                block_index + 1\n            ][\n                "axis_row_index"\n            ]\n            if block_index + 1\n            < len(axis_rows)\n            else len(rows)\n        )\n\n        sample_columns = (\n            axis_info[\n                "sample_columns"\n            ]\n        )\n\n        signal_rows = []\n\n        for signal_row_index in range(\n            axis_row_index + 1,\n            next_axis_row_index,\n        ):\n            signal_row = rows[\n                signal_row_index\n            ]\n\n            label_col, label = (\n                first_populated(\n                    signal_row\n                )\n            )\n\n            if label_col is None:\n                continue\n\n            # Never treat another axis-like row as a signal.\n            if is_axis_header_text(\n                label\n            ):\n                continue\n\n            value_count = 0\n\n            for column_index in sample_columns:\n                if (\n                    column_index\n                    < len(signal_row)\n                    and norm(\n                        signal_row[\n                            column_index\n                        ]\n                    )\n                ):\n                    value_count += 1\n\n            if value_count >= 2:\n                signal_rows.append({\n                    "row_index":\n                        signal_row_index,\n\n                    "label_column":\n                        label_col,\n\n                    "label":\n                        label,\n                })\n\n        if signal_rows:\n            blocks.append({\n                **axis_info,\n\n                "signal_rows":\n                    signal_rows,\n\n                "sample_count":\n                    len(\n                        sample_columns\n                    ),\n            })\n\n    return blocks\n\n\ndef parse_samples_by_columns(\n    source,\n    rows,\n    series_id,\n):\n    blocks = find_transposed_blocks(\n        rows\n    )\n\n    if not blocks:\n        raise ValueError(\n            "Could not reconstruct samples-by-columns temporal axis."\n        )\n\n    # --------------------------------------------------------\n    # Build one signal registry across all repeated blocks.\n    # The same raw signal label in multiple blocks is one signal.\n    # --------------------------------------------------------\n\n    signal_key_to_info = {}\n\n    for block in blocks:\n        for signal_row in block[\n            "signal_rows"\n        ]:\n            raw_label = norm(\n                signal_row[\n                    "label"\n                ]\n            )\n\n            key = norm_key(\n                raw_label\n            )\n\n            if not key:\n                continue\n\n            if key not in signal_key_to_info:\n                signal_key_to_info[\n                    key\n                ] = {\n                    "raw_label":\n                        raw_label,\n\n                    "source_row_index":\n                        signal_row[\n                            "row_index"\n                        ],\n\n                    "source_column_index":\n                        signal_row[\n                            "label_column"\n                        ],\n                }\n\n    if not signal_key_to_info:\n        raise ValueError(\n            "No signals found in transposed temporal blocks."\n        )\n\n    signals = []\n    signal_by_key = {}\n\n    for signal_position, (\n        key,\n        info,\n    ) in enumerate(\n        signal_key_to_info.items(),\n        1,\n    ):\n        raw_label = info[\n            "raw_label"\n        ]\n\n        unit = extract_unit_from_text(\n            raw_label\n        )\n\n        signal = make_signal(\n            source=source,\n            series_id=series_id,\n            signal_position=signal_position,\n            label=raw_label,\n            unit=unit,\n            source_row_index=(\n                info[\n                    "source_row_index"\n                ]\n            ),\n            source_column_index=(\n                info[\n                    "source_column_index"\n                ]\n            ),\n            header_fragments=[\n                raw_label\n            ],\n            orientation="samples_by_columns",\n        )\n\n        signals.append(\n            signal\n        )\n\n        signal_by_key[\n            key\n        ] = signal\n\n    # --------------------------------------------------------\n    # Choose effective axis metadata from first block.\n    # --------------------------------------------------------\n\n    first_block = blocks[0]\n\n    first_axis_row = rows[\n        first_block[\n            "axis_row_index"\n        ]\n    ]\n\n    first_axis_values = [\n        norm(\n            first_axis_row[\n                column_index\n            ]\n        )\n        for column_index\n        in first_block[\n            "sample_columns"\n        ]\n    ]\n\n    first_axis_label = norm(\n        first_block[\n            "axis_label"\n        ]\n    )\n\n    if (\n        first_axis_label.casefold()\n        == "parameter"\n    ):\n        sample_text = " ".join(\n            first_axis_values\n        )\n\n        if re.search(\n            r"\\bsec\\b|\\bseconds?\\b",\n            sample_text,\n            re.I,\n        ):\n            axis_label_effective = (\n                "Seconds Before Event"\n            )\n        else:\n            axis_label_effective = (\n                first_axis_label\n            )\n    else:\n        axis_label_effective = (\n            first_axis_label\n        )\n\n    axis_type = classify_axis_type(\n        axis_label_effective\n    )\n\n    all_axis_values = []\n\n    for block in blocks:\n        axis_row = rows[\n            block[\n                "axis_row_index"\n            ]\n        ]\n\n        for column_index in block[\n            "sample_columns"\n        ]:\n            if column_index < len(\n                axis_row\n            ):\n                all_axis_values.append(\n                    norm(\n                        axis_row[\n                            column_index\n                        ]\n                    )\n                )\n\n    axis_unit = infer_axis_unit(\n        axis_label_effective,\n        all_axis_values,\n    )\n\n    # --------------------------------------------------------\n    # Build samples sequentially across all blocks.\n    # --------------------------------------------------------\n\n    samples = []\n    values_long = []\n    sample_index = 0\n\n    for block_index, block in enumerate(\n        blocks\n    ):\n        axis_row_index = (\n            block[\n                "axis_row_index"\n            ]\n        )\n\n        axis_row = rows[\n            axis_row_index\n        ]\n\n        # Map signal key -> source row for this block.\n        block_signal_rows = {}\n\n        for signal_row in block[\n            "signal_rows"\n        ]:\n            key = norm_key(\n                signal_row[\n                    "label"\n                ]\n            )\n\n            if key:\n                block_signal_rows[\n                    key\n                ] = signal_row[\n                    "row_index"\n                ]\n\n        for column_index in block[\n            "sample_columns"\n        ]:\n            axis_raw = (\n                norm(\n                    axis_row[\n                        column_index\n                    ]\n                )\n                if column_index\n                < len(axis_row)\n                else ""\n            )\n\n            sample_id = (\n                "g4pdfsample_"\n                + identifier(\n                    series_id,\n                    sample_index,\n                )\n            )\n\n            values_map = {}\n\n            for key, signal in signal_by_key.items():\n                source_row_index = (\n                    block_signal_rows.get(\n                        key\n                    )\n                )\n\n                if source_row_index is None:\n                    raw_value = ""\n                else:\n                    signal_row = rows[\n                        source_row_index\n                    ]\n\n                    raw_value = (\n                        norm(\n                            signal_row[\n                                column_index\n                            ]\n                        )\n                        if column_index\n                        < len(signal_row)\n                        else ""\n                    )\n\n                values_map[\n                    signal[\n                        "signal_id"\n                    ]\n                ] = raw_value\n\n                values_long.append({\n                    **{\n                        base_key:\n                            source.get(\n                                base_key,\n                                ""\n                            )\n                        for base_key in BASE\n                    },\n\n                    "series_id":\n                        series_id,\n\n                    "sample_id":\n                        sample_id,\n\n                    "sample_index":\n                        sample_index,\n\n                    "signal_id":\n                        signal[\n                            "signal_id"\n                        ],\n\n                    "signal_position":\n                        signal[\n                            "signal_position"\n                        ],\n\n                    "signal_label_raw":\n                        signal[\n                            "signal_label_raw"\n                        ],\n\n                    "signal_unit_raw":\n                        signal[\n                            "signal_unit_raw"\n                        ],\n\n                    "axis_type":\n                        axis_type,\n\n                    "axis_label_raw":\n                        axis_label_effective,\n\n                    "axis_unit_raw":\n                        axis_unit,\n\n                    "axis_value_raw":\n                        axis_raw,\n\n                    "axis_value_numeric":\n                        numeric_value(\n                            axis_raw\n                        ),\n\n                    "value_raw":\n                        raw_value,\n\n                    "value_numeric":\n                        (\n                            numeric_value(\n                                raw_value\n                            )\n                            if is_numeric(\n                                raw_value\n                            )\n                            else ""\n                        ),\n\n                    "value_is_missing_or_na":\n                        is_missing_or_na(\n                            raw_value\n                        ),\n\n                    "source_page_number":\n                        source.get(\n                            "page_number",\n                            "",\n                        ),\n\n                    "source_table_index_on_page":\n                        source.get(\n                            "table_index_on_page",\n                            "",\n                        ),\n\n                    "source_table_row_index":\n                        (\n                            source_row_index\n                            if source_row_index\n                            is not None\n                            else ""\n                        ),\n\n                    "source_table_column_index":\n                        column_index,\n\n                    "table_orientation":\n                        "samples_by_columns",\n                })\n\n            samples.append({\n                **{\n                    base_key:\n                        source.get(\n                            base_key,\n                            ""\n                        )\n                    for base_key in BASE\n                },\n\n                "series_id":\n                    series_id,\n\n                "sample_id":\n                    sample_id,\n\n                "sample_index":\n                    sample_index,\n\n                "axis_type":\n                    axis_type,\n\n                "axis_label_raw":\n                    axis_label_effective,\n\n                "axis_unit_raw":\n                    axis_unit,\n\n                "axis_value_raw":\n                    axis_raw,\n\n                "axis_value_numeric":\n                    numeric_value(\n                        axis_raw\n                    ),\n\n                "secondary_axes_json":\n                    json_compact({\n                        "transposed_block_index":\n                            block_index,\n                    }),\n\n                "values_json":\n                    json_compact(\n                        values_map\n                    ),\n\n                "source_page_number":\n                    source.get(\n                        "page_number",\n                        "",\n                    ),\n\n                "source_table_index_on_page":\n                    source.get(\n                        "table_index_on_page",\n                        "",\n                    ),\n\n                "source_table_row_index":\n                    axis_row_index,\n\n                "table_orientation":\n                    "samples_by_columns",\n            })\n\n            sample_index += 1\n\n    return {\n        "signals":\n            signals,\n\n        "samples":\n            samples,\n\n        "values":\n            values_long,\n\n        "axis_type":\n            axis_type,\n\n        "axis_label_raw":\n            axis_label_effective,\n\n        "axis_unit_raw":\n            axis_unit,\n\n        "sample_count":\n            len(samples),\n\n        "signal_count":\n            len(signals),\n\n        "header_row_index":\n            first_block[\n                "axis_row_index"\n            ],\n\n        "axis_column_index":\n            "",\n\n        "transposed_block_count":\n            len(blocks),\n    }\n\n\n# ============================================================\n# Companion metadata\n# ============================================================\n\ndef build_companion_rows(rows):\n    result = []\n\n    for source in rows:\n        companion_id = (\n            "g4pdfmeta_"\n            + identifier(\n                source.get(\n                    "report_id",\n                    "",\n                ),\n                source.get(\n                    "pdf_candidate_id",\n                    "",\n                ),\n                source.get(\n                    "page_number",\n                    "",\n                ),\n                source.get(\n                    "table_index_on_page",\n                    "",\n                ),\n            )\n        )\n\n        result.append({\n            **{\n                key:\n                    source.get(\n                        key,\n                        ""\n                    )\n                for key in BASE\n            },\n\n            "companion_metadata_id":\n                companion_id,\n\n            "pdf_candidate_id":\n                source.get(\n                    "pdf_candidate_id",\n                    "",\n                ),\n\n            "source_path":\n                source.get(\n                    "source_path",\n                    "",\n                ),\n\n            "page_number":\n                source.get(\n                    "page_number",\n                    "",\n                ),\n\n            "table_index_on_page":\n                source.get(\n                    "table_index_on_page",\n                    "",\n                ),\n\n            "source_heading_hint":\n                source.get(\n                    "source_heading_hint",\n                    "",\n                ),\n\n            "audited_family":\n                source.get(\n                    "audited_family",\n                    "",\n                ),\n\n            "audited_component":\n                source.get(\n                    "audited_component",\n                    "",\n                ),\n\n            "source_rows_json":\n                source.get(\n                    "source_rows_json",\n                    "",\n                ),\n\n            "processing_status":\n                "preserved_pdf_companion_metadata",\n\n            "linkage_status":\n                "not_yet_linked_to_logical_series",\n        })\n\n    return result\n\n\n# ============================================================\n# Main\n# ============================================================\n\ndef main():\n    parser = argparse.ArgumentParser(\n        description=__doc__\n    )\n\n    parser.add_argument(\n        "--resolved-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group4_pdf_resolved_v1"\n        ),\n    )\n\n    parser.add_argument(\n        "--output-directory",\n        type=Path,\n        default=Path(\n            "data/processed/edr/"\n            "group4_pdf_structured_v1"\n        ),\n    )\n\n    args = parser.parse_args()\n\n    resolved = (\n        args.resolved_directory\n    )\n\n    accepted_path = (\n        resolved\n        / "accepted_timeseries_tables.csv"\n    )\n\n    companion_path = (\n        resolved\n        / "companion_metadata_tables.csv"\n    )\n\n    graphical_path = (\n        resolved\n        / "graphical_review_tables.csv"\n    )\n\n    for path in (\n        accepted_path,\n        companion_path,\n        graphical_path,\n    ):\n        if not path.exists():\n            raise FileNotFoundError(\n                path\n            )\n\n    accepted = read_csv(\n        accepted_path\n    )\n\n    companion_input = read_csv(\n        companion_path\n    )\n\n    graphical_review = read_csv(\n        graphical_path\n    )\n\n    registry = []\n    signal_registry = []\n    samples = []\n    values_long = []\n    audit_rows = []\n    failures = []\n\n    orientation_counts = Counter()\n    transposed_block_counts = Counter()\n\n    # ========================================================\n    # Extract accepted physical tables\n    # ========================================================\n\n    for index, source in enumerate(\n        accepted,\n        1,\n    ):\n        candidate_id = norm(\n            source.get(\n                "pdf_candidate_id",\n                ""\n            )\n        )\n\n        orientation = norm(\n            source.get(\n                "audited_orientation",\n                ""\n            )\n        )\n\n        source_rows = load_rows(\n            source.get(\n                "source_rows_json",\n                ""\n            )\n        )\n\n        series_id = (\n            "g4pdf_"\n            + identifier(\n                source.get(\n                    "report_id",\n                    "",\n                ),\n                candidate_id,\n                source.get(\n                    "page_number",\n                    "",\n                ),\n                source.get(\n                    "table_index_on_page",\n                    "",\n                ),\n            )\n        )\n\n        if not source_rows:\n            failures.append({\n                **{\n                    key:\n                        source.get(\n                            key,\n                            ""\n                        )\n                    for key in BASE\n                },\n\n                "pdf_candidate_id":\n                    candidate_id,\n\n                "series_id":\n                    series_id,\n\n                "source_heading_hint":\n                    source.get(\n                        "source_heading_hint",\n                        "",\n                    ),\n\n                "audited_orientation":\n                    orientation,\n\n                "error_type":\n                    "empty_source_rows",\n\n                "error":\n                    "source_rows_json is empty.",\n            })\n\n            continue\n\n        try:\n            if (\n                orientation\n                == "samples_by_rows"\n            ):\n                parsed = (\n                    parse_samples_by_rows(\n                        source,\n                        source_rows,\n                        series_id,\n                    )\n                )\n\n            elif (\n                orientation\n                == "samples_by_columns"\n            ):\n                parsed = (\n                    parse_samples_by_columns(\n                        source,\n                        source_rows,\n                        series_id,\n                    )\n                )\n\n            else:\n                raise ValueError(\n                    "Unsupported audited orientation: "\n                    f"{orientation}"\n                )\n\n        except Exception as exc:\n            failures.append({\n                **{\n                    key:\n                        source.get(\n                            key,\n                            ""\n                        )\n                    for key in BASE\n                },\n\n                "pdf_candidate_id":\n                    candidate_id,\n\n                "series_id":\n                    series_id,\n\n                "source_heading_hint":\n                    source.get(\n                        "source_heading_hint",\n                        "",\n                    ),\n\n                "audited_orientation":\n                    orientation,\n\n                "error_type":\n                    type(exc).__name__,\n\n                "error":\n                    str(exc),\n            })\n\n            continue\n\n        orientation_counts[\n            orientation\n        ] += 1\n\n        block_count = (\n            parsed.get(\n                "transposed_block_count",\n                "",\n            )\n        )\n\n        if block_count != "":\n            transposed_block_counts[\n                int(block_count)\n            ] += 1\n\n        signal_registry.extend(\n            parsed["signals"]\n        )\n\n        samples.extend(\n            parsed["samples"]\n        )\n\n        values_long.extend(\n            parsed["values"]\n        )\n\n        registry.append({\n            **{\n                key:\n                    source.get(\n                        key,\n                        ""\n                    )\n                for key in BASE\n            },\n\n            "series_id":\n                series_id,\n\n            "pdf_candidate_id":\n                candidate_id,\n\n            "source_path":\n                source.get(\n                    "source_path",\n                    "",\n                ),\n\n            "page_number":\n                source.get(\n                    "page_number",\n                    "",\n                ),\n\n            "table_index_on_page":\n                source.get(\n                    "table_index_on_page",\n                    "",\n                ),\n\n            "source_heading_hint":\n                source.get(\n                    "source_heading_hint",\n                    "",\n                ),\n\n            "family":\n                source.get(\n                    "audited_family",\n                    "",\n                ),\n\n            "component":\n                source.get(\n                    "audited_component",\n                    "",\n                ),\n\n            "table_orientation":\n                orientation,\n\n            "axis_type":\n                parsed["axis_type"],\n\n            "axis_label_raw":\n                parsed[\n                    "axis_label_raw"\n                ],\n\n            "axis_unit_raw":\n                parsed[\n                    "axis_unit_raw"\n                ],\n\n            "header_row_index":\n                parsed[\n                    "header_row_index"\n                ],\n\n            "axis_column_index":\n                parsed[\n                    "axis_column_index"\n                ],\n\n            "sample_count":\n                parsed[\n                    "sample_count"\n                ],\n\n            "signal_count":\n                parsed[\n                    "signal_count"\n                ],\n\n            "transposed_block_count":\n                block_count,\n\n            "table_part_index":\n                as_int_or_blank(\n                    source.get(\n                        "table_part_index",\n                        "",\n                    )\n                ),\n\n            "table_part_total":\n                as_int_or_blank(\n                    source.get(\n                        "table_part_total",\n                        "",\n                    )\n                ),\n\n            "continuation_candidate_key":\n                source.get(\n                    "continuation_candidate_key",\n                    "",\n                ),\n\n            "continuation_merge_status":\n                (\n                    "candidate_not_merged"\n                    if norm(\n                        source.get(\n                            "continuation_candidate_key",\n                            "",\n                        )\n                    )\n                    else "not_applicable"\n                ),\n\n            "group2_handoff_page_support":\n                source.get(\n                    "group2_handoff_page_support",\n                    "",\n                ),\n\n            "processing_status":\n                "structured_extracted",\n\n            "semantic_normalization_status":\n                "not_normalized",\n\n            "unit_conversion_status":\n                "not_converted",\n        })\n\n        audit_rows.append({\n            **{\n                key:\n                    source.get(\n                        key,\n                        ""\n                    )\n                for key in BASE\n            },\n\n            "series_id":\n                series_id,\n\n            "pdf_candidate_id":\n                candidate_id,\n\n            "page_number":\n                source.get(\n                    "page_number",\n                    "",\n                ),\n\n            "table_index_on_page":\n                source.get(\n                    "table_index_on_page",\n                    "",\n                ),\n\n            "source_heading_hint":\n                source.get(\n                    "source_heading_hint",\n                    "",\n                ),\n\n            "family":\n                source.get(\n                    "audited_family",\n                    "",\n                ),\n\n            "component":\n                source.get(\n                    "audited_component",\n                    "",\n                ),\n\n            "table_orientation":\n                orientation,\n\n            "sample_count":\n                parsed[\n                    "sample_count"\n                ],\n\n            "signal_count":\n                parsed[\n                    "signal_count"\n                ],\n\n            "long_value_count":\n                len(\n                    parsed[\n                        "values"\n                    ]\n                ),\n\n            "transposed_block_count":\n                block_count,\n\n            "table_part_index":\n                source.get(\n                    "table_part_index",\n                    "",\n                ),\n\n            "table_part_total":\n                source.get(\n                    "table_part_total",\n                    "",\n                ),\n\n            "continuation_candidate_key":\n                source.get(\n                    "continuation_candidate_key",\n                    "",\n                ),\n\n            "status":\n                "success",\n\n            "issue":\n                "",\n        })\n\n        if (\n            index % 100 == 0\n            or index\n            == len(accepted)\n        ):\n            print(\n                "Structured Group 4 PDF "\n                f"{index}/{len(accepted)} tables...",\n                flush=True,\n            )\n\n    companion_rows = (\n        build_companion_rows(\n            companion_input\n        )\n    )\n\n    # ========================================================\n    # Validation\n    # ========================================================\n\n    validation = []\n\n    def check(\n        name,\n        condition,\n        observed,\n        expected,\n        severity="hard",\n    ):\n        validation.append({\n            "check":\n                name,\n\n            "status":\n                (\n                    "PASS"\n                    if condition\n                    else "FAIL"\n                ),\n\n            "severity":\n                severity,\n\n            "observed":\n                str(observed),\n\n            "expected":\n                str(expected),\n        })\n\n    check(\n        "accepted_tables_accounted_for",\n        (\n            len(registry)\n            + len(failures)\n            == len(accepted)\n        ),\n        (\n            len(registry)\n            + len(failures)\n        ),\n        len(accepted),\n    )\n\n    check(\n        "input_accepted_table_count",\n        len(accepted) == 861,\n        len(accepted),\n        861,\n        severity="warning",\n    )\n\n    check(\n        "all_accepted_tables_structured",\n        len(failures) == 0,\n        len(failures),\n        0,\n    )\n\n    series_ids = [\n        row["series_id"]\n        for row in registry\n    ]\n\n    signal_ids = [\n        row["signal_id"]\n        for row in signal_registry\n    ]\n\n    sample_ids = [\n        row["sample_id"]\n        for row in samples\n    ]\n\n    check(\n        "series_ids_unique",\n        len(series_ids)\n        == len(set(series_ids)),\n        len(set(series_ids)),\n        len(series_ids),\n    )\n\n    check(\n        "signal_ids_unique",\n        len(signal_ids)\n        == len(set(signal_ids)),\n        len(set(signal_ids)),\n        len(signal_ids),\n    )\n\n    check(\n        "sample_ids_unique",\n        len(sample_ids)\n        == len(set(sample_ids)),\n        len(set(sample_ids)),\n        len(sample_ids),\n    )\n\n    known_series = set(\n        series_ids\n    )\n\n    known_signals = set(\n        signal_ids\n    )\n\n    known_samples = set(\n        sample_ids\n    )\n\n    orphan_signal_series = sum(\n        1\n        for row in signal_registry\n        if row["series_id"]\n        not in known_series\n    )\n\n    orphan_sample_series = sum(\n        1\n        for row in samples\n        if row["series_id"]\n        not in known_series\n    )\n\n    orphan_value_series = sum(\n        1\n        for row in values_long\n        if row["series_id"]\n        not in known_series\n    )\n\n    orphan_value_signal = sum(\n        1\n        for row in values_long\n        if row["signal_id"]\n        not in known_signals\n    )\n\n    orphan_value_sample = sum(\n        1\n        for row in values_long\n        if row["sample_id"]\n        not in known_samples\n    )\n\n    check(\n        "orphan_signal_series_refs",\n        orphan_signal_series == 0,\n        orphan_signal_series,\n        0,\n    )\n\n    check(\n        "orphan_sample_series_refs",\n        orphan_sample_series == 0,\n        orphan_sample_series,\n        0,\n    )\n\n    check(\n        "orphan_value_series_refs",\n        orphan_value_series == 0,\n        orphan_value_series,\n        0,\n    )\n\n    check(\n        "orphan_value_signal_refs",\n        orphan_value_signal == 0,\n        orphan_value_signal,\n        0,\n    )\n\n    check(\n        "orphan_value_sample_refs",\n        orphan_value_sample == 0,\n        orphan_value_sample,\n        0,\n    )\n\n    # --------------------------------------------------------\n    # "Time (...)" must never survive as a measurement signal.\n    # --------------------------------------------------------\n\n    axis_like_signal_rows = [\n        row\n        for row in signal_registry\n        if re.fullmatch(\n            r"times?\\s*\\([^)]*\\)",\n            norm(\n                row.get(\n                    "signal_label_raw",\n                    "",\n                )\n            ),\n            re.I,\n        )\n    ]\n\n    check(\n        "axis_like_signal_labels",\n        len(\n            axis_like_signal_rows\n        )\n        == 0,\n        len(\n            axis_like_signal_rows\n        ),\n        0,\n    )\n\n    # --------------------------------------------------------\n    # Dense sample x signal consistency\n    # --------------------------------------------------------\n\n    signals_by_series = defaultdict(\n        int\n    )\n\n    samples_by_series = defaultdict(\n        int\n    )\n\n    values_by_series = defaultdict(\n        int\n    )\n\n    for row in signal_registry:\n        signals_by_series[\n            row["series_id"]\n        ] += 1\n\n    for row in samples:\n        samples_by_series[\n            row["series_id"]\n        ] += 1\n\n    for row in values_long:\n        values_by_series[\n            row["series_id"]\n        ] += 1\n\n    count_mismatch_series = []\n\n    for row in registry:\n        series_id = row["series_id"]\n\n        declared_samples = int(\n            row["sample_count"]\n        )\n\n        declared_signals = int(\n            row["signal_count"]\n        )\n\n        actual_samples = (\n            samples_by_series[\n                series_id\n            ]\n        )\n\n        actual_signals = (\n            signals_by_series[\n                series_id\n            ]\n        )\n\n        actual_values = (\n            values_by_series[\n                series_id\n            ]\n        )\n\n        expected_values = (\n            actual_samples\n            * actual_signals\n        )\n\n        if (\n            declared_samples\n            != actual_samples\n            or declared_signals\n            != actual_signals\n            or actual_values\n            != expected_values\n        ):\n            count_mismatch_series.append(\n                series_id\n            )\n\n    check(\n        "series_count_consistency",\n        len(\n            count_mismatch_series\n        )\n        == 0,\n        len(\n            count_mismatch_series\n        ),\n        0,\n    )\n\n    # ========================================================\n    # Summaries\n    # ========================================================\n\n    family_counts = Counter(\n        row["family"]\n        for row in registry\n    )\n\n    component_counts = Counter(\n        row["component"]\n        for row in registry\n    )\n\n    orientation_counts = Counter(\n        row[\n            "table_orientation"\n        ]\n        for row in registry\n    )\n\n    axis_type_counts = Counter(\n        row["axis_type"]\n        for row in registry\n    )\n\n    signal_label_counts = Counter(\n        row[\n            "signal_label_raw"\n        ]\n        for row in signal_registry\n    )\n\n    signal_unit_counts = Counter(\n        row[\n            "signal_unit_raw"\n        ]\n        for row in signal_registry\n        if row[\n            "signal_unit_raw"\n        ]\n    )\n\n    reports_with_series = {\n        row["report_id"]\n        for row in registry\n    }\n\n    continuation_series = [\n        row\n        for row in registry\n        if norm(\n            row.get(\n                "continuation_candidate_key",\n                "",\n            )\n        )\n    ]\n\n    continuation_groups = {\n        row[\n            "continuation_candidate_key"\n        ]\n        for row in continuation_series\n    }\n\n    repeated_transposed_series_count = sum(\n        1\n        for row in registry\n        if (\n            row.get(\n                "transposed_block_count",\n                ""\n            )\n            not in (\n                "",\n                1,\n                "1",\n            )\n        )\n    )\n\n    values_grouped = defaultdict(\n        list\n    )\n\n    for row in values_long:\n        values_grouped[\n            row["series_id"]\n        ].append(\n            row\n        )\n\n    all_unavailable_series_count = 0\n\n    for row in registry:\n        series_values = (\n            values_grouped[\n                row["series_id"]\n            ]\n        )\n\n        if (\n            series_values\n            and all(\n                is_missing_or_na(\n                    value_row[\n                        "value_raw"\n                    ]\n                )\n                for value_row\n                in series_values\n            )\n        ):\n            all_unavailable_series_count += 1\n\n    # ========================================================\n    # Write output\n    # ========================================================\n\n    out = args.output_directory\n    out.mkdir(\n        parents=True,\n        exist_ok=True,\n    )\n\n    write_csv(\n        out\n        / "timeseries_registry.csv",\n        registry,\n        [\n            *BASE,\n            "series_id",\n            "pdf_candidate_id",\n            "source_path",\n            "page_number",\n            "table_index_on_page",\n            "source_heading_hint",\n            "family",\n            "component",\n            "table_orientation",\n            "axis_type",\n            "axis_label_raw",\n            "axis_unit_raw",\n            "header_row_index",\n            "axis_column_index",\n            "sample_count",\n            "signal_count",\n            "transposed_block_count",\n            "table_part_index",\n            "table_part_total",\n            "continuation_candidate_key",\n            "continuation_merge_status",\n            "group2_handoff_page_support",\n            "processing_status",\n            "semantic_normalization_status",\n            "unit_conversion_status",\n        ],\n    )\n\n    write_csv(\n        out\n        / "timeseries_signal_registry.csv",\n        signal_registry,\n        [\n            *BASE,\n            "series_id",\n            "signal_id",\n            "signal_position",\n            "source_row_index",\n            "source_column_index",\n            "signal_label_raw",\n            "signal_unit_raw",\n            "header_fragments_json",\n            "table_orientation",\n            "semantic_normalization_status",\n        ],\n    )\n\n    write_csv(\n        out\n        / "timeseries_samples_wide.csv",\n        samples,\n        [\n            *BASE,\n            "series_id",\n            "sample_id",\n            "sample_index",\n            "axis_type",\n            "axis_label_raw",\n            "axis_unit_raw",\n            "axis_value_raw",\n            "axis_value_numeric",\n            "secondary_axes_json",\n            "values_json",\n            "source_page_number",\n            "source_table_index_on_page",\n            "source_table_row_index",\n            "table_orientation",\n        ],\n    )\n\n    write_csv(\n        out\n        / "timeseries_values_long.csv",\n        values_long,\n        [\n            *BASE,\n            "series_id",\n            "sample_id",\n            "sample_index",\n            "signal_id",\n            "signal_position",\n            "signal_label_raw",\n            "signal_unit_raw",\n            "axis_type",\n            "axis_label_raw",\n            "axis_unit_raw",\n            "axis_value_raw",\n            "axis_value_numeric",\n            "value_raw",\n            "value_numeric",\n            "value_is_missing_or_na",\n            "source_page_number",\n            "source_table_index_on_page",\n            "source_table_row_index",\n            "source_table_column_index",\n            "table_orientation",\n        ],\n    )\n\n    write_csv(\n        out\n        / "timeseries_companion_metadata.csv",\n        companion_rows,\n        [\n            *BASE,\n            "companion_metadata_id",\n            "pdf_candidate_id",\n            "source_path",\n            "page_number",\n            "table_index_on_page",\n            "source_heading_hint",\n            "audited_family",\n            "audited_component",\n            "source_rows_json",\n            "processing_status",\n            "linkage_status",\n        ],\n    )\n\n    graphical_columns = (\n        list(\n            graphical_review[\n                0\n            ].keys()\n        )\n        if graphical_review\n        else []\n    )\n\n    write_csv(\n        out\n        / "graphical_review_tables.csv",\n        graphical_review,\n        graphical_columns,\n    )\n\n    write_csv(\n        out\n        / "timeseries_audit.csv",\n        audit_rows,\n        [\n            *BASE,\n            "series_id",\n            "pdf_candidate_id",\n            "page_number",\n            "table_index_on_page",\n            "source_heading_hint",\n            "family",\n            "component",\n            "table_orientation",\n            "sample_count",\n            "signal_count",\n            "long_value_count",\n            "transposed_block_count",\n            "table_part_index",\n            "table_part_total",\n            "continuation_candidate_key",\n            "status",\n            "issue",\n        ],\n    )\n\n    write_csv(\n        out\n        / "extraction_failures.csv",\n        failures,\n        [\n            *BASE,\n            "pdf_candidate_id",\n            "series_id",\n            "source_heading_hint",\n            "audited_orientation",\n            "error_type",\n            "error",\n        ],\n    )\n\n    write_csv(\n        out\n        / "validation_report.csv",\n        validation,\n        [\n            "check",\n            "status",\n            "severity",\n            "observed",\n            "expected",\n        ],\n    )\n\n    # ========================================================\n    # Metadata\n    # ========================================================\n\n    hard_failures = [\n        row\n        for row in validation\n        if (\n            row["status"]\n            == "FAIL"\n            and row["severity"]\n            == "hard"\n        )\n    ]\n\n    warning_failures = [\n        row\n        for row in validation\n        if (\n            row["status"]\n            == "FAIL"\n            and row["severity"]\n            == "warning"\n        )\n    ]\n\n    metadata = {\n        "created_at":\n            datetime.now(\n                timezone.utc\n            ).isoformat(),\n\n        "group":\n            "Group 4 - Time-series measurements",\n\n        "stage":\n            "PDF structural extraction",\n\n        "input_accepted_tables":\n            len(accepted),\n\n        "structured_series_count":\n            len(registry),\n\n        "failed_table_count":\n            len(failures),\n\n        "reports_with_structured_timeseries":\n            len(\n                reports_with_series\n            ),\n\n        "signal_registry_rows":\n            len(signal_registry),\n\n        "sample_rows":\n            len(samples),\n\n        "long_value_rows":\n            len(values_long),\n\n        "companion_metadata_rows":\n            len(companion_rows),\n\n        "graphical_review_table_count":\n            len(graphical_review),\n\n        "family_counts":\n            dict(family_counts),\n\n        "component_counts":\n            dict(component_counts),\n\n        "orientation_counts":\n            dict(orientation_counts),\n\n        "axis_type_counts":\n            dict(axis_type_counts),\n\n        "unique_raw_signal_labels":\n            len(\n                signal_label_counts\n            ),\n\n        "top_raw_signal_labels":\n            signal_label_counts.most_common(\n                40\n            ),\n\n        "raw_unit_counts":\n            dict(\n                signal_unit_counts\n            ),\n\n        "continuation_candidate_series_count":\n            len(\n                continuation_series\n            ),\n\n        "continuation_candidate_group_count":\n            len(\n                continuation_groups\n            ),\n\n        "repeated_transposed_series_count":\n            repeated_transposed_series_count,\n\n        "transposed_block_count_distribution":\n            {\n                str(key):\n                    value\n                for key, value\n                in sorted(\n                    transposed_block_counts.items()\n                )\n            },\n\n        "axis_like_signal_label_count":\n            len(\n                axis_like_signal_rows\n            ),\n\n        "all_values_unavailable_series_count":\n            all_unavailable_series_count,\n\n        "validation_checks":\n            len(validation),\n\n        "validation_failures":\n            sum(\n                1\n                for row in validation\n                if row["status"]\n                == "FAIL"\n            ),\n\n        "hard_validation_failures":\n            len(hard_failures),\n\n        "warning_validation_failures":\n            len(\n                warning_failures\n            ),\n\n        "scope":\n            (\n                "Structural extraction of accepted Group 4 PDF-only "\n                "time-series tables. Each physical PDF table remains "\n                "independent. Repeated transposed Time/measurement "\n                "blocks inside one physical PDF table are concatenated "\n                "structurally into one series, preventing later Time "\n                "rows from being misclassified as signals. Row-oriented "\n                "tables accept both Time and Times axis headings. "\n                "Multi-part continuation candidates are preserved but "\n                "not merged. Raw values, labels, units, axes, missing "\n                "source values, and PDF provenance are retained. No "\n                "semantic normalization, unit conversion, event identity "\n                "inference, continuation merging, or CSV/PDF integration "\n                "is performed."\n            ),\n    }\n\n    tmp = (\n        out\n        / "metadata.json.part"\n    )\n\n    tmp.write_text(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        ),\n        encoding="utf-8",\n    )\n\n    tmp.replace(\n        out\n        / "metadata.json"\n    )\n\n    print()\n    print(\n        json.dumps(\n            metadata,\n            indent=2,\n            ensure_ascii=False,\n        )\n    )\n\n    print()\n    print(\n        f"Outputs: {out}"\n    )\n\n    if hard_failures:\n        print()\n        print(\n            "GROUP 4 PDF STRUCTURAL EXTRACTION "\n            "HAS HARD VALIDATION FAILURES."\n        )\n\n        for row in hard_failures:\n            print(\n                f"- {row[\'check\']}: "\n                f"observed={row[\'observed\']} "\n                f"expected={row[\'expected\']}"\n            )\n\n        raise SystemExit(1)\n\n    print()\n    print(\n        "GROUP 4 PDF STRUCTURAL EXTRACTION COMPLETE."\n    )\n\n\n'

_CSV_DISCOVERY = _make_ns(
    "csv_discovery",
    _CSV_DISCOVERY_SOURCE,
    {"load_rows": _load_csv_rows},
)
_CSV_AUDIT = _make_ns("csv_audit", _CSV_AUDIT_SOURCE)
_CSV_EXTRACT = _make_ns("csv_extract", _CSV_EXTRACT_SOURCE)
_PDF_DISCOVERY = _make_ns("pdf_discovery", _PDF_DISCOVERY_SOURCE)
_PDF_AUDIT = _make_ns("pdf_audit", _PDF_AUDIT_SOURCE)
_PDF_RESOLVE = _make_ns("pdf_resolve", _PDF_RESOLVE_SOURCE)
_PDF_EXTRACT = _make_ns("pdf_extract", _PDF_EXTRACT_SOURCE)

def _identity(identity: dict[str, Any]) -> dict[str, str]:
    return {
        "report_id": str(identity.get("report_id", "") or ""),
        "case_id": str(identity.get("case_id", "") or ""),
        "vehicle_number": str(identity.get("vehicle_number", "") or ""),
        "export_basename": str(identity.get("export_basename", "") or ""),
    }


def select_group4_source(csv_path=None, pdf_path=None):
    csv_path = Path(csv_path) if csv_path else None
    pdf_path = Path(pdf_path) if pdf_path else None

    if csv_path and csv_path.is_file():
        return "csv", csv_path
    if pdf_path and pdf_path.is_file():
        return "pdf", pdf_path
    raise FileNotFoundError("No usable CSV or PDF source was found.")


def _csv_discover_and_audit(path: Path, identity: dict[str, Any]):
    rows, _, _, _, _, warnings = _load_csv_rows(path)
    sections = _CSV_DISCOVERY["segment_sections"](rows)

    accepted = []
    companions = []
    excluded = []
    unresolved = []

    base = _identity(identity)

    for section in sections:
        heading = section["heading"]
        content = section["rows"]
        analysis = _CSV_DISCOVERY["analyze_section"](heading, content)

        if not (analysis["candidate"] or analysis["review"]):
            continue

        candidate_id = (
            "g4csv_"
            + _CSV_DISCOVERY["identifier"](
                base["report_id"],
                section["start"],
                heading,
            )
        )

        source = {
            **base,
            "timeseries_candidate_id": candidate_id,
            "source_path": str(path),
            "source_heading": heading,
            "source_record_start": section["start"] + 1,
            "source_record_end": section["end"],
            "candidate_family": analysis["family"],
            "time_axis_type_candidate": analysis["time_axis_type"],
            "discovery_score": analysis["score"],
            "explicit_time_axis": analysis["explicit_time"],
            "buffer_axis": analysis["buffer_axis"],
            "time_header_match_count": analysis["time_header_match_count"],
            "signal_header_match_count": analysis["signal_header_match_count"],
            "numeric_leading_row_count": analysis["numeric_leading_row_count"],
            "modal_populated_width": analysis["modal_populated_width"],
            "modal_width_row_count": analysis["modal_width_row_count"],
            "discovery_reasons": "|".join(analysis["reasons"]),
            "csv_warning_count": len(warnings),
            "source_rows_json": json.dumps(content, ensure_ascii=False),
        }

        audited = _CSV_AUDIT["audit_row"](
            source,
            "discovery_candidate" if analysis["candidate"] else "discovery_review",
        )

        decision = audited.get("audit_decision", "")
        if decision == "accept":
            accepted.append(audited)
        elif decision == "preserve_as_companion_metadata":
            companions.append(audited)
        elif decision == "exclude_from_group4":
            excluded.append(audited)
        else:
            unresolved.append(audited)

    return accepted, companions, excluded, unresolved


def _csv_structured(path: Path, identity: dict[str, Any]):
    accepted, companions, excluded, unresolved = _csv_discover_and_audit(
        path, identity
    )

    registry = []
    signals = []
    samples = []
    values = []
    issues = []

    for source in accepted:
        candidate_id = source.get("timeseries_candidate_id", "")
        series_id = (
            "g4csv_"
            + _CSV_EXTRACT["identifier"](
                source.get("report_id", ""),
                candidate_id,
                source.get("source_heading", ""),
            )
        )

        audited_orientation = _CSV_EXTRACT["norm"](
            source.get("table_orientation", "")
        )

        source_rows_original = _CSV_EXTRACT["load_rows"](
            source.get("source_rows_json", "")
        )
        source_rows = _CSV_EXTRACT["trim_non_timeseries_tail"](
            source_rows_original
        )

        try:
            if audited_orientation == "buffer_order_table":
                parser_orientation = "buffer_order_table"
                parsed = _CSV_EXTRACT["parse_buffer_order_table"](
                    source, source_rows, series_id
                )
            elif _CSV_EXTRACT["has_transposed_time_axis"](source_rows):
                parser_orientation = "samples_by_columns"
                parsed = _CSV_EXTRACT["parse_samples_by_columns"](
                    source, source_rows, series_id
                )
            elif audited_orientation == "samples_by_rows":
                parser_orientation = "samples_by_rows"
                parsed = _CSV_EXTRACT["parse_samples_by_rows"](
                    source, source_rows, series_id
                )
            elif audited_orientation == "samples_by_columns":
                parser_orientation = "samples_by_columns"
                parsed = _CSV_EXTRACT["parse_samples_by_columns"](
                    source, source_rows, series_id
                )
            else:
                raise ValueError(
                    f"Unsupported table orientation: {audited_orientation}"
                )
        except Exception as exc:
            issues.append(
                f"{source.get('report_id','')} | "
                f"{source.get('source_heading','')} | "
                f"{type(exc).__name__}: {exc}"
            )
            continue

        signals.extend(parsed["signals"])
        samples.extend(parsed["samples"])
        values.extend(parsed["values"])

        registry.append({
            **{k: source.get(k, "") for k in (
                "report_id", "case_id", "vehicle_number", "export_basename"
            )},
            "series_id": series_id,
            "timeseries_candidate_id": candidate_id,
            "source_format": "csv",
            "source_heading": source.get("source_heading", ""),
            "source_path": source.get("source_path", ""),
            "source_record_start": source.get("source_record_start", ""),
            "source_record_end": source.get("source_record_end", ""),
            "family": source.get("audited_family", ""),
            "component": source.get("audited_component", ""),
            "audited_orientation": audited_orientation,
            "table_orientation": parser_orientation,
            "orientation_overridden": parser_orientation != audited_orientation,
            "pid_tail_trimmed": len(source_rows) < len(source_rows_original),
            "axis_type": parsed["axis_type"],
            "axis_label_raw": parsed["axis_label_raw"],
            "axis_unit_raw": parsed["axis_unit_raw"],
            "axis_column_index": parsed["axis_column_index"],
            "secondary_axis_columns_json":
                _CSV_EXTRACT["json_compact"](parsed["secondary_axis_columns"]),
            "header_row_count": parsed["header_row_count"],
            "sample_count": parsed["sample_count"],
            "signal_count": parsed["signal_count"],
            "processing_status": "structured_extracted",
            "semantic_normalization_status": "not_normalized",
            "unit_conversion_status": "not_converted",
        })

    companion_rows = _CSV_EXTRACT["build_companion_rows"](companions)

    return Group4ExtractionResult(
        source_format="csv",
        source_path=str(path),
        series=registry,
        signals=signals,
        samples=samples,
        values=values,
        companion_metadata=companion_rows,
        excluded=excluded,
        unresolved=unresolved,
        issues=issues,
    )


def _pdf_discover(path: Path, identity: dict[str, Any]):
    import pdfplumber

    base = _identity(identity)
    candidates = []
    reviews = []
    errors = []

    with pdfplumber.open(path) as pdf:
        for page_number, page in enumerate(pdf.pages, 1):
            try:
                page_text = page.extract_text() or ""
            except Exception:
                page_text = ""

            try:
                tables = page.extract_tables() or []
            except Exception as exc:
                errors.append(
                    f"page {page_number}: {type(exc).__name__}: {exc}"
                )
                continue

            for table_index, table in enumerate(tables):
                if not table:
                    continue

                cleaned_rows = [
                    [_PDF_DISCOVERY["norm"](cell) for cell in row]
                    for row in table
                    if row is not None
                ]
                cleaned_rows = [
                    row for row in cleaned_rows
                    if _PDF_DISCOVERY["row_values"](row)
                ]

                if len(cleaned_rows) < 2:
                    continue

                heading_hint = _PDF_DISCOVERY["extract_heading_hint"](
                    page_text, cleaned_rows
                )

                analysis = _PDF_DISCOVERY["analyze_table"](
                    cleaned_rows,
                    heading_hint,
                    page_text,
                    [],  # Group-2 handoff is support only, not source.
                )

                if not (analysis["candidate"] or analysis["review"]):
                    continue

                candidate_id = (
                    "g4pdf_"
                    + _PDF_DISCOVERY["identifier"](
                        base["report_id"],
                        page_number,
                        table_index,
                        heading_hint,
                    )
                )

                source = {
                    **base,
                    "pdf_candidate_id": candidate_id,
                    "source_path": str(path),
                    "page_number": page_number,
                    "table_index_on_page": table_index,
                    "source_heading_hint": heading_hint,
                    "family_candidate": analysis["family"],
                    "component_candidate": analysis["component"],
                    "table_orientation_candidate": analysis["orientation"],
                    "discovery_score": analysis["score"],
                    "numeric_axis_row_count": analysis["numeric_row_count"],
                    "numeric_axis_column": analysis["numeric_axis_column"],
                    "transposed_axis_detected":
                        analysis["transposed_axis_detected"],
                    "transposed_axis_row": analysis["transposed_axis_row"],
                    "transposed_sample_count": analysis["transposed_sample_count"],
                    "buffer_axis_detected": analysis["buffer_axis"],
                    "time_header_match_count": analysis["time_header_count"],
                    "signal_header_match_count": analysis["signal_header_count"],
                    "modal_populated_width": analysis["modal_width"],
                    "modal_width_row_count": analysis["modal_width_count"],
                    "group2_handoff_page_support": False,
                    "group2_handoff_match_count": 0,
                    "group2_handoff_headings_json": "[]",
                    "discovery_reasons": "|".join(analysis["reasons"]),
                    "source_rows_json": json.dumps(
                        cleaned_rows, ensure_ascii=False
                    ),
                    "page_text_context":
                        _PDF_DISCOVERY["norm"](page_text)[:4000],
                }

                if analysis["candidate"]:
                    candidates.append(source)
                else:
                    reviews.append(source)

    return candidates, reviews, errors


def _pdf_structured(path: Path, identity: dict[str, Any]):
    candidates, reviews, discovery_errors = _pdf_discover(path, identity)

    accepted = []
    companions = []
    excluded = []
    unresolved = []
    graphical = []

    for source in candidates + reviews:
        audit_fields = _PDF_AUDIT["audit_table"](source)
        audited = {**source, **audit_fields}
        decision = audited.get("decision", "")

        if decision == "accept":
            accepted.append(audited)

        elif decision == "companion":
            companions.append(audited)

        elif decision == "exclude":
            excluded.append(audited)

        elif decision == "review":
            resolution = _PDF_RESOLVE["resolve_table"](audited)
            resolved = {**audited, **resolution}

            rdecision = resolution.get(
                "resolution_decision",
                "",
            )

            if rdecision == "graphical_review":
                graphical.append(resolved)

            elif rdecision == "companion":
                companions.append(resolved)

            elif rdecision == "exclude":
                excluded.append(resolved)

            else:
                unresolved.append(resolved)

        else:
            unresolved.append({
                **audited,
                "resolution_reason":
                    f"unexpected_pdf_audit_decision:{decision}",
            })

    registry = []
    signals = []
    samples = []
    values = []
    issues = list(discovery_errors)

    for source in accepted:
        candidate_id = _PDF_EXTRACT["norm"](
            source.get("pdf_candidate_id", "")
        )
        orientation = _PDF_EXTRACT["norm"](
            source.get("audited_orientation", "")
        )
        source_rows = _PDF_EXTRACT["load_rows"](
            source.get("source_rows_json", "")
        )
        series_id = (
            "g4pdf_"
            + _PDF_EXTRACT["identifier"](
                source.get("report_id", ""),
                candidate_id,
                source.get("page_number", ""),
                source.get("table_index_on_page", ""),
            )
        )

        try:
            if orientation == "samples_by_rows":
                parsed = _PDF_EXTRACT["parse_samples_by_rows"](
                    source, source_rows, series_id
                )
            elif orientation == "samples_by_columns":
                parsed = _PDF_EXTRACT["parse_samples_by_columns"](
                    source, source_rows, series_id
                )
            else:
                raise ValueError(
                    f"Unsupported audited orientation: {orientation}"
                )
        except Exception as exc:
            issues.append(
                f"{source.get('report_id','')} | page "
                f"{source.get('page_number','')} | "
                f"{type(exc).__name__}: {exc}"
            )
            continue

        signals.extend(parsed["signals"])
        samples.extend(parsed["samples"])
        values.extend(parsed["values"])

        registry.append({
            **{k: source.get(k, "") for k in (
                "report_id", "case_id", "vehicle_number", "export_basename"
            )},
            "series_id": series_id,
            "pdf_candidate_id": candidate_id,
            "source_format": "pdf",
            "source_path": source.get("source_path", ""),
            "page_number": source.get("page_number", ""),
            "table_index_on_page": source.get("table_index_on_page", ""),
            "source_heading_hint": source.get("source_heading_hint", ""),
            "family": source.get("audited_family", ""),
            "component": source.get("audited_component", ""),
            "table_orientation": orientation,
            "axis_type": parsed["axis_type"],
            "axis_label_raw": parsed["axis_label_raw"],
            "axis_unit_raw": parsed["axis_unit_raw"],
            "header_row_index": parsed["header_row_index"],
            "axis_column_index": parsed["axis_column_index"],
            "sample_count": parsed["sample_count"],
            "signal_count": parsed["signal_count"],
            "transposed_block_count":
                parsed.get("transposed_block_count", ""),
            "table_part_index":
                _PDF_EXTRACT["as_int_or_blank"](
                    source.get("table_part_index", "")
                ),
            "table_part_total":
                _PDF_EXTRACT["as_int_or_blank"](
                    source.get("table_part_total", "")
                ),
            "continuation_candidate_key":
                source.get("continuation_candidate_key", ""),
            "continuation_merge_status":
                "candidate_not_merged"
                if _PDF_EXTRACT["norm"](
                    source.get("continuation_candidate_key", "")
                )
                else "not_applicable",
            "group2_handoff_page_support":
                source.get("group2_handoff_page_support", ""),
            "processing_status": "structured_extracted",
            "semantic_normalization_status": "not_normalized",
            "unit_conversion_status": "not_converted",
        })

    companion_rows = _PDF_EXTRACT["build_companion_rows"](companions)

    return Group4ExtractionResult(
        source_format="pdf",
        source_path=str(path),
        series=registry,
        signals=signals,
        samples=samples,
        values=values,
        companion_metadata=companion_rows,
        graphical_review=graphical,
        excluded=excluded,
        unresolved=unresolved,
        issues=issues,
    )


def extract_group4_csv(path, identity):
    return _csv_structured(Path(path), identity)


def extract_group4_pdf(path, identity):
    return _pdf_structured(Path(path), identity)


def extract_group4_report(*, identity, csv_path=None, pdf_path=None):
    source_format, source_path = select_group4_source(
        csv_path=csv_path,
        pdf_path=pdf_path,
    )
    if source_format == "csv":
        return extract_group4_csv(source_path, identity)
    return extract_group4_pdf(source_path, identity)
